  const Q = [
    // basics
    { id: 'rlnc', tag: 'hoodi', src: 'intro', q: 'What does RLNC, the technology inside Optimum, stand for?', a: ['Random Linear Network Coding', 'Rapid Ledger Node Consensus', 'Recursive Lattice Number Cryptography', 'Reliable Layered Network Caching'], why: 'Random Linear Network Coding mixes pieces of a message into random linear combinations, so receivers only need enough independent pieces, not specific ones.' },
    { id: 'notchain', tag: 'hoodi', src: 'home', q: 'Is Optimum a blockchain with its own consensus?', a: ['No, it is a network that runs alongside blockchains at the propagation layer', 'Yes, a proof of stake layer 1', 'Yes, an Ethereum rollup', 'It replaces Ethereum consensus'], why: 'Optimum says it operates alongside blockchains and only at the propagation layer: it moves data faster, it does not order or execute transactions.' },
    { id: 'noconsensus', tag: 'hoodi', src: 'home', q: 'What does Ethereum need to change in its consensus rules to use mump2p?', a: ['Nothing, no consensus changes are needed', 'A hard fork', 'A new block size limit', 'A switch back to proof of work'], why: 'Optimum lists "No consensus changes" as a design point. It speeds up how messages travel, not what the chain agrees on.' },
    { id: 'sidecar', tag: 'hoodi', src: 'home', q: 'How does a validator run mump2p?', a: ['As a sidecar next to its existing Ethereum client', 'By replacing its consensus client', 'By moving to a new chain', 'Only through a centralized relay'], why: 'mump2p runs as a sidecar alongside the client a validator already uses, so there is no client swap.' },
    { id: 'hoodi150', tag: 'hoodi', src: 'home', q: 'What average block propagation time does Optimum report on the Hoodi testnet?', a: ['About 150 ms', 'About 4 seconds', 'About 12 seconds', 'About 1 ms'], why: 'Optimum reports about 150 ms average block propagation on Hoodi, which it calls at least 6x faster than Gossipsub.', vol: true },
    { id: 'slot', tag: 'mainnet', src: 'eth', q: 'How long is one Ethereum slot, the window in which a block should be proposed and attested?', a: ['12 seconds', '1 second', '1 minute', '10 minutes'], why: 'Ethereum slots are 12 seconds. A block that arrives late eats into the time validators have to attest, which is why propagation speed matters.' },
    { id: 'agnostic', tag: 'hoodi', src: 'home', q: 'Is mump2p built only for Ethereum?', a: ['No, Optimum calls it chain agnostic by design', 'Yes, it only works on Ethereum', 'It only works on Bitcoin', 'It only works on Solana'], why: 'Optimum describes the network as chain agnostic by design. Ethereum is where it started.' },
    { id: 'what', tag: 'blob', src: 'intro', q: 'What kinds of data does mump2p propagate?', a: ['Blocks, blobs and transactions', 'Only smart contract code', 'Only NFT images', 'Private keys'], why: 'The docs describe mump2p as RLNC accelerated pub/sub for fast propagation of blocks, blobs and transactions.' },
    { id: 'compat', tag: 'flood', src: 'intro', q: 'mump2p is designed to be compatible with which existing protocol?', a: ['libp2p Gossipsub', 'Kafka', 'MQTT', 'BitTorrent'], why: 'The docs call mump2p libp2p and Gossipsub compatible pub/sub, so it fits next to the networking that Ethereum clients already use.' },
    // gossipsub vs mump2p
    { id: 'fullcopies', tag: 'flood', src: 'paper', q: 'How does plain Gossipsub move a block between peers?', a: ['It sends complete copies of the full message', 'It sends coded shards', 'It sends only a hash and no data', 'It routes everything through one server'], why: 'Gossipsub forwards whole messages, so the same block reaches a peer from several neighbours. Those repeats are the Dupes in this game.' },
    { id: 'dupuseless', tag: 'flood', src: 'paper', q: 'Why is a duplicate copy of a block wasted bandwidth?', a: ['It carries no information the peer does not already have', 'It is always corrupted', 'It is encrypted with the wrong key', 'It is larger than the original'], why: 'A second identical copy adds nothing. With RLNC a fresh coded shard almost always adds new information, so less traffic is wasted.' },
    { id: 'bw', tag: 'flood', src: 'home', q: 'How much bandwidth reduction versus Gossipsub does Optimum claim?', a: ['About 90 to 95%', 'About 10%', 'About 50%', 'None, it trades bandwidth for speed'], why: 'Optimum claims about 90 to 95% less bandwidth than Gossipsub, mostly by not sending redundant full copies.', vol: true },
    { id: 'speedx', tag: 'stress', src: 'home', q: 'How much faster block and blob delivery than Gossipsub does Optimum claim?', a: ['6 to 20x faster', '2x faster', '100x faster', 'The same speed, only cheaper'], why: 'Optimum claims 6 to 20x faster block and blob delivery versus Gossipsub.', vol: true },
    { id: 'idontwant', tag: 'flood', src: 'p2p', q: 'What is the idea behind an IDONTWANT control message?', a: ['Telling peers not to send data you already have', 'Asking to leave the network', 'Rejecting an invalid block', 'Requesting a validator exit'], why: 'IDONTWANT lets a peer say it already has a message, so neighbours skip sending it. mump2p uses IDONTWANT, IHAVE and IWANT control messages.' },
    // shards and threshold
    { id: 'kshards', tag: 'shard', src: 'p2p', q: 'A message is split into k fragments and coded into n shards. How many shards does a node need to rebuild it?', a: ['Any k linearly independent shards', 'All n shards', 'Exactly the first k that were sent', '2k shards'], why: 'Any k independent coded shards are enough. It does not matter which ones arrive, which is why coded shields in this game care about different shooters, not specific ones.' },
    { id: 'shardfactor', tag: 'shard', src: 'params', q: 'What is the default shard factor in mump2p (shards per message)?', a: ['4', '1', '16', '64'], why: 'The gateway config sets DefaultShardFactor to 4: a message is split into 4 base fragments before coding (yaml key rlnc_shard_factor).' },
    { id: 'threshold', tag: 'shard', src: 'params', q: 'What fraction of a message\'s shards does a mump2p relay need by default before it forwards recoded shards?', a: ['75%', '100%', '25%', '50%'], why: 'DefaultForwardShardThreshold is 0.75 in the gateway config: a relay forwards a recoded shard once it holds more than 0.75 times the shard factor. Decoding still needs k independent shards.' },
    { id: 'shardmult', tag: 'shard', src: 'params', q: 'What does the mump2p publisher shard multiplier (default 1.2) control?', a: ['How many extra coded shards a publisher creates', 'How many peers are in the mesh', 'How long messages are stored', 'The block reward'], why: 'PublisherShardMultiplier is a redundancy multiplier: a publisher creates ShredFactor times 1.2 coded shards, so losses can be absorbed.', vol: true },
    { id: 'field', tag: 'shard', src: 'p2p', q: 'In RLNC, coded shards are random linear combinations over what?', a: ['A finite field', 'Real numbers', 'Hashes of the blockchain', 'Random English words'], why: 'The docs describe coding as random linear combinations over a finite field. Any k independent combinations are enough to solve for the original pieces.' },
    { id: 'recode', tag: 'shard', src: 'p2p', q: 'What can a mump2p relay do with shards before it has the whole message?', a: ['Recode them into a new coded shard and forward it', 'Nothing until it decodes the full message', 'Only delete duplicates', 'Only forward the original publisher shards'], why: 'Any node can create a new coded shard from the shards it holds without decoding first. Muriel, the Recoder, does exactly this in the game.' },
    { id: 'thresholdfwd', tag: 'shard', src: 'p2p', q: 'When does a mump2p relay start forwarding recoded shards?', a: ['Once its shard count passes a forwarding threshold', 'Only after it decodes the block', 'Only every 12 seconds', 'Only when the publisher asks'], why: 'Relays forward recoded shards once they hold more than the ForwardShardThreshold, so data keeps moving without waiting for the full message.' },
    { id: 'rsvsrlnc', tag: 'shard', src: 'codes', q: 'What can RLNC do that classic Reed Solomon codes cannot do mid route?', a: ['Recode at intermediate nodes without decoding', 'Encrypt the data', 'Compress the data', 'Sign the data'], why: 'With Reed Solomon a relay must decode before it can re encode. RLNC relays mix what they have and pass it on immediately.' },
    { id: 'erasure', tag: 'subsea', src: 'product', q: 'Optimum describes RLNC as an advanced form of which coding?', a: ['Erasure coding', 'Hashing', 'Encryption', 'Compression'], why: 'RLNC is erasure coding: data is turned into coded chunks so missing chunks can be made up by any other independent ones.' },
    // loss
    { id: 'loss', tag: 'subsea', src: 'p2p', q: 'With RLNC, what happens if one coded shard is lost on the way?', a: ['Any other independent shard can replace it', 'The exact same shard must be resent', 'The whole block is dropped', 'The validator is slashed'], why: 'Because any k independent shards work, a lost shard is replaced by whichever new one arrives. No specific resend is needed.' },
    { id: 'randomuseful', tag: 'subsea', src: 'paper', q: 'Why is a freshly coded random shard almost always useful to the receiver?', a: ['Random combinations are very likely independent of what it already has', 'It is always the first shard', 'It contains the whole message', 'It carries a validator signature'], why: 'Random linear combinations are independent with high probability, so new coded shards rarely duplicate what a peer already holds.' },
    { id: 'zeroloss', tag: 'stress', src: 'testnet', q: 'In early A/B tests, what did Optimum report about message loss in stress scenarios?', a: ['Zero message loss', 'About 50% loss', 'Loss was the same as Gossipsub', 'Loss was not measured'], why: 'The testnet announcement reports zero message loss during stress scenarios.' },
    // mesh
    { id: 'mesh6', tag: 'mesh', src: 'params', q: 'What is the default target mesh size (peers) in mump2p?', a: ['6', '2', '50', '1'], why: 'The gateway config sets DefaultMeshDegreeTarget to 6 peers, the same degree Gossipsub uses. In Mesh Limits, hiring 6 crew gives the speed bonus.' },
    { id: 'meshmin', tag: 'mesh', src: 'params', q: 'Below how many mesh peers does a mump2p node look for more?', a: ['4', '1', '6', '12'], why: 'The gateway config sets DefaultMeshDegreeMin to 4: below that the node grafts new peers into its mesh.' },
    { id: 'meshmax', tag: 'mesh', src: 'params', q: 'Above how many mesh peers does a mump2p node start pruning?', a: ['12', '6', '24', '100'], why: 'The gateway config sets DefaultMeshDegreeMax to 12, which is why Mesh Limits caps your crew at 12.' },
    { id: 'pubsub', tag: 'mesh', src: 'cli', q: 'In the mump2p CLI, which two commands send and receive messages on a topic?', a: ['publish and subscribe', 'push and pull', 'mint and burn', 'stake and unstake'], why: 'mump2p is pub/sub: you publish to a topic and subscribe to it.' },
    // flexnodes and products
    { id: 'flexnodes', tag: 'flex', src: 'intro', q: 'What are Flexnodes?', a: ['Permissionless nodes that encode, decode and forward RLNC coded frames', 'A hardware wallet', 'An NFT collection', 'Ethereum execution clients'], why: 'Flexnodes are permissionless nodes that encode, decode and forward RLNC coded gossip frames, keep bounded coded buffers to recover loss and work with existing clients.' },
    { id: 'flexreward', tag: 'flex', src: 'product', q: 'What do Flexnode operators earn rewards for?', a: ['Contributing bandwidth', 'Mining blocks with GPUs', 'Holding NFTs', 'Voting on governance'], why: 'Optimum describes Flexnodes as a global network of data accelerators whose operators earn rewards for contributing bandwidth.' },
    { id: 'deram', tag: 'flex', src: 'product', q: 'What does DeRAM, on Optimum\'s product roadmap, stand for?', a: ['Decentralized Random Access Memory', 'Delegated Restaking Asset Manager', 'Decentralized Rollup Archive Module', 'Decoded RLNC Access Mesh'], why: 'DeRAM is described as high speed state reads and writes for latency sensitive applications.' },
    { id: 'derom', tag: 'flex', src: 'product', q: 'What is DeROM meant to be?', a: ['Immutable, globally ordered archival storage', 'A faster consensus client', 'A token bridge', 'A gas fee oracle'], why: 'DeROM, Decentralized Read Only Memory, is described as an immutable, globally ordered archival storage layer.' },
    { id: 'live', tag: 'flex', src: 'product', q: 'Which Optimum product does the product page list as live now?', a: ['mump2p', 'DeRAM', 'DeROM', 'None yet'], why: 'mump2p is live. DeRAM and DeROM are listed as coming soon.', vol: true },
    // gateway
    { id: 'gwclients', tag: 'gateway', src: 'gateway', q: 'Which clients does Optimum Gateway connect to mump2p?', a: ['Prysm, Lighthouse, Nimbus, Teku and Lodestar', 'Geth, Nethermind, Besu and Erigon', 'MetaMask and Rabby', 'Bitcoin Core'], why: 'The Gateway serves Ethereum consensus layer clients. Geth and friends are execution clients, a different layer.' },
    { id: 'gwnochange', tag: 'gateway', src: 'gateway', q: 'What do consensus clients have to change to use Optimum Gateway?', a: ['Nothing, they simply peer with the gateway', 'Their fork choice rule', 'Their validator keys', 'Their database'], why: 'No client changes are needed: the gateway subscribes to their gossip, carries it over the RLNC mesh and re injects it.' },
    { id: 'gwnets', tag: 'gateway', src: 'gateway', q: 'Which Ethereum networks does the Gateway support?', a: ['Hoodi and Mainnet', 'Only Bitcoin', 'Only Solana devnet', 'Only private chains'], why: 'The gateway config supports Hoodi and Mainnet.' },
    { id: 'gwdedup', tag: 'gateway', src: 'gateway', q: 'How does the Gateway avoid passing the same message twice?', a: ['A short lived cache of message fingerprints (about a minute)', 'A vote among validators', 'An onchain transaction per message', 'It drops every second message'], why: 'The gateway deduplicates with a TTL cache of about one minute using fast hash fingerprints.' },
    { id: 'cl', tag: 'gateway', src: 'gateway', q: 'Block gossip on Ethereum happens between which kind of clients?', a: ['Consensus layer clients', 'Wallets', 'Block explorers', 'Exchanges'], why: 'Blocks and attestations are gossiped by consensus layer clients over libp2p, which is where the gateway plugs in.' },
    // testnet and validators
    { id: 'tenx', tag: 'stress', src: 'testnet', q: 'In early A/B tests, how did OptimumP2P latency compare with Gossipsub under high traffic?', a: ['About 10x lower', 'About the same', 'About 2x higher', 'It was not tested'], why: 'The testnet announcement reports about 10x lower latency under high traffic.', vol: true },
    { id: 'fourmb', tag: 'blob', src: 'testnet', q: 'In those tests, at what message size did Gossipsub start failing under high arrival rates?', a: ['4 MB', '4 KB', '400 MB', 'It never failed'], why: 'Gossipsub failed at 4 MB under high arrival rates while OptimumP2P stayed stable up to 10 MB.' },
    { id: 'tenmb', tag: 'blob', src: 'testnet', q: 'Up to what message size did OptimumP2P stay stable in those tests?', a: ['10 MB', '1 KB', '100 KB', '1 GB'], why: 'OptimumP2P handled messages up to 10 MB in the reported tests.' },
    { id: 'stake15', tag: 'mainnet', src: 'testnet', q: 'At the testnet launch, the seven validator operators testing OptimumP2P represented about what share of Ethereum stake?', a: ['About 15%', 'About 1%', 'About 50%', 'About 90%'], why: 'Seven large operators, together about 15% of total stake, took part in testing.', vol: true },
    { id: 'benefits', tag: 'mainnet', src: 'product', q: 'Which of these does Optimum list as a benefit for validators?', a: ['More attestation rewards', 'Higher gas fees for users', 'Longer block times', 'Needing fewer validators'], why: 'Optimum lists more attestation rewards, better MEV opportunities and fewer missed proposals. Faster blocks mean more on time votes.' },
    { id: 'missed', tag: 'mainnet', src: 'blogapr', q: 'Why would faster propagation mean fewer missed proposals?', a: ['A proposer\'s block reaches others before the deadline', 'Blocks get smaller', 'Validators get more stake', 'Fees go down'], why: 'A block that spreads too slowly can miss the attestation window. Speed is money: late data costs rewards.' },
    // people
    { id: 'medard', tag: 'hoodi', src: 'product', q: 'Who co invented RLNC in her MIT lab and co founded Optimum?', a: ['Prof. Muriel Médard', 'Vitalik Buterin', 'Satoshi Nakamoto', 'Ada Lovelace'], why: 'Prof. Muriel Médard co invented RLNC at MIT and is Optimum\'s CEO.' },
    { id: 'flp', tag: 'mainnet', src: 'flp', q: 'Optimum advisor Nancy Lynch is the L in which famous distributed systems result?', a: ['The FLP impossibility result', 'The CAP theorem', 'Paxos', 'Proof of history'], why: 'Fischer, Lynch and Paterson showed in 1985 that no deterministic protocol can guarantee consensus in an asynchronous system with even one faulty process. Optimum\'s team page highlights her 1985 BFT proof and the 1988 DLS algorithm.' },
    { id: 'slogan', tag: 'mainnet', src: 'home', q: 'Complete Optimum\'s line: "Data movement sets the ceiling. ..."', a: ['Optimum raises it.', 'Blockchains break it.', 'Validators ignore it.', 'Fees decide it.'], why: '"Data movement sets the ceiling. Optimum raises it." The idea: propagation limits everything built on top.' },

    // the team behind the crew
    { id: 'hamming', tag: 'hoodi', src: 'hamming', q: 'Which IEEE medal did Prof. Muriel Médard receive in 2026?', a: ['The Richard W. Hamming Medal', 'The Turing Award', 'The Fields Medal', 'The Nobel Prize in Physics'], why: 'The Hamming Medal honours exceptional contributions to information sciences. Muriel, the Recoder in your crew, is named after her.' },
    { id: 'nae', tag: 'hoodi', src: 'team', q: 'In which year was Muriel Médard elected to the US National Academy of Engineering?', a: ['2020', '1999', '2010', '2025'], why: 'The team page lists National Academy of Engineering membership in 2020, alongside fellowships of the IEEE and the American Academy of Arts and Sciences.' },
    { id: 'itsoc', tag: 'shard', src: 'team', q: 'Muriel Médard is a former president of which society?', a: ['The IEEE Information Theory Society', 'The Ethereum Foundation', 'The Linux Foundation', 'The Royal Society of Chemistry'], why: 'Information theory is the maths of how much data must move, which is exactly what RLNC optimizes.' },
    { id: 'kentclub', tag: 'mainnet', src: 'team', q: 'Optimum co-founder Kent Lin, the Flexnode Bank in your crew, was president of which club?', a: ['Harvard Blockchain Club', 'MIT Bitcoin Club', 'Stanford Crypto Society', 'Oxford Ethereum Society'], why: 'Kent Lin leads business development, tokenomics and fundraising, and was a Partner at GSRV before Optimum.', vol: true },
    { id: 'kishmeta', tag: 'shard', src: 'team', q: 'Before co-founding Optimum, Dr. Kishori Konwar was a senior engineer and scientist at which company?', a: ['Meta', 'Google', 'Apple', 'Amazon'], why: 'He also did a postdoc in network coding at MIT and worked as a quant at Goldman Sachs. Kishori, your Encoder, is named after him.' },
    { id: 'kishpostdoc', tag: 'shard', src: 'team', q: 'Where did Kishori Konwar do his postdoctoral work in network coding?', a: ['MIT', 'ETH Zurich', 'Caltech', 'Oxford'], why: 'Optimum grew out of years of network coding research at MIT.' },
    { id: 'dls', tag: 'mainnet', src: 'team', q: 'Optimum\'s team page says the DLS algorithm co-created by Nancy Lynch is a basis for what?', a: ['Tendermint and Ethereum consensus', 'Bitcoin mining', 'Zero knowledge proofs', 'IPFS storage'], why: 'DLS (Dwork, Lynch, Stockmeyer, 1988) studied consensus with partial synchrony, the setting most proof of stake protocols live in.' },
    { id: 'sriram', tag: 'stress', src: 'team', q: 'Which research areas does Optimum advisor Sriram Vishwanath work in?', a: ['Information theory, wireless communications and network science', 'Smart contract auditing', 'GPU mining hardware', 'Token design only'], why: 'He is your guide on the Stress Test stage. Decoding under heavy load is information theory at work.' },
    { id: 'jeff', tag: 'flood', src: 'jeff', q: 'Who introduced himself in 2025 as Optimum\'s new community manager?', a: ['Jeff (@blockchainjeff)', 'Vitalik Buterin', 'Kent Lin', 'Satoshi Nakamoto'], why: 'Jeff joined after about eight years building Web3 communities. Jeff, your crowd clearing Flood Breaker, is named after him.', vol: true },
    { id: 'gmum', tag: 'flood', src: 'jeff', q: 'What is the Optimum community\'s version of "gm"?', a: ['GMUM', 'GMOON', 'WAGMI', 'GN'], why: 'Optimum\'s community manager opened his first post with GMUM and the community greets each other with it. It is also how the game greets you on X.' },
    { id: 'founders', tag: 'hoodi', src: 'team', q: 'Who are Optimum\'s three co-founders?', a: ['Muriel Médard, Kent Lin and Kishori Konwar', 'Nancy Lynch, Sriram Vishwanath and Jeff', 'Vitalik Buterin, Gavin Wood and Joe Lubin', 'Muriel Médard, Nancy Lynch and Kent Lin'], why: 'The team page lists Médard (CEO), Lin and Konwar as co-founders, with Nancy Lynch and Sriram Vishwanath as advisors.', vol: true },
    { id: 'advisors', tag: 'mainnet', src: 'team', q: 'Which two professors does Optimum list as advisors?', a: ['Nancy Lynch and Sriram Vishwanath', 'Muriel Médard and Kishori Konwar', 'Kent Lin and Jeff', 'Silvio Micali and Dan Boneh'], why: 'Nancy is the Throttle in your crew who exposes eclipse attackers, and Sriram guides the Stress Test stage.', vol: true },
    { id: 'mitinc', tag: 'hoodi', src: 'seed', q: 'Optimum came out of research at which university?', a: ['MIT', 'Harvard', 'Stanford', 'Cambridge'], why: 'Optimum was incubated at MIT, building on years of network coding research there.' },
    { id: 'seed11', tag: 'mainnet', src: 'seed', q: 'How much did Optimum raise in its 2025 seed round?', a: ['$11 million', '$1 million', '$110 million', '$1 billion'], why: 'Optimum announced an $11M seed round in April 2025.' },
    // more on how mump2p works
    { id: 'nodecode', tag: 'shard', src: 'p2p', q: 'Does a mump2p relay have to decode a message before forwarding anything?', a: ['No, it can recode and forward what it holds', 'Yes, always', 'Only for blobs', 'Only on mainnet'], why: 'Not waiting to decode is the big latency win: shards keep flowing hop after hop.' },
    { id: 'publisher', tag: 'mesh', src: 'p2p', q: 'How does a mump2p publisher hand out the coded shards of a new message?', a: ['Different coded shards to different peers, round robin', 'It waits for a vote first', 'All shards to one random peer', 'It stores them until the next slot'], why: 'The docs say a publisher sends different coded shards to different peers in round robin fashion. A node that gets a shard straight from the publisher forwards it to all its mesh peers at once; later hops forward recoded shards once they pass the threshold.' },
    { id: 'innovative', tag: 'shard', src: 'p2p', q: 'A coded shard that is a combination of shards you already hold is...', a: ['Linearly dependent: it brings no new information', 'Twice as useful', 'Invalid and slashed', 'Enough to decode alone'], why: 'Only linearly independent shards move you toward decoding. That is why repeat hits from the same crew member barely dent a coded shield.' },
    { id: 'rateless', tag: 'subsea', src: 'codes', q: 'In Optimum\'s "Battle of the Codes" post, which family is described as rateless, with no predefined redundancy?', a: ['Fountain codes', 'Reed Solomon codes', 'Parity bits', 'Hash functions'], why: 'Fountain codes are rateless. Reed Solomon fixes its redundancy up front. The post\'s key point: only RLNC can recode at relays without decoding first.' },
    { id: 'ihave', tag: 'flood', src: 'gossipsub', q: 'In gossip protocols like Gossipsub, what does an IHAVE message do?', a: ['Announces message IDs a peer has seen', 'Sends the full block', 'Bans a peer', 'Proposes a new block'], why: 'IHAVE gossips IDs; a peer that is missing one answers with IWANT. mump2p uses the same family of control messages.' },
    { id: 'ssz', tag: 'gateway', src: 'gateway', q: 'Ethereum consensus messages that the Gateway re-encodes use which serialization format?', a: ['SSZ (Simple Serialize)', 'JSON', 'XML', 'Protocol Buffers'], why: 'Consensus clients gossip SSZ encoded, snappy compressed messages. The gateway re-encodes them so clients see exactly what they expect.' },
    { id: 'gwtopics', tag: 'gateway', src: 'gateway', q: 'What does the Gateway subscribe to on the client side?', a: ['The consensus layer gossip topics', 'Wallet transactions only', 'Exchange order books', 'Social media feeds'], why: 'It listens on the /eth2/... gossip topics, carries the traffic over the RLNC mesh and re-injects it locally.' },
    { id: 'noinfra', tag: 'gateway', src: 'product', q: 'What infrastructure change does Optimum say validators need for mump2p?', a: ['None: no infrastructure changes are required', 'New GPUs', 'A dedicated fibre line', 'A second validator key'], why: 'Optimum lists "No infrastructure changes required" among the validator benefits.' },
    { id: 'deramuse', tag: 'flex', src: 'product', q: 'What kind of applications is DeRAM aimed at?', a: ['Latency sensitive apps that need fast state reads and writes', 'Long term cold storage only', 'Mining pools', 'Hardware wallets'], why: 'DeRAM is described as high speed state reads and writes for latency sensitive applications. DeROM covers archival storage.' },
    { id: 'foundation', tag: 'mainnet', src: 'home', q: 'Complete Optimum\'s line: "Fix the foundation. ..."', a: ['Everything above it improves.', 'Then fork the chain.', 'Ignore the apps.', 'Raise the fees.'], why: 'The foundation is data propagation: when blocks move faster, every layer above benefits.' },
    { id: 'layer', tag: 'gateway', src: 'home', q: 'At which layer of the stack does Optimum work?', a: ['The data propagation (networking) layer', 'The application layer only', 'The wallet layer', 'The token layer'], why: 'Optimum moves data between nodes. It does not execute transactions or run consensus.' },
    // Ethereum context
    { id: 'epoch', tag: 'mainnet', src: 'eth', q: 'How many slots make one Ethereum epoch?', a: ['32', '12', '64', '100'], why: 'An epoch is 32 slots of 12 seconds, about 6.4 minutes. Validators attest once per epoch.' },
    { id: 'attest', tag: 'mainnet', src: 'eth', q: 'What does a validator do once every epoch?', a: ['Attests: votes on the chain head it sees', 'Mines a block with GPUs', 'Withdraws its stake', 'Changes its keys'], why: 'Attestations need the latest block in time. A slow block means a late or wrong vote and lost rewards.' },
    { id: 'hoodinet', tag: 'hoodi', src: 'ethnets', q: 'What is Hoodi?', a: ['A public Ethereum testnet for validators and staking', 'An Optimum token', 'A Layer 2 rollup', 'A hardware wallet'], why: 'Hoodi is an Ethereum testnet built for validator and staking testing, the first stage of this game.' },
    { id: 'blobs4844', tag: 'blob', src: 'danksharding', q: 'Which Ethereum proposal introduced blobs?', a: ['EIP-4844 (proto-danksharding)', 'EIP-1559', 'The Merge', 'EIP-20'], why: 'Blobs are large chunks of data for rollups, added by EIP-4844. Bigger data makes fast propagation even more important.' },
    { id: 'mevname', tag: 'mainnet', src: 'mev', q: 'What does MEV stand for?', a: ['Maximal extractable value', 'Minimum execution volume', 'Mempool encryption vault', 'Multi validator election'], why: 'MEV is value captured by ordering transactions in a block. Optimum lists better MEV opportunities among the benefits of faster data.' },

    // the people in your crew and stage guides
    { id: 'swarna', tag: 'gateway', src: 'bloghoodi', q: 'Swarna, your Long Haul sniper, is named after the author of which Optimum analysis?', a: ['The 6x latency win of mump2p on the Hoodi testnet', 'The Ethereum yellow paper', 'The Bitcoin white paper', 'A token unlock schedule'], why: 'Swarnabha Sinha measured every Hoodi block through both mump2p and Gossipsub at once and found about 150 ms against roughly 1 second.' },
    { id: 'sajida', tag: 'mainnet', src: 'blogpbs', q: 'Sajida, your Decoder, is named after the author of which Optimum research post?', a: ['The cost of uncertainty in Ethereum\'s PBS hot path', 'A guide to NFT minting', 'A Solana validator setup guide', 'The Optimum token whitepaper'], why: 'Sajida Zouarhi showed how unreliable delivery, not just average speed, costs validators money in proposer builder separation.' },
    { id: 'paperauthors', tag: 'stress', src: 'paper', q: 'The OptimumP2P research paper lists most of its authors at which location?', a: ['Optimum, Cambridge, MA', 'Ethereum Foundation, Zug', 'Google, Mountain View', 'CERN, Geneva'], why: 'Eleven authors are listed at Optimum in Cambridge, Massachusetts, with Sriram Vishwanath at Georgia Tech. Many of them guide the stages in this game.' },
    { id: 'guides', tag: 'hoodi', src: 'paper', q: 'Nicolas Nicolaou, Har Preet Singh and Alejandro Bergasov, three of your stage guides, are co-authors of what?', a: ['The OptimumP2P research paper', 'The Ethereum yellow paper', 'The Gossipsub v1.0 spec', 'The Bitcoin white paper'], why: 'The OptimumP2P paper (arXiv 2508.04833) describes the protocol and its experiments against Gossipsub.' },
    // research results
    { id: 'p10mb', tag: 'blob', src: 'paper', q: 'In the OptimumP2P paper, how many 10 MB messages out of 100 did Gossipsub deliver in the stress experiment?', a: ['84', '100', '50', '12'], why: 'OptimumP2P delivered all 100 large messages while Gossipsub dropped 16.' },
    { id: 'p20', tag: 'stress', src: 'paper', q: 'In the paper, what happened to Gossipsub latency at 20 messages per second?', a: ['It degraded sharply to about 4 seconds', 'It dropped to 10 ms', 'It stayed flat', 'The test was skipped'], why: 'Gossipsub saturated at about 4.0 s while OptimumP2P kept delivery within about 1.8 to 2.0 s.' },
    { id: 'hoodi1s', tag: 'hoodi', src: 'bloghoodi', q: 'In the Hoodi analysis, about how long did Gossipsub take on average to propagate a block?', a: ['About 1 second', 'About 150 ms', 'About 12 seconds', 'About 10 ms'], why: 'mump2p averaged about 150 ms against a Gossipsub baseline of about 1 second, the 6x the post calls conservative.', vol: true },
    { id: 'dualpath', tag: 'hoodi', src: 'bloghoodi', q: 'How did Optimum make the Hoodi comparison fair?', a: ['Every block went through both mump2p and Gossipsub at the same time', 'It only tested at night', 'It used different blocks for each protocol', 'It asked validators to guess'], why: 'Each gateway timestamped the same block arriving over both paths under identical network conditions.' },
    { id: 'gw30', tag: 'gateway', src: 'bloghoodi', q: 'How many gateway nodes did the Hoodi measurement use?', a: ['30, spread across the US, EU and Asia', '1, in one data center', '3, all in Europe', '3000, one per validator'], why: 'Globally spread gateways let the test include cross continental hops, where peaks reached about 200 to 250 ms.' },
    { id: 'variance', tag: 'stress', src: 'blogpbs', q: 'Besides faster p95 latency, what does Optimum report about mump2p\'s propagation variance?', a: ['About 7x lower than Gossipsub', 'About the same', 'Higher than Gossipsub', 'It was not measured'], why: 'Consistency matters: validators plan around the slow cases, so less variance means more usable slot time.' },
    { id: 'apr', tag: 'mainnet', src: 'blogapr', q: 'Optimum\'s staking study estimates that cutting propagation latency by 50 to 150 ms could raise major operators\' APR by about how much?', a: ['About 0.66 to 1.97%', 'About 50%', 'Nothing measurable', 'About 0.001%'], why: 'More usable slot time lets proposers see more builder bids and improves head vote accuracy. Speed is money.' },
    { id: 'per50', tag: 'mainnet', src: 'blogapr', q: 'In that study, each extra 50 ms of usable slot time is worth roughly how much more average validator revenue?', a: ['About 0.6 to 0.7%', 'About 6 to 7%', 'About 60%', 'Nothing'], why: 'The biggest driver is MEV bid selection: waiting a little longer lets a proposer pick a higher value block.' },
    { id: 'headvote', tag: 'mainnet', src: 'blogapr', q: 'What network wide head vote accuracy does the study give as today\'s baseline?', a: ['About 98.6%', 'About 50%', 'About 75%', 'Exactly 100%'], why: 'With 50 to 150 ms less latency it rises to about 98.8 to 99.1%, worth about 1000 to 2000 ETH a year across the network.' },
    { id: 'free', tag: 'mainnet', src: 'blogfree', q: 'As of August 2026, what does Optimum charge validators for faster beacon block and attestation propagation?', a: ['Nothing, it is free and Optimum says it will remain free', 'A fee per block', 'A monthly subscription', 'A share of staking rewards'], why: 'Optimum\'s August 2026 post says access to faster blocks and attestations is and will remain free for validators.', vol: true },
    { id: 'extra', tag: 'gateway', src: 'blogfree', q: 'Does mump2p replace Ethereum\'s normal Gossipsub?', a: ['No, it runs as an additional channel alongside standard gossip', 'Yes, it switches Gossipsub off', 'Only on weekends', 'Only for blobs'], why: 'Validators keep standard gossip and get a second, faster path, so nothing breaks if one path is slow.' },
    { id: 'console', tag: 'gateway', src: 'blogfree', q: 'How does a validator connect its gateway to the Optimum network, per the August 2026 post?', a: ['With an API key from Optimum Console', 'By staking a token', 'By editing Ethereum\'s consensus rules', 'By mailing a hardware key'], why: 'The gateway joins the network with an API key generated in Optimum Console, which the August 2026 post said would open publicly the following month.', vol: true },
    { id: 'permissioned', tag: 'flex', src: 'blogfree', q: 'In August 2026, in which phase was the Optimum network running?', a: ['A permissioned phase with 40+ validators and node operators, heading to permissionless', 'Fully permissionless', 'Shut down', 'Only a private lab test'], why: 'Optimum describes a permissioned start with enterprise grade operators and a roadmap toward a permissionless Optimum Network.', vol: true },
    { id: 'widernet', tag: 'flex', src: 'blogfree', q: 'Per Optimum, what happens to propagation as more nodes join an RLNC network?', a: ['It gets faster, because nodes add coded capacity and coverage', 'It gets slower and heavier', 'Nothing changes', 'It stops working'], why: 'In gossip, more nodes can mean more duplicates. With RLNC, extra nodes add useful coded capacity.' },
    { id: 'latmarket', tag: 'flex', src: 'blogflex', q: 'How are Flexnode operators meant to be rewarded?', a: ['Through a latency marketplace for the bandwidth they contribute', 'Through proof of work mining', 'Through NFT royalties', 'They are not rewarded'], why: 'Validators pay for faster delivery, and operators who supply the bandwidth earn from it.', vol: true },
    { id: 'flexhw', tag: 'flex', src: 'blogflex', q: 'What hardware does RLNC powered propagation need, according to the Flexnodes post?', a: ['Very little: any internet connected device could take part', 'A data center GPU cluster', 'ASIC miners', 'A dedicated satellite link'], why: 'Low requirements are part of the decentralization story: many small nodes can add coded capacity.' },
    { id: 'solana', tag: 'stress', src: 'blogsol', q: 'Besides Ethereum, which chain did Optimum write about needing faster data propagation in December 2025?', a: ['Solana', 'Dogecoin', 'Litecoin', 'Monero'], why: 'Optimum is chain agnostic; Swarnabha Sinha\'s post looks at why Solana would benefit too.' },
    // batch A: written from the corpus snapshot of 2026-10-02, every answer backed by a verbatim passage of its source
    {"id": "a_fastest", "tag": "hoodi", "src": "intro", "q": "How does Optimum's own documentation describe Optimum in one line?", "a": ["The fastest decentralized internet protocol for web3", "The first decentralized storage protocol for web3", "The most secure consensus protocol for web3", "The cheapest rollup settlement layer for web3"], "why": "Optimum's intro page calls it the fastest decentralized internet protocol for web3, with speed of data movement as the whole point."},
    {"id": "a_geogossip", "tag": "subsea", "src": "intro", "q": "Across what kind of nodes does Optimum say it accelerates low latency gossip?", "a": ["Geographically distributed nodes", "Nodes inside a single data center", "Nodes on one cloud provider", "Nodes within the same country"], "why": "Optimum speeds up gossip between nodes spread across the globe, so distance and lossy links are exactly the problem it targets."},
    {"id": "a_provopt", "tag": "hoodi", "src": "intro", "q": "Under standard RLNC models, what does Optimum claim about its dissemination strategy?", "a": ["It is provably optimal for throughput and latency under loss and contention", "It is provably secure against any eclipse attack", "It is provably cheaper than any erasure code", "It is provably optimal only on lossless links"], "why": "Optimum's intro says that under standard RLNC models the strategy is provably optimal for throughput and latency when links lose packets or get congested."},
    {"id": "a_rlncgossip", "tag": "flood", "src": "intro", "q": "According to Optimum's intro, what two things does applying RLNC to gossip improve?", "a": ["It reduces redundancy and improves loss tolerance", "It reduces block size and improves finality", "It reduces peer count and improves privacy", "It reduces gas fees and improves staking yield"], "why": "Coded shards replace redundant full copies and any sufficient set of shards decodes, so RLNC cuts waste and survives loss at the same time."},
    {"id": "a_permissionless", "tag": "flex", "src": "intro", "q": "Who can operate a flexnode on the Optimum network?", "a": ["Anyone, since the network is permissionless", "Only validators with 32 ETH staked", "Only operators approved by the Optimum team", "Only partners running a dedicated data center"], "why": "Optimum describes itself as a permissionless network of flexnodes that anyone can run alongside their existing clients and P2P stacks."},
    {"id": "a_adoptnow", "tag": "gateway", "src": "intro", "q": "Through which product can builders and operators adopt mump2p today, per Optimum's intro?", "a": ["The Optimum Gateway", "The Optimum DeRAM console", "A dedicated Optimum consensus client", "The Flexnode marketplace"], "why": "The intro says teams can adopt mump2p now for measurable latency gains via the Optimum Gateway, which is the entry point for existing clients."},
    {"id": "a_memreq", "tag": "flex", "src": "intro", "q": "Besides taking part in coded gossip, what does Optimum's intro say a flexnode serves?", "a": ["Memory requests", "Block proposals", "Attestation aggregation", "DNS lookups"], "why": "A flexnode is an operator run node that joins Optimum's coded gossip and also serves memory requests, pointing at Optimum's memory layer ambitions."},
    {"id": "a_codedbuf", "tag": "subsea", "src": "intro", "q": "Why do flexnodes keep bounded coded buffers, according to Optimum's intro?", "a": ["To recover loss and smooth tail latency", "To cache full blocks for archival sync", "To store validator keys securely", "To batch transactions for lower fees"], "why": "A small buffer of coded shards lets a flexnode fill in lost pieces and keep the slowest deliveries from dragging out the tail."},
    {"id": "a_frames", "tag": "flex", "src": "intro", "q": "What do flexnodes do with RLNC coded gossip frames, per Optimum's intro?", "a": ["Encode, decode, and forward them", "Sign, timestamp, and archive them", "Compress, encrypt, and store them", "Validate, order, and finalize them"], "why": "Flexnodes are the workers of coded gossip: they encode frames, decode them, and forward them onward through the network."},
    {"id": "a_galois", "tag": "hoodi", "src": "p2p", "q": "By what other name does Optimum's documentation call the RLNC based gossip mechanism in mump2p?", "a": ["Galois Gossip", "Fountain Gossip", "Hamming Gossip", "Reed Gossip"], "why": "Optimum's protocol docs call mump2p, the gossip mechanism based on RLNC, Galois Gossip. It builds on libp2p's GossipSub but moves coded shards instead of whole messages."},
    {"id": "a_stdhost", "tag": "hoodi", "src": "p2p", "q": "What is each mump2p node at its core, according to the protocol docs?", "a": ["A standard libp2p host enhanced with RLNC logic", "A modified Ethereum execution client", "A custom UDP relay written from scratch", "A Gossipsub node with coding disabled"], "why": "A mump2p node is simply a libp2p host with RLNC encoding, recoding and decoding added on top, so it stays compatible with the ecosystem."},
    {"id": "a_meshcomp", "tag": "mesh", "src": "p2p", "q": "What does the Mesh Topology component of a mump2p node maintain?", "a": ["A configurable gossip mesh with peer degrees similar to GossipSub", "A fixed ring of exactly six peers", "A full connection to every node in the network", "A star topology around the publisher"], "why": "mump2p keeps GossipSub style peer degrees in its mesh, so operators tune it with the same intuition they already have."},
    {"id": "a_matrixinv", "tag": "shard", "src": "p2p", "q": "What mathematical operation does a mump2p node use to decode a message from k independent shards?", "a": ["Matrix inversion from linear algebra", "Polynomial interpolation over the reals", "Fast Fourier transform", "Merkle root recomputation"], "why": "Once k linearly independent shards arrive, the node solves the linear system by inverting the coefficient matrix to recover the original data."},
    {"id": "a_lenprefix", "tag": "shard", "src": "p2p", "q": "What does mump2p do to a message in the preparation step before encoding it?", "a": ["Adds a length prefix and pads it if necessary", "Compresses it with Snappy", "Encrypts it with the publisher key", "Splits it into fixed 1 KB packets"], "why": "A length prefix and padding make the message fit cleanly into equal fragments, so the decoder knows exactly where the real data ends."},
    {"id": "a_shredfactor", "tag": "mesh", "src": "p2p", "q": "In mump2p's configuration, which parameter is the number of base fragments a message is split into before encoding?", "a": ["ShredFactor", "PublisherShardMultiplier", "ForwardShardThreshold", "MeshDegreeTarget"], "why": "ShredFactor sets how many base fragments a message becomes; the other parameters scale coded shards or control the mesh, not the split."},
    {"id": "a_shredtrade", "tag": "mesh", "src": "p2p", "q": "What is the trade off of a higher ShredFactor in mump2p?", "a": ["More granular sharding but more computational overhead", "Fewer peers but more bandwidth", "Faster decoding but weaker loss tolerance", "Smaller messages but longer mesh warmup"], "why": "Splitting a message into more fragments gives finer grained shards to spread around, but every extra fragment costs more compute to code and decode."},
    {"id": "a_frompub", "tag": "mesh", "src": "p2p", "q": "In mump2p, what does a node do with a shard that arrived directly from the publisher?", "a": ["Forwards it immediately to all mesh peers", "Holds it until k shards are collected", "Decodes it before sending anything", "Drops it and requests a recoded version"], "why": "Shards straight from the publisher are pushed to every mesh peer at once; only shards from other peers wait for the forwarding threshold."},
    {"id": "a_iwant", "tag": "flood", "src": "p2p", "q": "In mump2p, what does the IWANT control message request?", "a": ["Additional shards for a message not yet decoded", "A full copy of a message already decoded", "The peer list of a remote node", "A signature for a suspicious shard"], "why": "A node that still cannot decode a message sends IWANT to ask peers for more coded shards, the shard aware version of GossipSub's IWANT."},
    {"id": "a_graftprune", "tag": "mesh", "src": "p2p", "q": "What do the GRAFT and PRUNE messages do in mump2p?", "a": ["Keep the mesh at its optimal size by adding or removing peers", "Advertise and request coded shards", "Signal that a message has been decoded", "Rate limit a publisher that sends too fast"], "why": "GRAFT pulls a peer into the full message mesh and PRUNE pushes one out, keeping the mesh size near its target as peers come and go."},
    {"id": "a_metapeer", "tag": "mesh", "src": "p2p", "q": "In the GossipSub mesh topology mump2p builds on, what are metadata only peerings used for?", "a": ["Gossip and network maintenance", "Reliable full message delivery", "Encrypting the transport channel", "Storing decoded messages for peers"], "why": "Full message peerings carry the actual data; metadata only peerings carry gossip about what exists and keep the mesh healthy."},
    {"id": "a_degreetrade", "tag": "mesh", "src": "p2p", "q": "What is the downside of a higher MeshDegreeTarget in mump2p?", "a": ["Higher bandwidth use from redundant message copies", "Slower delivery because of extra hops", "Lower reliability from peer churn", "Weaker encryption on each link"], "why": "More mesh peers deliver faster and more reliably, but each extra peer sends copies you may already have, so bandwidth goes up."},
    {"id": "a_degreerange", "tag": "mesh", "src": "p2p", "q": "In libp2p's default implementation, what range of peering degree does the mump2p doc call acceptable?", "a": ["Anywhere from 4 to 12", "Anywhere from 2 to 6", "Anywhere from 8 to 20", "Anywhere from 1 to 3"], "why": "libp2p aims for an ideal degree of 6 but treats anything from 4 to 12 as acceptable, and mump2p inherits that mesh management.", "vol": true},
    {"id": "a_uncle", "tag": "mainnet", "src": "p2p", "q": "Which Ethereum benefit does the mump2p doc list alongside faster mempool propagation?", "a": ["Lower uncle rates", "Lower gas limits", "Fewer validators per committee", "Shorter epochs"], "why": "When blocks reach the network faster, fewer competing blocks get orphaned, so the doc lists lower uncle rates as an Ethereum benefit."},
    {"id": "a_turbine", "tag": "subsea", "src": "p2p", "q": "How does the mump2p doc say it can help Solana?", "a": ["By enhancing Turbine style data sharding with packet loss recovery", "By replacing Proof of History with RLNC based timestamps", "By cutting the number of validators Solana needs to run", "By compressing Solana transactions before they are gossiped"], "why": "Solana already shards block data through Turbine; mump2p adds coded redundancy so lost packets can be recovered without resends."},
    {"id": "a_sybil", "tag": "mesh", "src": "p2p", "q": "How does mump2p defend against Sybil and eclipse attacks?", "a": ["Through libp2p's peer discovery and management systems", "By requiring a stake deposit from every peer", "By limiting each node to one peer per country", "By decoding every shard before accepting a peer"], "why": "mump2p does not reinvent peer management; it relies on libp2p's discovery and management, which already guard against floods of malicious nodes."},
    {"id": "a_pollution", "tag": "shard", "src": "p2p", "q": "What is a pollution attack on a network coding protocol like mump2p?", "a": ["Injecting corrupted coded shards so honest nodes cannot decode", "Flooding a topic with duplicate copies of a full message", "Spoofing peer IDs to cut a node off from honest peers", "Delaying shards on purpose to inflate delivery latency"], "why": "In a pollution attack a bad actor feeds invalid shards into the mix, hoping that recoded combinations spread the damage and break decoding."},
    {"id": "a_srcauth", "tag": "shard", "src": "p2p", "q": "What is the core of mump2p's defense against pollution attacks?", "a": ["Source authentication", "Proof of work on each shard", "Peer bandwidth throttling", "Mandatory TLS pinning"], "why": "mump2p binds a hash and the publisher's signature to the data, so the source can be authenticated after decoding no matter who recoded along the way."},
    {"id": "a_verifysig", "tag": "shard", "src": "p2p", "q": "After decoding a message from shards, how does a mump2p node check that nothing was polluted?", "a": ["It checks the decoded data against the publisher's signature and hash", "It asks three mesh peers to vote on the decoded result", "It encodes the data again and compares the shard sizes", "It checks the message against the latest block header"], "why": "The publisher's signature and hash travel with the data, so the decoded result can be checked end to end even though intermediate nodes recoded it."},
    {"id": "a_reputation", "tag": "mesh", "src": "p2p", "q": "What does mump2p do to peers that sent invalid shards once a decode fails verification?", "a": ["Lowers their reputation scores and eventually isolates them", "Bans their IP address immediately", "Asks them to resend the full message", "Slashes their staked tokens"], "why": "Pinpointing the exact bad shard is hard, but the system can score down the peers that sent invalid shards until they are cut out of the network."},
    {"id": "a_proxysession", "tag": "gateway", "src": "clirepo", "q": "In the mump2p CLI, what is the proxy used for?", "a": ["Session management, with publish and subscribe going directly to nodes", "Relaying every message between the CLI and the network", "Storing all published messages for replay", "Running the RLNC decoder on behalf of the CLI"], "why": "The CLI only talks to the proxy to set up a session; actual publishing and subscribing happen directly with P2P nodes."},
    {"id": "a_loginflow", "tag": "gateway", "src": "clirepo", "q": "How does mump2p login finish authenticating you?", "a": ["You complete it in a browser by visiting a link and entering a code", "You paste an API key into the terminal", "You sign a message with your validator key", "You scan a QR code with a mobile wallet"], "why": "The CLI prints an activation link and a code; you finish the login in your browser while the CLI waits for confirmation."},
    {"id": "a_maxmsg", "tag": "gateway", "src": "clirepo", "q": "What maximum message size does the mump2p CLI whoami output show for an authenticated account?", "a": ["10.00 MB", "1.00 MB", "100.00 MB", "4.00 MB"], "why": "whoami lists the account limits, and the sample shows a 10 MB cap on a single published message.", "vol": true},
    {"id": "a_dailyquota", "tag": "gateway", "src": "clirepo", "q": "What daily data quota does the mump2p CLI whoami sample show?", "a": ["20480.00 MB", "2048.00 MB", "1024.00 MB", "51200.00 MB"], "why": "The sample account may publish up to 20480 MB per day, which is 20 GB of messages.", "vol": true},
    {"id": "a_failover", "tag": "gateway", "src": "clirepo", "q": "What does the mump2p CLI do if the first P2P node it tries is unreachable?", "a": ["It automatically falls back to the next node", "It exits with an error and asks you to retry", "It routes all traffic through the proxy instead", "It waits until the node comes back online"], "why": "The CLI requests several nodes up front, so when the first one fails it simply moves on to a backup without user action."},
    {"id": "a_exposedef", "tag": "gateway", "src": "clirepo", "q": "By default, how many nodes does the mump2p CLI request for failover on subscribe and on publish?", "a": ["3 for subscribe and 1 for publish", "1 for subscribe and 3 for publish", "3 for both subscribe and publish", "5 for subscribe and 2 for publish"], "why": "A subscription is long lived so it gets backup nodes; a publish is a single shot, so one node is enough by default.", "vol": true},
    {"id": "a_persistdir", "tag": "gateway", "src": "clirepo", "q": "If you give mump2p subscribe --persist only a directory path, what file are messages saved to?", "a": ["A file named messages.log in that directory", "A file named with the topic name", "A file named with the session ID", "One file per message"], "why": "With just a directory, the CLI picks the default file name messages.log inside it and appends received messages there."},
    {"id": "a_webhookpost", "tag": "gateway", "src": "clirepo", "q": "What must a webhook endpoint accept to receive messages from mump2p subscribe?", "a": ["POST requests", "GET requests", "WebSocket upgrades", "gRPC streams"], "why": "The CLI delivers each message with an HTTP POST, so the receiving endpoint has to be configured for POST."},
    {"id": "a_gotemplate", "tag": "gateway", "src": "clirepo", "q": "Which templating syntax does the mump2p CLI use for custom webhook schemas?", "a": ["Go template syntax", "Jinja2 syntax", "Mustache syntax", "Handlebars syntax"], "why": "Webhook bodies are shaped with Go templates, so placeholders like {{.Message}} and {{.Topic}} are filled in per message."},
    {"id": "a_tsformat", "tag": "gateway", "src": "clirepo", "q": "In mump2p webhook templates, in which format is the {{.Timestamp}} variable given?", "a": ["RFC3339", "Unix epoch seconds", "ISO week date", "RFC 2822"], "why": "The message timestamp is rendered in RFC3339, the common internet date and time format, so downstream tools can parse it easily."},
    {"id": "a_queuesize", "tag": "gateway", "src": "clirepo", "q": "By default, how many messages does the mump2p CLI queue for a webhook before it starts dropping?", "a": ["100", "10", "1000", "50"], "why": "The webhook queue holds 100 messages by default; busy topics can raise it to avoid drops when the endpoint is slow.", "vol": true},
    {"id": "a_debugflag", "tag": "gateway", "src": "clirepo", "q": "What extra information does the --debug flag add to mump2p CLI output?", "a": ["Session details, node scores, timing breakdowns and peer paths", "Raw RLNC coefficients for every shard it receives", "The full libp2p peer table of the connected node", "Gas estimates for each message it publishes"], "why": "Debug mode exposes the session, which nodes were scored and chosen, how long each phase took, and the path each message traveled."},
    {"id": "a_defproxy", "tag": "gateway", "src": "clirepo", "q": "Which proxy does the mump2p CLI use by default?", "a": ["http://us1-proxy.getoptimum.io:8080", "http://us2-proxy.getoptimum.io:8080", "http://us3-proxy.getoptimum.io:8080", "http://eu1-proxy.getoptimum.io:8080"], "why": "us1 is the default proxy; us2 and us3 exist too and can be chosen with the service URL flag for performance or proximity.", "vol": true},
    {"id": "a_topicstate", "tag": "gateway", "src": "clirepo", "q": "Why might mump2p list topics show different results on different proxies?", "a": ["Each proxy server keeps its own separate topic state", "Topics expire at different times per region", "Only the default proxy stores topics", "Topic names are hashed per proxy"], "why": "Topic subscriptions are tracked per proxy, so the same account can have different active topics on us1, us2 and us3."},
    {"id": "a_jwttickets", "tag": "gateway", "src": "clirepo", "q": "Per ADR-0002, what does the proxy return when the mump2p CLI requests a session?", "a": ["A list of scored P2P nodes with JWT tickets", "A single relay address and a password", "A full copy of the topic history", "The RLNC parameters for the network"], "why": "The proxy acts as the control plane: it hands back scored nodes plus JWT tickets so the CLI can connect to the best node directly."},
    {"id": "a_grpc", "tag": "gateway", "src": "clirepo", "q": "Per ADR-0002, which protocol does the mump2p CLI use to connect directly to the best node?", "a": ["gRPC", "WebSocket", "Raw TCP sockets", "HTTP long polling"], "why": "After the proxy hands over scored nodes, the CLI opens a direct gRPC connection and messages stream from the node with no proxy hop."},
    {"id": "a_noratelimit", "tag": "gateway", "src": "clirepo", "q": "What happens to rate limits when the mump2p CLI runs in its testing mode with authentication disabled?", "a": ["None are enforced, all quotas are bypassed", "They are halved for safety", "They are enforced per client ID", "They apply only to publishing"], "why": "With auth disabled there is no token to attach limits to, so no quotas are enforced and no usage is tracked."},
    {"id": "a_auth0", "tag": "gateway", "src": "clirepo", "q": "The mump2p CLI testing mode that disables authentication skips which identity service?", "a": ["Auth0", "Okta", "Firebase Auth", "Keycloak"], "why": "Normal logins go through Auth0's browser based device flow; the disable auth flag with a client ID skips that entirely for testing."},
    {"id": "a_outputfmt", "tag": "gateway", "src": "clirepo", "q": "Besides the default table, which output formats do mump2p read commands support?", "a": ["JSON and YAML", "CSV and XML", "TOML and INI", "Protobuf and MessagePack"], "why": "Read commands such as whoami, health and list topics can print JSON or YAML, which makes them easy to pipe into scripts."},
    {"id": "a_authpath", "tag": "gateway", "src": "clirepo", "q": "Where does the mump2p CLI store authentication tokens by default?", "a": ["~/.mump2p/auth.yml", "~/.config/mump2p/token.json", "/etc/mump2p/auth.yml", "~/.mump2p/session.toml"], "why": "Tokens live in auth.yml under a .mump2p folder in your home directory unless you point the CLI at a custom path."},
    {"id": "a_envauth", "tag": "gateway", "src": "clirepo", "q": "Which environment variable sets a custom auth file location for every mump2p CLI command?", "a": ["MUMP2P_AUTH_PATH", "MUMP2P_TOKEN_FILE", "OPTIMUM_AUTH_PATH", "MUMP2P_CONFIG_DIR"], "why": "Exporting MUMP2P_AUTH_PATH applies the custom auth file to all commands, handy for containers and non root deployments."},
    {"id": "a_tracerdash", "tag": "gateway", "src": "clirepo", "q": "What does the mump2p tracer dashboard command show?", "a": ["Live network metrics, message statistics and latency data", "The source code of the RLNC encoder and decoder", "A list of all validators active on the Hoodi testnet", "Your account's billing and payment history"], "why": "The tracer dashboard is an interactive real time view of the network, auto publishing demo messages so you can watch metrics and latency live."},
    {"id": "a_healthcmd", "tag": "gateway", "src": "clirepo", "q": "What does the mump2p health command check?", "a": ["The health of the proxy server", "The sync status of your Ethereum node", "The RLNC decode success rate", "The validity of your auth token"], "why": "mump2p health reports the proxy's status, memory, CPU and disk use, and the guide suggests running it before long operations."},
    {"id": "a_usagecmd", "tag": "gateway", "src": "clirepo", "q": "Which mump2p command shows your current usage against your rate limits?", "a": ["mump2p usage", "mump2p whoami", "mump2p health", "mump2p version"], "why": "When you hit rate limit errors, mump2p usage shows your hourly and per second publish counts and data used against the quotas."},
    {"id": "a_loadtest", "tag": "stress", "src": "clirepo", "q": "Which mump2p CLI mode does the guide say is useful for load testing and performance analysis?", "a": ["Debug mode", "Verbose mode", "Benchmark mode", "Profile mode"], "why": "Debug mode prints timing breakdowns per message, so firing many publishes at a debug subscriber gives a quick load test picture."},
    {"id": "a_proxyprox", "tag": "subsea", "src": "clirepo", "q": "Why would you choose a different mump2p proxy server, per the CLI guide?", "a": ["For better performance or geographic proximity", "To unlock a higher message size limit", "To access a different set of topics only", "To run commands without authentication"], "why": "The guide suggests picking a proxy for performance or closeness to you, since a nearer control plane cuts session setup time."},
    // batch B: written from the corpus snapshot of 2026-10-02, every answer backed by a verbatim passage of its source
    {"id": "b_15years", "tag": "hoodi", "src": "research", "q": "On how many years of network coding research does Optimum say its decentralized memory infrastructure is built?", "a": ["15 years", "5 years", "25 years", "40 years"], "why": "Optimum's research overview says its breakthrough rests on 15 years of pioneering network coding work, so the ideas behind mump2p are older than the company.", "vol": true},
    {"id": "b_konwarfields", "tag": "hoodi", "src": "research", "q": "Optimum's research overview says co founder and CTO Kishori Konwar drives the technology in which two fields?", "a": ["Distributed systems and coding theory", "Compiler design and cryptography", "Game theory and token economics", "Operating systems and robotics"], "why": "The overview pairs Konwar's distributed systems and coding theory background with Medard's RLNC work as the two pillars of Optimum's technology.", "vol": true},
    {"id": "b_lynchbft", "tag": "hoodi", "src": "research", "q": "Optimum's research overview credits advisor Nancy Lynch with foundational work on which topic?", "a": ["Byzantine Fault Tolerance", "Zero knowledge proofs", "Garbage collection", "Public key cryptography"], "why": "Lynch's work on Byzantine Fault Tolerance is why Optimum says she anchors its foundation in resilient, secure systems."},
    {"id": "b_necchair", "tag": "hoodi", "src": "research", "q": "Which MIT chair did Nancy Lynch hold before Muriel Medard, according to Optimum's research overview?", "a": ["NEC Chair of Software Science and Engineering", "Cecil and Ida Green Chair of Computer Science", "Ford Professorship of Engineering", "Dugald C. Jackson Chair of Electrical Engineering"], "why": "Lynch held MIT's NEC Chair of Software Science and Engineering before Medard did, a direct academic lineage between advisor and CEO.", "vol": true},
    {"id": "b_funccap", "tag": "hoodi", "src": "research", "q": "Optimum's research overview says network coding advances which three functional capabilities?", "a": ["Storage, access, and propagation", "Mining, staking, and voting", "Hashing, signing, and encrypting", "Indexing, caching, and billing"], "why": "The research library is organized around what network coding improves: how data is stored, how it is accessed, and how it propagates."},
    {"id": "b_algebraicgossip", "tag": "flood", "src": "resgossip", "q": "What name did Deb and Médard give their network coding approach to optimal multiple rumor mongering?", "a": ["Algebraic Gossip", "Epidemic Gossip", "Fountain Gossip", "Byzantine Gossip"], "why": "Algebraic Gossip mixes rumors into coded combinations instead of forwarding each one separately, the root idea behind coded gossip in mump2p."},
    // batch C: written from the corpus snapshot of 2026-10-02, every answer backed by a verbatim passage of its source
    {"id": "c_floodsubfwd", "tag": "flood", "src": "paper", "q": "According to the OptimumP2P paper, how does libp2p's Floodsub spread a message?", "a": ["Every node forwards the message to all of its neighbors", "Each node forwards only to six randomly chosen peers", "Only the publisher sends, relays never forward", "Nodes forward to one peer chosen by hash of the message"], "why": "Floodsub is pure flooding: each node pushes every message to every neighbor, which finds short paths but burns bandwidth."},
    {"id": "c_floodsubweak", "tag": "flood", "src": "paper", "q": "What two problems did Floodsub suffer from, according to the OptimumP2P paper?", "a": ["Bandwidth saturation and unbounded degree flooding", "Slow path discovery and frequent message loss", "Weak signatures and easy impersonation", "Large coefficient overhead and slow decoding"], "why": "Flooding to every neighbor finds paths quickly but saturates links and has no bound on how many peers each node talks to."},
    {"id": "c_gsubhops", "tag": "flood", "src": "paper", "q": "Per the OptimumP2P paper, what side effect did Gossipsub's bounded degree D have on message delivery?", "a": ["More hops to reach distant peers, so higher latency", "Fewer hops but much larger control messages", "Higher bandwidth use than Floodsub", "Messages reaching only a fraction of subscribers"], "why": "Limiting each node to D full message peers saves bandwidth, but a message now needs more relays to cross the network, which adds latency."},
    {"id": "c_gsubdup", "tag": "flood", "src": "paper", "q": "According to the OptimumP2P paper, why does Gossipsub still waste bandwidth on duplicates?", "a": ["Peers forward the full message even to peers that may already have it", "Every message is sent twice for reliability", "Control messages are larger than the data itself", "Metadata peers also receive full copies"], "why": "Gossipsub reduced duplication compared with Floodsub, but a relay still pushes whole messages to peers that may already hold them."},
    {"id": "c_question", "tag": "flood", "src": "paper", "q": "What central question does the OptimumP2P paper set out to answer about gossip protocols?", "a": ["Can a gossip protocol be light in network usage yet fast in diffusion", "Can gossip run without any peer discovery mechanism", "Can gossip replace consensus in blockchains", "Can gossip work without cryptographic signatures"], "why": "Floodsub is fast but heavy and Gossipsub is lighter but slower; the paper asks whether coding can give both speed and low network use."},
    {"id": "c_coverage", "tag": "flood", "src": "paper", "q": "Per the OptimumP2P paper, what is the 'faster network coverage' benefit of sending coded shards instead of full messages?", "a": ["Each peer reaches more peers for the same amount of data sent", "Each peer needs fewer signatures per message", "Each peer can skip validation of incoming data", "Each peer keeps a smaller routing table"], "why": "A shard is smaller than a full message, so with the same bytes a peer can feed many more neighbors at once."},
    {"id": "c_pushbased", "tag": "flood", "src": "paper", "q": "According to the OptimumP2P paper, is OptimumP2P primarily a push or a pull protocol?", "a": ["Push based: the publisher pushes shards and peers forward them", "Pull based: peers poll neighbors for shards every heartbeat", "Pure flooding of full messages like Floodsub", "Request only: nothing moves until a peer asks"], "why": "Shards flow proactively from the publisher outward; pulling extra shards is only a fallback when a node cannot decode."},
    {"id": "c_fallback", "tag": "flood", "src": "paper", "q": "In OptimumP2P, what happens when a node does not receive enough shards to decode a message?", "a": ["It requests more shards from its peers", "It drops the message permanently", "It asks the publisher to resend the full message", "It waits for the next heartbeat and re subscribes"], "why": "The push system has a fallback: a node short of shards simply asks its peers, who recode and supply more shards."},
    {"id": "c_pubfresh", "tag": "flood", "src": "paper", "q": "Why does OptimumP2P forward shards created by the publisher so aggressively?", "a": ["They are created early and always carry new degrees of freedom", "They are the only shards that carry a valid signature", "They are smaller than recoded shards", "They include the full coefficient matrix"], "why": "Publisher shards are fresh and each one adds new information to any receiver, so pushing them widely speeds up decoding everywhere."},
    {"id": "c_puballnbrs", "tag": "flood", "src": "paper", "q": "In OptimumP2P's publisher flooding optimization, to whom does the publisher send its shards?", "a": ["All of its neighbors, not only its mesh peers", "Only its mesh peers", "A single randomly chosen peer", "Only peers that sent an iwant request"], "why": "Unlike relays, which only feed their mesh peers, the publisher floods every connected neighbor to spread degrees of freedom fast."},
    {"id": "c_ctrlpurpose", "tag": "flood", "src": "paper", "q": "What two purposes do control messages serve in OptimumP2P, per the paper?", "a": ["Suppress unneeded transmissions and reach isolated nodes in partitions", "Negotiate the coding field size and shard count", "Elect a leader and order messages", "Measure link capacity and pick routes"], "why": "idontwant, ihave and iwant stop wasted sends and let a cut off node still pull shards for a message it missed."},
    {"id": "c_answeriwant", "tag": "flood", "src": "paper", "q": "In OptimumP2P, how does a node answer an iwant request for a message it has already decoded?", "a": ["It recodes the shards it used to decode into a fresh shard for the requester", "It sends the whole decoded message back to the requester in one piece", "It forwards the original publisher shards it received, unchanged", "It replies with an ihave and waits for the requester to ask again"], "why": "Even a decoded node answers in coded form: it mixes the shards it holds into a fresh shard and queues it for the requester."},
    {"id": "c_gsmultihop", "tag": "flood", "src": "paper", "q": "According to the OptimumP2P paper, what causes Gossipsub's erratic delivery times under load?", "a": ["Its multi hop gossip structure with redundant retransmissions", "Its use of a single fixed route for every message", "Its lack of any control messages between peers", "Its requirement to fully decode before forwarding"], "why": "Full messages hopping through a mesh take uneven paths and get resent needlessly, so some nodes receive much later than others."},
    {"id": "c_epidemic", "tag": "flood", "src": "paper", "q": "By what other name does the OptimumP2P paper say gossip algorithms are known?", "a": ["Epidemic protocols", "Consensus protocols", "Routing protocols", "Erasure protocols"], "why": "Gossip spreads like a disease: each informed node infects a random subset of neighbors, so the literature calls them epidemic protocols."},
    {"id": "c_ltdegrade", "tag": "shard", "src": "paper", "q": "Per the OptimumP2P paper, when does the performance of Luby Transform (LT) coded gossip degrade?", "a": ["In highly decentralized, multi hop topologies", "In direct multicast to a few destinations", "When messages are smaller than 1 MB", "When all links are reliable"], "why": "LT codes stream from one source and work well in shallow multicast, but across many hops the central encoder must resend lost pieces."},
    {"id": "c_galoistheory", "tag": "shard", "src": "paper", "q": "According to the OptimumP2P paper, the finite field algebra behind RLNC is rooted in which theory?", "a": ["Galois theory", "Graph theory", "Queueing theory", "Game theory"], "why": "RLNC works over finite (Galois) fields, which is why the paper calls its protocol Galois Gossip."},
    {"id": "c_piecebypiece", "tag": "shard", "src": "paper", "q": "How does the OptimumP2P paper summarize the essential difference between OptimumP2P and traditional gossip?", "a": ["Peers spread information piece by piece instead of full messages", "Peers use pull instead of push", "Peers keep a central index of all messages", "Peers gossip only inside a single data center"], "why": "Traditional gossip copies whole messages between peers; OptimumP2P moves coded pieces that receivers combine into the message."},
    {"id": "c_noninvert", "tag": "shard", "src": "paper", "q": "Per the OptimumP2P paper, what happens if a receiver's random coefficient matrix turns out not to be invertible?", "a": ["Discard it and wait for more shards until an invertible one forms", "Request the publisher to resend the full message", "Decode anyway with reduced accuracy", "Mark the message as polluted"], "why": "A random matrix is invertible with high probability; in the rare bad case the node just collects another shard and tries again."},
    {"id": "c_pollspread", "tag": "shard", "src": "paper", "q": "According to the OptimumP2P paper, how can a pollution attack spread beyond the Byzantine peer?", "a": ["Honest peers mix correct shards with polluted ones when recoding", "Signatures of polluted shards are copied by honest peers", "Polluted shards are smaller and travel faster", "The publisher re encodes polluted shards"], "why": "Recoding is the strength of RLNC, but an honest node that combines a bad shard with good ones produces more bad shards."},
    {"id": "c_rlnclib", "tag": "shard", "src": "paper", "q": "Which three operations does the external RLNC library in the OptimumP2P paper provide?", "a": ["Encoding, recoding and decoding", "Hashing, signing and verifying", "Grafting, pruning and scoring", "Compressing, splitting and merging"], "why": "The protocol treats RLNC as a black box with three calls: encode a value into shards, recode shards into a new shard, decode shards back."},
    {"id": "c_rugbyname", "tag": "shard", "src": "paper", "q": "Why is OptimumP2P's pollution avoidance scheme called the Rugby Protocol?", "a": ["A polluted node raises its hand like an offside rugby player, then gets back onside", "It was first tested on the private network of a university rugby club", "Shards are only ever passed backward between peers, like a rugby ball", "Peers form a scrum of exactly eight nodes before they start decoding"], "why": "A node that finds itself polluted announces it, stays quiet, and is reintegrated once clean, like an offside player signalling and rejoining play."},
    {"id": "c_keccak", "tag": "shard", "src": "paper", "q": "What does an OptimumP2P node use to detect that a decoded message was polluted?", "a": ["The keccak256 hash of the original message", "The size of the coefficient vector", "A majority vote among mesh peers", "The publisher's timestamp"], "why": "Every message id is a hash of its content, so a node simply hashes what it decoded and compares it with the id."},
    {"id": "c_detectcases", "tag": "shard", "src": "paper", "q": "Per the OptimumP2P paper, which two situations reveal pollution while a node tries to decode?", "a": ["More than k shards yet no decode, or decoding only with a proper subset", "A shard arrives twice, or a shard arrives unsigned", "A peer sends ihave twice, or never sends idontwant", "The mesh has fewer than D peers, or more than D peers"], "why": "If k shards should suffice but the hash does not match, or only some of the shards give the right hash, a bad shard is in the set."},
    {"id": "c_bruteforce", "tag": "shard", "src": "paper", "q": "How does an OptimumP2P node identify which neighbor sent polluted shards after it still managed to decode?", "a": ["By ignoring subsets of peers and noting which omissions remove the pollution", "By asking the publisher for a signed list of its honest neighbors", "By comparing the libp2p peer scores of all of its neighbors", "By checking which of its neighbors has the highest latency"], "why": "It is a brute force search: ignore shards from some peers, see whether decoding becomes clean, and blame the peers whose removal fixed it."},
    {"id": "c_fingerpoint", "tag": "shard", "src": "paper", "q": "In OptimumP2P's Byzantine finger pointing, what does a node attach when it warns peers about a malicious neighbor?", "a": ["The polluted shard itself as proof", "Its own copy of the decoded message", "A list of all its mesh peers", "The malicious peer's IP address"], "why": "Peers do not have to trust the accusation: each one checks that the attached shard really cannot decode the message before blocking the sender."},
    {"id": "c_noforge", "tag": "shard", "src": "paper", "q": "Per the OptimumP2P paper, why can the sender of a pollution alert not fabricate the proof shard?", "a": ["Each shard is signed by its creator", "Shards are encrypted with the publisher's key", "Alerts go only through the publisher", "Proof shards are hashed into the block"], "why": "Since every shard carries its creator's unforgeable signature, an accuser cannot invent a bad shard and pin it on an honest peer."},
    {"id": "c_selfquar", "tag": "shard", "src": "paper", "q": "In OptimumP2P's self quarantine rule, what does a node do when it discovers it is the source of pollution?", "a": ["It stays silent until it can decode the message and make a valid shard", "It broadcasts the full message to every one of its neighbors", "It leaves the mesh permanently and never rejoins the topic", "It resends every shard it previously forwarded to its peers"], "why": "A polluted node stops spreading bad shards; once it decodes correctly it can generate clean shards and rejoin."},
    {"id": "c_selfalert", "tag": "shard", "src": "paper", "q": "Why does an OptimumP2P node alert its neighbors as soon as it finds it has been polluted?", "a": ["To keep its reputation so it can be reintegrated later", "To ask them for the full message", "To force a new mesh election", "To trigger a network wide reset of the topic"], "why": "Confessing early protects a victim node's standing: peers quarantine and audit it instead of treating it as a Byzantine attacker."},
    {"id": "c_audit", "tag": "shard", "src": "paper", "q": "In OptimumP2P's pollution audit, when is a quarantined peer removed from quarantine?", "a": ["When a message it sends turns out to be a valid shard", "After a fixed number of heartbeats", "When the publisher vouches for it", "When it sends an idontwant"], "why": "Every shard from a quarantined peer is checked for decodability; the first valid one clears the peer."},
    {"id": "c_topics", "tag": "mesh", "src": "paper", "q": "According to the OptimumP2P paper, how does Gossipsub's topic organization reduce traffic?", "a": ["Nodes forward messages only to peers subscribed to the topic", "Nodes compress messages per topic", "Each topic has exactly one publisher", "Topics are limited to 128 KB messages"], "why": "Grouping messages into topics means a node never pushes data to peers that did not ask for that kind of content."},
    {"id": "c_sparsemesh", "tag": "mesh", "src": "paper", "q": "In Gossipsub as described in the OptimumP2P paper, how connected is the network of full message (mesh) peers?", "a": ["Sparsely connected, each peer with degree D", "Fully connected, every peer to every peer", "A single ring of peers", "A star around the publisher"], "why": "Full messages travel over a sparse mesh of degree D, while the dense metadata network carries only small control messages."},
    {"id": "c_whylimitd", "tag": "mesh", "src": "paper", "q": "Per the OptimumP2P paper, why does Gossipsub limit the number of full message peerings?", "a": ["To reduce network traffic and increase available bandwidth", "To make peer discovery deterministic", "To keep signatures short", "To avoid needing control messages"], "why": "Every full message peering is a channel that carries whole messages, so capping them keeps links from filling up with copies."},
    {"id": "c_higherd", "tag": "mesh", "src": "paper", "q": "According to the OptimumP2P paper, what does a higher mesh degree D improve in Gossipsub?", "a": ["Coverage, delivery speed, reliability and fault tolerance", "Bandwidth efficiency and lower congestion", "Coefficient randomness and decode speed", "Signature verification throughput"], "why": "More mesh peers means more paths, so messages reach subscribers faster and a dropped peer matters less; the price is more redundant copies."},
    {"id": "c_fwdconds", "tag": "mesh", "src": "paper", "q": "In OptimumP2P, which three things decide whether a node forwards a shard it just processed?", "a": ["Who sent it, how many shards the node holds, and its peers' status", "Message size, topic name, and time of day", "Link capacity, hop count, and publisher id", "Signature length, field size, and mesh degree"], "why": "Forwarding is conditional: publisher shards go out at once, others only past a threshold, and never to peers that already said they are done."},
    {"id": "c_whythreshold", "tag": "mesh", "src": "paper", "q": "Why do non publisher nodes in OptimumP2P wait for a forwarding threshold before recoding and sending a shard?", "a": ["To avoid sending shards unlikely to carry new degrees of freedom", "To give the publisher time to sign the message", "To keep the mesh degree below D", "To let the hash of the message be computed"], "why": "A relay with only a shard or two would mostly produce combinations its peers already have, so it waits until it holds enough to add real information."},
    {"id": "c_stopaccept", "tag": "mesh", "src": "paper", "q": "Once an OptimumP2P node confirms a neighbor is polluting, what does it do with that neighbor?", "a": ["Adds it to a malicious list and stops accepting its shards", "Sends it the full message so it can recover", "Asks it to re encode with new coefficients", "Moves it from mesh peer to metadata peer"], "why": "Byzantine avoidance is simple: a proven polluter is listed as malicious and its shards are ignored from then on."},
    {"id": "c_channels", "tag": "subsea", "src": "paper", "q": "What two kinds of communication channels does the OptimumP2P system model assume between peers?", "a": ["Reliable and unreliable", "Encrypted and plaintext", "Wired and wireless", "Synchronous and lock step"], "why": "The model allows links that may lose data, which is exactly where coded shards shine since any k shards suffice to decode."},
    {"id": "c_simgeo", "tag": "subsea", "src": "paper", "q": "In the OptimumP2P simulations, how were the latencies between pairs of nodes chosen?", "a": ["Based on real world geographic locations", "Set to a constant 50 ms", "Drawn uniformly at random", "Taken from the Bitcoin network"], "why": "Using real geography makes the simulated network behave like a globe spanning blockchain, with long haul links that matter for propagation."},
    {"id": "c_mirror", "tag": "subsea", "src": "paper", "q": "The real world testbed in the OptimumP2P paper was spread across the globe to roughly mirror what?", "a": ["The distribution of Ethereum validator nodes", "The distribution of Bitcoin miners", "The top ten cloud regions by price", "A single European data center"], "why": "Placing nodes where validators actually live makes the latency results meaningful for Ethereum block propagation."},
    {"id": "c_whylowvar", "tag": "subsea", "src": "paper", "q": "Per the OptimumP2P paper, why is OptimumP2P's delay variance so low across nodes?", "a": ["Coded fragments spread uniformly, so no single route or node is relied on", "All of its nodes sit inside the same data center", "It uses one fixed spanning tree for every message", "It sends every message twice over two different links"], "why": "When pieces arrive in parallel over many paths, no node waits on one slow link, so delivery times cluster tightly."},
    {"id": "c_gsvuln", "tag": "subsea", "src": "paper", "q": "According to the OptimumP2P paper, what makes Gossipsub vulnerable to packet drops during bursts?", "a": ["Its reliance on relaying full messages", "Its use of small control messages", "Its random choice of publisher", "Its topic based filtering"], "why": "If a whole message must arrive intact at each hop, one lost packet or a saturated link stalls that entire copy."},
    {"id": "c_ethshadow", "tag": "stress", "src": "paper", "q": "Which tool did the OptimumP2P authors use to simulate gossip in an Ethereum like network?", "a": ["Ethshadow", "Ganache", "Hardhat", "Kurtosis"], "why": "Ethshadow is an Ethereum simulation tool; using it let the authors rerun earlier Ethereum Foundation experiments for comparison.", "vol": true},
    {"id": "c_simnodes", "tag": "stress", "src": "paper", "q": "How many nodes did the OptimumP2P simulation run, and what share had 1 Gbps links?", "a": ["1,000 nodes, 20% with 1 Gbps", "100 nodes, 50% with 1 Gbps", "36 nodes, all with 1 Gbps", "10,000 nodes, 5% with 1 Gbps"], "why": "The setup copied prior Ethereum research: a thousand nodes, one fifth on fast 1 Gbps links and the rest on 50 Mbps.", "vol": true},
    {"id": "c_reproduce", "tag": "stress", "src": "paper", "q": "What gave the OptimumP2P authors confidence that their simulations were reproducible?", "a": ["Their Gossipsub results matched the earlier Ethereum Foundation results", "They ran each simulation on three cloud providers", "An external auditor repeated the runs", "The results matched the Bitcoin network"], "why": "Reproducing the known Gossipsub baseline first shows the simulator was set up correctly before comparing OptimumP2P against it."},
    {"id": "c_36nodes", "tag": "stress", "src": "paper", "q": "How many nodes did each protocol use in the OptimumP2P paper's real world A/B tests, and where did they run?", "a": ["36 identical nodes in Google Cloud data centers", "12 nodes on a university cluster", "100 nodes on home connections", "1,000 nodes in AWS"], "why": "Both protocols got the same 36 node, geographically spread GCP deployment so the comparison was apples to apples.", "vol": true},
    {"id": "c_latdef", "tag": "stress", "src": "paper", "q": "How did the OptimumP2P paper define propagation latency in its real world experiments?", "a": ["Time for 95% of nodes to receive and reconstruct the message", "Time for the first node to receive the message", "Time for the publisher to encode all shards", "Time until every single node acknowledged"], "why": "Measuring the 95th percentile of nodes captures network wide delivery without letting one straggler dominate the number.", "vol": true},
    {"id": "c_10msgs", "tag": "stress", "src": "paper", "q": "In the OptimumP2P paper, what were the latencies of Gossipsub and OptimumP2P for 10 MB messages at 10 messages per second?", "a": ["2.5 s for Gossipsub, 1.5 s for OptimumP2P", "1.0 s for Gossipsub, 0.8 s for OptimumP2P", "4.0 s for Gossipsub, 2.0 s for OptimumP2P", "15.6 s for Gossipsub, 1.3 s for OptimumP2P"], "why": "At a moderate publish rate Gossipsub already slowed to 2.5 seconds while the coded protocol held at 1.5 seconds.", "vol": true},
    {"id": "c_20opt", "tag": "stress", "src": "paper", "q": "In the OptimumP2P paper's real world tests at 20 messages per second, what latency did OptimumP2P hold for 10 MB messages?", "a": ["About 1.8 to 2.0 seconds", "About 4.0 seconds", "About 0.8 seconds", "About 15.6 seconds"], "why": "While Gossipsub saturated at this rate, OptimumP2P stayed around two seconds, showing coding uses capacity more efficiently.", "vol": true},
    {"id": "c_10mbgsdelay", "tag": "stress", "src": "paper", "q": "In the OptimumP2P paper's message size test (5 MB and 10 MB at 1 message per second), what average delay did Gossipsub show for 10 MB blocks?", "a": ["15.6 seconds", "2.3 seconds", "1.3 seconds", "4.0 seconds"], "why": "Large payloads broke Gossipsub: besides losing messages, its average delay ballooned to over fifteen seconds with huge variability.", "vol": true},
    {"id": "c_10mbopt", "tag": "stress", "src": "paper", "q": "In the OptimumP2P paper's message size test, what delivery rate and latency did OptimumP2P achieve for 10 MB blocks at 1 message per second?", "a": ["100% delivery with about 1302 ms latency", "84% delivery with about 15.6 s latency", "99% delivery with about 2293 ms latency", "95% delivery with about 2.5 s latency"], "why": "Going from 5 MB to 10 MB barely moved OptimumP2P's latency, while Gossipsub fell apart on the same payload.", "vol": true},
    {"id": "c_deliv20", "tag": "stress", "src": "paper", "q": "At 20 messages per second, what delivery rate did Gossipsub fall to in the OptimumP2P paper?", "a": ["About 80%, roughly 1 in 5 messages lost", "About 95%, roughly 1 in 20 lost", "About 50%, half the messages lost", "About 99%, almost nothing lost"], "why": "Under burst load Gossipsub dropped a fifth of messages to congestion and buffer overflows, while OptimumP2P kept 99 to 100% delivery.", "vol": true},
    {"id": "c_optvar", "tag": "stress", "src": "paper", "q": "In the OptimumP2P paper's real world tests, how tightly bounded was OptimumP2P's delay standard deviation across all publish rates?", "a": ["Around plus or minus 0.2 to 0.3 seconds", "Around plus or minus 0.9 seconds", "Around plus or minus 2 seconds", "Around plus or minus 7 seconds"], "why": "A spread of only a few hundred milliseconds means nearly all nodes get the message in the same narrow window.", "vol": true},
    {"id": "c_gsvar20", "tag": "stress", "src": "paper", "q": "At 20 messages per second, how large did Gossipsub's delay standard deviation grow in the OptimumP2P paper?", "a": ["Nearly plus or minus 0.9 seconds", "Nearly plus or minus 0.2 seconds", "Nearly plus or minus 5 seconds", "Nearly plus or minus 15 seconds"], "why": "Under load some Gossipsub nodes got messages far later than others, a much wider spread than the 0.2 to 0.3 seconds seen with OptimumP2P.", "vol": true},
    {"id": "c_partialdata", "tag": "stress", "src": "paper", "q": "Per the OptimumP2P paper, which ability of OptimumP2P ensures robust delivery even under stress?", "a": ["Delivering coded fragments and recovering full messages from partial data", "Retrying every lost message up to three times before giving up", "Electing a backup publisher for every topic in the network", "Compressing every message before it is gossiped to peers"], "why": "Because any sufficient set of shards rebuilds the message, losing some fragments in a burst does not stop delivery."},
    {"id": "c_blobs", "tag": "blob", "src": "paper", "q": "What kind of data did nodes propagate in the OptimumP2P paper's real world tests?", "a": ["Large data blobs simulating transaction blocks", "Small heartbeat pings", "Peer discovery records", "Encrypted chat messages"], "why": "The experiments used multi megabyte blobs standing in for blocks, the payloads that matter most for blockchain propagation."},
    {"id": "c_gslarge", "tag": "blob", "src": "paper", "q": "According to the OptimumP2P paper, how does Gossipsub behave as payloads grow large?", "a": ["It becomes unreliable under congestion and protocol overhead", "It speeds up because fewer separate messages are needed", "It stays perfectly stable for payloads up to 100 MB", "It switches automatically to Floodsub for big payloads"], "why": "Bigger blocks mean bigger full copies at every hop, so Gossipsub chokes while coded shards keep flowing."},
    {"id": "c_threeaims", "tag": "hoodi", "src": "paper", "q": "What three goals does the OptimumP2P paper state for its new protocol inside libp2p?", "a": ["Decrease latency, enhance fault tolerance, optimize bandwidth usage", "Add consensus, add staking, add slashing", "Encrypt traffic, hide peers, resist censorship", "Reduce storage, prune history, compress state"], "why": "The protocol targets the three things gossip struggles with at once: speed, resilience to loss, and network cost."},
    {"id": "c_efprior", "tag": "hoodi", "src": "paper", "q": "According to the OptimumP2P abstract, whose preliminary research already showed RLNC improving block propagation time?", "a": ["The Ethereum Foundation", "The Linux Foundation", "The Solana Foundation", "Protocol Labs"], "why": "Ethereum researchers had tested RLNC for faster block and blob propagation, and the paper builds on that work."},
    {"id": "c_replace", "tag": "hoodi", "src": "paper", "q": "In practice, what does the OptimumP2P paper say OptimumP2P aims to replace?", "a": ["The gossip protocol in libp2p", "Ethereum's consensus layer", "The TCP transport", "The block builder market"], "why": "OptimumP2P is built as a drop in gossip layer for libp2p, the network stack used by Ethereum and other chains."},
    {"id": "c_latencysens", "tag": "mainnet", "src": "paper", "q": "The OptimumP2P paper says fast and predictable delivery is critical for which application?", "a": ["Block propagation in blockchain systems like Ethereum", "Video streaming to mobile phones", "Backing up databases overnight", "Email delivery between servers"], "why": "Blocks must reach validators within a tight slot, so both low latency and low variance translate directly into fewer missed deadlines."},
    // batch D: written from the corpus snapshot of 2026-10-02, every answer backed by a verbatim passage of its source
    {"id": "d_tcpresend", "tag": "shard", "src": "codes", "q": "In Optimum's Battle of the Codes post, what is the old way of dealing with data lost on a shaky connection, the way TCP does it?", "a": ["Simply resend anything that did not make it", "Add redundant coded pieces before sending", "Route the data again over a second path", "Compress the data so less of it can be lost"], "why": "Before erasure codes, a lost packet was simply sent again. On a crowded network every resend adds to the traffic jam and delays things even more."},
    {"id": "d_threefam", "tag": "shard", "src": "codes", "q": "Which three families of erasure codes does Optimum's Battle of the Codes post compare?", "a": ["Block erasure codes, fountain codes and network codes", "Hamming codes, Huffman codes and Gray codes", "Convolutional codes, turbo codes and LDPC codes", "Checksum codes, parity codes and CRC codes"], "why": "The post lines up block codes like Reed-Solomon, fountain codes like LT and Raptor, and network codes like RLNC, each with its own trade offs."},
    {"id": "d_rspoly", "tag": "shard", "src": "codes", "q": "According to Optimum's Battle of the Codes post, how do block codes like Reed-Solomon work?", "a": ["They turn data into a polynomial representation and add systematic redundancy", "They hash data into a Merkle tree and add proof branches", "They XOR random subsets of packets with no fixed structure", "They compress data and attach a checksum to each block"], "why": "Reed-Solomon treats the data as a polynomial and adds structured extra pieces, which is why any k of its n shards can rebuild the original."},
    {"id": "d_rsrepurposed", "tag": "shard", "src": "codes", "q": "Per Optimum's Battle of the Codes post, what were Reed-Solomon codes traditionally designed as?", "a": ["Error correcting codes, later repurposed to handle erasures", "Erasure codes, later repurposed for error correction", "Compression codes, later repurposed for storage", "Encryption codes, later repurposed for networking"], "why": "Reed-Solomon was born to fix corrupted symbols. Using it to recover missing pieces came later, which is one reason it carries constraints that RLNC does not."},
    {"id": "d_mds", "tag": "shard", "src": "codes", "q": "Since any k of n Reed-Solomon shards can decode the data, RS belongs to which code category, per Optimum's Battle of the Codes post?", "a": ["Maximum Distance Separable (MDS) codes", "Low Density Parity Check (LDPC) codes", "Rateless fountain codes", "Cyclic redundancy codes"], "why": "A code where any k of the n shards is enough to decode is called Maximum Distance Separable, and Reed-Solomon is the classic example."},
    {"id": "d_codingrate", "tag": "shard", "src": "codes", "q": "In an (n, k) Reed-Solomon code, what does the ratio k/n define, according to Optimum's Battle of the Codes post?", "a": ["The coding rate, which sets how many erasures the code can tolerate", "The decoding latency measured in time slots", "The number of hops the code can survive", "The size of each shard in bytes"], "why": "k original pieces over n total shards is the coding rate. The lower the rate, the more extra shards exist and the more losses the code can absorb."},
    {"id": "d_rsuses", "tag": "shard", "src": "codes", "q": "Where does Optimum's Battle of the Codes post say Reed-Solomon codes are widely used today?", "a": ["RAID arrays, optical media like CDs and DVDs, and QR codes", "Wireless mesh networks, IoT systems and 5G links", "Blockchain gossip, mempools and block relays", "Video streaming, IPTV and satellite broadcast"], "why": "Reed-Solomon is everywhere in storage: disk arrays, CDs and DVDs, and the QR codes you scan. It is well understood, which is why it spread so widely."},
    {"id": "d_rssource", "tag": "shard", "src": "codes", "q": "In a network, where does coding happen with Reed-Solomon codes, according to Optimum's Battle of the Codes post?", "a": ["Only at the source, with decoding at the targets", "At every intermediate node along the path", "At the receiver, which requests parity on demand", "At a central coordinator shared by all nodes"], "why": "Reed-Solomon is a single source scheme: the sender encodes once and only the destinations decode. Nodes in between can merely forward what they got."},
    {"id": "d_fountainstream", "tag": "shard", "src": "codes", "q": "Unlike block codes, what do fountain codes generate, per Optimum's Battle of the Codes post?", "a": ["An unlimited stream of encoded packets built by combining original data shreds", "Exactly n packets fixed in advance by the coding rate", "A single parity packet for every original shred", "A polynomial the receiver evaluates at k points"], "why": "A fountain code keeps producing fresh packets for as long as needed, so sender and receiver need no precise coordination about how many were lost."},
    {"id": "d_ncfirst", "tag": "shard", "src": "codes", "q": "Per Optimum's Battle of the Codes post, who first discussed the existence of network coding, and in which year?", "a": ["Ahlswede, Cai, Li and Yeung in 2000", "Reed and Solomon in 1960", "Luby in 2002", "Shokrollahi in 2006"], "why": "Network coding was first described in 2000 by Ahlswede, Cai, Li and Yeung; the algebraic framework and RLNC came in the following years."},
    {"id": "d_kotter", "tag": "shard", "src": "codes", "q": "Who gave network coding an algebraic framework by writing each node's processing as equations, per Optimum's Battle of the Codes post?", "a": ["Kötter and Médard", "Reed and Solomon", "Luby and Shokrollahi", "Ahlswede and Yeung"], "why": "Kötter and Médard modeled each node as algebraic equations and the whole network as a matrix, showing that matrix manipulation can encode and decode data."},
    {"id": "d_rlncenv", "tag": "shard", "src": "codes", "q": "In which environments does Optimum's Battle of the Codes post say RLNC is superior to other coding approaches?", "a": ["Decentralized, dynamic ones like wireless mesh networks, IoT systems and 5G", "Static ones like RAID arrays and optical discs", "Centralized ones like a single data center", "Lossless ones like fiber links inside a lab"], "why": "Because RLNC needs no fixed rules or structure, it shines where topology shifts and links flicker, exactly the conditions of decentralized networks."},
    {"id": "d_rsnever", "tag": "shard", "src": "codes", "q": "How does Optimum's Battle of the Codes post describe Reed-Solomon codes relative to RLNC?", "a": ["Never better than RLNC, a needlessly constrained random code", "Better than RLNC on single links but worse over many hops", "Equal to RLNC in theory but slower than RLNC in practice", "Better than RLNC for small messages but not large ones"], "why": "The post is blunt: Reed-Solomon is a degenerate, constrained special case of a random code, so it can match RLNC at best and never beat it."},
    {"id": "d_elevenshards", "tag": "shard", "src": "codes", "q": "In the Battle of the Codes example where a channel drops 1 in 10 messages and the receiver needs 10 shards, how many shards does the source prepare?", "a": ["11 shards", "10 shards", "20 shards", "15 shards"], "why": "One extra shard covers the expected single loss out of ten, so the receiver still collects the ten it needs on a point to point link.", "vol": true},
    {"id": "d_multicastfail", "tag": "flood", "src": "codes", "q": "In a single hop multicast using block codes, what happens to a receiver that fails to collect k shards, per Optimum's Battle of the Codes post?", "a": ["It fails to decode the original data", "It asks neighbors for recoded shards", "It decodes a partial version of the data", "It waits for the next coding round"], "why": "A block code fixes n and k in advance, so a receiver that loses more than n minus k shards is simply stuck, even if other receivers did fine."},
    {"id": "d_lossaccum", "tag": "subsea", "src": "codes", "q": "Per Optimum's Battle of the Codes post, what happens to shard loss as packets cross more hops with block or fountain codes?", "a": ["Loss accumulates, so more hops means more packets missing at the receiver", "Loss resets at every hop because each node resends", "Loss stays constant no matter how many hops there are", "Loss decreases because each hop adds redundancy"], "why": "Each hop drops a few shards and nobody in the middle can replace them, so the losses pile up along the path until decoding fails or needs heavy overhead."},
    {"id": "d_diamond", "tag": "mesh", "src": "codes", "q": "In Optimum's Battle of the Codes post, why does decoding at intermediate nodes fail in a topology like the diamond?", "a": ["Coded elements get split among the nodes, so each may lack enough to decode", "The nodes cannot agree on which path is primary", "The diamond creates a cycle that duplicates packets forever", "Intermediate nodes have no finite field to work in"], "why": "When the source's shards fan out over two middle nodes, each one sees only part of the set, so neither can decode and the scheme breaks down."},
    {"id": "d_lasthop", "tag": "subsea", "src": "codes", "q": "With RLNC recoding at intermediate nodes, which losses does the receiver actually see, per Optimum's Battle of the Codes post?", "a": ["Only the losses from the last hop", "The sum of the losses from every hop", "Twice the losses of a single hop", "No losses at all, even on the last hop"], "why": "Every intermediate node can mint replacement shards by recoding, so earlier losses are healed on the way and only the final link's drops remain."},
    {"id": "d_nosync", "tag": "shard", "src": "codes", "q": "Besides creating new packets without decoding, which need does RLNC recoding eliminate, per Optimum's Battle of the Codes post?", "a": ["Distributed synchronization protocols", "Finite field arithmetic", "Source authentication", "Peer reputation scoring"], "why": "Random coefficients make every node's output independently useful, so nodes never have to coordinate who sends which piece."},
    {"id": "d_constthru", "tag": "stress", "src": "codes", "q": "As a network grows, how does RLNC throughput compare with other coding approaches, per Optimum's Battle of the Codes post?", "a": ["RLNC keeps constant throughput while the others drop with the number of hops", "All approaches drop equally as the hop count increases", "RLNC throughput grows with hops while the others stay flat", "The others keep constant throughput while RLNC drops"], "why": "Recoding stops loss from stacking up hop after hop, so RLNC holds its throughput as paths lengthen, which the post calls necessary for a scalable network."},
    {"id": "d_treeprotocols", "tag": "mesh", "src": "codes2", "q": "In Battle of the Codes Pt II, which two Web3 protocols are named for adopting hierarchical tree topologies?", "a": ["Monad and Solana", "Ethereum and Bitcoin", "Cosmos and Avalanche", "Polkadot and Near"], "why": "Solana's Turbine and Monad's RaptorCast both push block data down a tree of validators, which is why the post studies trees next."},
    {"id": "d_treenocycle", "tag": "mesh", "src": "codes2", "q": "What important property of tree topologies does Battle of the Codes Pt II point out?", "a": ["No cycles: no chain of connections leads back to the starting node", "Every node has exactly two children", "All leaves sit at the same depth", "Every node connects to every other node"], "why": "A tree branches from a root and never loops back, which makes it a set of daisy chains and means loss accumulates along each branch."},
    {"id": "d_turbinecode", "tag": "shard", "src": "codes2", "q": "Per Battle of the Codes Pt II, which erasure code does Solana's Turbine use when it breaks blocks into shreds?", "a": ["Reed-Solomon codes", "Raptor codes", "LT codes", "Random Linear Network Codes"], "why": "Turbine slices each block into shreds coded with Reed-Solomon, so validators can rebuild a block even when some shreds never arrive."},
    {"id": "d_turbinebatch", "tag": "shard", "src": "codes2", "q": "In Solana's Turbine, as described in Battle of the Codes Pt II, how many shreds make a batch and how many recover the data?", "a": ["64 shreds, any 32 recover the data", "32 shreds, any 16 recover the data", "128 shreds, any 64 recover the data", "64 shreds, any 48 recover the data"], "why": "Each batch carries 64 shreds and any 32 are enough, a code rate of one half, so Turbine can lose half a batch and still rebuild it.", "vol": true},
    {"id": "d_solanaslot", "tag": "mainnet", "src": "codes2", "q": "Per Battle of the Codes Pt II, how long is a Solana slot, and how often is the leader schedule generated?", "a": ["400 millisecond slots, a schedule per epoch about every two days", "12 second slots, a schedule per epoch about every six minutes", "1 second slots, a schedule per epoch about every hour", "400 millisecond slots, a schedule per epoch about every week"], "why": "Solana fixes a leader for every 400 ms slot, with the schedule drawn up before each epoch, which comes around roughly every two days.", "vol": true},
    {"id": "d_raptorcast", "tag": "shard", "src": "codes2", "q": "Per Battle of the Codes Pt II, what is RaptorCast?", "a": ["MonadBFT's multicast protocol for block proposals, built on a variant of Raptor codes", "Solana's block propagation protocol built on Reed-Solomon codes", "Ethereum's gossip protocol for beacon blocks", "Optimum's RLNC based data propagation protocol"], "why": "RaptorCast is how Monad spreads block proposals: chunks are coded with a Raptor code variant (RFC 5053) and sent down a two level tree."},
    {"id": "d_raptor2x", "tag": "stress", "src": "codes2", "q": "Per Battle of the Codes Pt II, RaptorCast keeps propagation latency within what bound?", "a": ["2x the network's worst case one way latency", "Half the network's average round trip time", "One slot of 400 milliseconds", "10x the fastest link's latency"], "why": "With only two levels in its tree, RaptorCast promises delivery within twice the worst one way latency while using all upload bandwidth.", "vol": true},
    {"id": "d_raptorudp", "tag": "subsea", "src": "codes2", "q": "Per Battle of the Codes Pt II, which transport does RaptorCast run over, and how does it cope with packet loss?", "a": ["UDP, with senders adding configurable redundancy", "TCP, with automatic retransmission", "QUIC, with built in forward error correction", "HTTP, with retries through a relay"], "why": "RaptorCast avoids retransmission entirely: it fires chunks over UDP and lets senders add enough extra coded chunks to cover expected loss."},
    {"id": "d_twostrategies", "tag": "shard", "src": "codes2", "q": "Per Battle of the Codes Pt II, what two strategies do block and fountain codes use to avoid accumulating shred loss?", "a": ["Assume a fixed topology and send extra coded elements, or decode and encode anew at each hop", "Lower the coding rate for every message, or raise the packet size until no shred is lost", "Retransmit every lost shred from the source, or switch each receiver to a backup path", "Recode the shreds at each node, or cache a full copy of the message at the root"], "why": "Without recoding, a protocol must either over provision shards for a known hop count or stop at every node to decode and encode again."},
    {"id": "d_treedepth", "tag": "mesh", "src": "codes2", "q": "Per Battle of the Codes Pt II, what tree depth does Turbine assume, and what structure does RaptorCast use?", "a": ["Turbine two to three levels, RaptorCast a fixed two level structure", "Turbine one level, RaptorCast a fixed five level structure", "Both use a fixed two level structure", "Turbine ten levels, RaptorCast an unbounded tree"], "why": "Both protocols cap their hop count up front so they can pre compute enough redundancy, which is the fixed topology strategy.", "vol": true},
    {"id": "d_expdrop", "tag": "stress", "src": "codes2", "q": "Per Battle of the Codes Pt II, what would happen if Turbine or RaptorCast added more tree layers as they scale?", "a": ["Hops would increase and throughput would decrease exponentially", "Hops would increase but throughput would stay flat", "Throughput would rise with each added layer", "Latency would fall because the tree gets wider"], "why": "Each added layer is another hop where losses stack up for a non recoding code, so throughput falls off exponentially with depth."},
    {"id": "d_fourshreds", "tag": "shard", "src": "codes2", "q": "In the Battle of the Codes Pt II example, how many coded shreds does each protocol start with, and how many decode the message?", "a": ["Four coded shreds, any two decode", "Six coded shreds, any three decode", "Four coded shreds, any three decode", "Eight coded shreds, any four decode"], "why": "The worked example keeps things tiny: four shreds at the root, two needed, so you can watch each timeslot and see who decodes first."},
    {"id": "d_sixslots", "tag": "stress", "src": "codes2", "q": "In the Battle of the Codes Pt II example, how many timeslots do block and fountain codes need to reach every node?", "a": ["6 timeslots", "2 timeslots", "3 timeslots", "10 timeslots"], "why": "Because block and fountain codes must decode and encode again at each level, they need six rounds, while RLNC shards flow straight through.", "vol": true},
    {"id": "d_rsdup", "tag": "shard", "src": "codes2", "q": "In the Battle of the Codes Pt II example, what stops the leftmost second level node from decoding with Reed-Solomon?", "a": ["It received a duplicated RS shred", "It received a corrupted RS shred", "Its link to the root was faulty", "It never received any RS shred"], "why": "Two copies of the same Reed-Solomon shred carry no new information, so the node still lacks the two distinct pieces it needs."},
    {"id": "d_rumor", "tag": "flood", "src": "bloggossip", "q": "In Optimum's Gossip Protocol Problem post, which analogy explains how gossip protocols spread data?", "a": ["A rumor spreading through a high school", "A virus spreading through a city", "Water flowing through a pipe network", "A radio station broadcasting to listeners"], "why": "One student tells two friends, who each tell two more. Gossip protocols fan out the same way, fast at first and then wasteful at the end."},
    {"id": "d_earlycov", "tag": "flood", "src": "bloggossip", "q": "Per Optimum's Gossip Protocol Problem post, for which share of nodes does gossip deliver low latency early on?", "a": ["The first 50 to 90% of nodes", "The first 5 to 10% of nodes", "Only the publisher's direct peers", "The last 10% of nodes"], "why": "Early hops reach mostly nodes that have not heard yet, so the first half to most of the network gets the data quickly. The stragglers are the problem."},
    {"id": "d_lastmile", "tag": "flood", "src": "bloggossip", "q": "What is the last mile bottleneck of gossip, per Optimum's Gossip Protocol Problem post?", "a": ["Near the end, most bandwidth goes to duplicates for nodes that already have the data", "At the end, nodes stop forwarding to save bandwidth", "Near the end, the publisher runs out of upload capacity", "At the end, the last nodes refuse to accept the data"], "why": "Once most nodes know, almost every send hits someone who already has it, so the last few nodes wait while bandwidth is burned on repeats."},
    {"id": "d_tenthousand", "tag": "flood", "src": "bloggossip", "q": "Per Optimum's Gossip Protocol Problem post, what happens to a standard gossip approach that works fine for 10 nodes when there are 10,000?", "a": ["It can bog down considerably", "It speeds up thanks to more peers", "It behaves exactly the same", "It stops working entirely"], "why": "Gossip overhead grows faster than the bandwidth new nodes bring, so a scheme that is fine in a small group slows badly at blockchain scale."},
    {"id": "d_finality", "tag": "mainnet", "src": "bloggossip", "q": "Per Optimum's Gossip Protocol Problem post, about how long does Ethereum take to finalize a block?", "a": ["About 2 epochs, around 12.8 minutes", "About 2 slots, around 24 seconds", "About 1 epoch, around 6.4 minutes", "About 10 epochs, around an hour"], "why": "Finality waits roughly two epochs, partly to give the network time to gossip the block to everyone, so gossip lag is baked into the delay.", "vol": true},
    {"id": "d_nodecount", "tag": "mainnet", "src": "bloggossip", "q": "Per Optimum's Gossip Protocol Problem post, how many full nodes and active validators must data reach on Ethereum for finality?", "a": ["More than 9,000 full nodes and 560K active validators", "More than 900 full nodes and 56K active validators", "More than 90,000 full nodes and 5.6M active validators", "More than 3,000 full nodes and 100K active validators"], "why": "Ethereum's size is what exposes gossip's limits: thousands of nodes and hundreds of thousands of validators all need the same data in time.", "vol": true},
    {"id": "d_entropy", "tag": "flood", "src": "bloggossip", "q": "Per Optimum's Gossip Protocol Problem post, what does bandwidth deliver under RLNC instead of duplicates?", "a": ["Entropy, meaning new information in every fragment", "Compressed copies of the full block", "Signed receipts from each peer", "Routing hints for the next hop"], "why": "Every coded fragment is a fresh algebraic mix, so until a node can decode, each one it receives teaches it something new."},
    {"id": "d_propnotcons", "tag": "flood", "src": "bloggossip", "q": "What is the main takeaway of Optimum's Gossip Protocol Problem post about slow confirmations?", "a": ["They are often a data propagation problem, not just a consensus problem", "They are mostly caused by slow signature verification", "They come from block size limits alone", "They are caused by having too few validators"], "why": "Consensus cannot act on what nodes have not received, so how data spreads often matters more for confirmation time than the consensus rules."},
    {"id": "d_txflow", "tag": "mainnet", "src": "blogp2p", "q": "In Optimum's Introducing mump2p post, how does a built block reach the proposer on Ethereum?", "a": ["It is sent to the proposer via a relayer", "The proposer builds it from its own mempool", "It is pulled from an RPC node", "It is fetched from the beacon chain"], "why": "The post traces a transaction from RPC node to mempool to a built block, which a relayer hands to the proposer before broadcast begins."},
    {"id": "d_supermaj", "tag": "mainnet", "src": "blogp2p", "q": "Per Optimum's Introducing mump2p post, when is a block considered confirmed on Ethereum?", "a": ["When enough nodes for a two thirds supermajority have received and attested to it", "When the proposer has signed it", "When half of the validators have seen it", "When it is included in the next epoch"], "why": "Confirmation needs two thirds of the network to receive and attest, which is why getting the block to everyone quickly matters so much."},
    {"id": "d_noencode", "tag": "flood", "src": "blogp2p", "q": "Per Optimum's Introducing mump2p post, what is Gossipsub's key limitation compared with mump2p?", "a": ["It is a method of gossip that does not use data encoding", "It only works inside a single data center", "It requires a consensus change to deploy", "It only supports messages under 1 MB"], "why": "Gossipsub moves whole copies around with no coding; mump2p adds RLNC, which is what makes propagation faster, more reliable and lighter on bandwidth."},
    {"id": "d_agentservice", "tag": "gateway", "src": "blogp2p", "q": "In Optimum's Introducing mump2p post, which piece of software reads blocks directly from the validator's Ethereum client?", "a": ["The Optimum Agent", "The Optimum Service", "The Optimum Gateway", "The Optimum Relayer"], "why": "The Agent picks up blocks from the Ethereum client and hands them to the Service, which codes them into shards and sends them out."},
    {"id": "d_otheruses", "tag": "blob", "src": "blogp2p", "q": "Besides block propagation, which uses does Optimum's Introducing mump2p post list for mump2p?", "a": ["Faster transaction relay from RPC node to mempool, and faster blob propagation", "Faster state sync and faster snapshot downloads", "Faster MEV auctions and faster relay bidding", "Faster light client proofs and faster bridging"], "why": "Anything that must spread across the network benefits: transactions on their way to the mempool and blobs for rollups, not only blocks."},
    {"id": "d_lowspec", "tag": "flex", "src": "blogp2p", "q": "Per Optimum's Introducing mump2p post, how does RLNC's resource efficiency protect decentralization?", "a": ["Lower spec nodes can still participate effectively", "Only data centers can meet the bandwidth needs", "Validators must upgrade to enterprise hardware", "Nodes are grouped by hardware tier"], "why": "Because coded propagation uses less bandwidth, modest machines keep up, unlike hardware based scaling that pushes a network toward centralization."},
    {"id": "d_simnodes", "tag": "stress", "src": "blogcompare", "q": "In Optimum's Optimump2p versus Gossipsub simulations, how many nodes were simulated and how was bandwidth split?", "a": ["1,000 nodes, 20% at 1Gbps and 80% at 50Mbps", "100 nodes, all of them at 1Gbps", "1,000 nodes, 50% at 1Gbps and 50% at 50Mbps", "10,000 nodes, 20% at 10Gbps and 80% at 100Mbps"], "why": "Optimum reused the setup of earlier Ethereum research: a thousand nodes with a fast minority and a slower majority, so results could be compared directly.", "vol": true},
    {"id": "d_live36", "tag": "stress", "src": "blogcompare", "q": "In Optimum's live demo on 36 nodes with 6 MB messages, what average latencies did Optimump2p and Gossipsub show?", "a": ["1.17 seconds for Optimump2p versus 2.35 seconds for Gossipsub", "2.35 seconds for Optimump2p versus 1.17 seconds for Gossipsub", "0.5 seconds for Optimump2p versus 5 seconds for Gossipsub", "1.17 seconds for both Optimump2p and Gossipsub"], "why": "On real geographically spread infrastructure, coded propagation delivered 6 MB messages in about half the time Gossipsub needed.", "vol": true},
    {"id": "d_stddev", "tag": "stress", "src": "blogcompare", "q": "In Optimum's Optimump2p versus Gossipsub experiments, how did Gossipsub's latency standard deviation compare?", "a": ["It was twice as much as Optimump2p's", "It was half of Optimump2p's", "It was about the same as Optimump2p's", "It was ten times Optimump2p's"], "why": "Gossipsub's delivery times swung twice as widely. Queueing theory says more variation hurts any system, so steadier latency is a win in itself.", "vol": true},
    {"id": "d_congestion", "tag": "stress", "src": "blogcompare", "q": "Per Optimum's Optimump2p versus Gossipsub post, Gossipsub failing to deliver 10 MB messages is characteristic of what?", "a": ["Network congestion", "A libp2p bug", "A UDP packet size limit", "Too few mesh peers"], "why": "When load passes a threshold, queueing delay explodes rather than growing gently. Gossipsub hit that wall at 10 MB while Optimump2p kept going."},
    {"id": "d_trilemma3", "tag": "mainnet", "src": "blogtrilemma", "q": "Which three properties make up the Blockchain Trilemma, per Optimum's Unlocking the Blockchain Trilemma post?", "a": ["Decentralization, security and scalability", "Privacy, liveness and finality", "Throughput, latency and cost", "Consistency, availability and partition tolerance"], "why": "The trilemma says you cannot fully have all three at once. Optimum argues that RLNC lifts scalability without giving up the other two."},
    {"id": "d_threats", "tag": "mainnet", "src": "blogtrilemma", "q": "Which three security threats against blockchains does Optimum's Trilemma post attribute to Buterin?", "a": ["Failures, attacks and collusion", "Forks, reorgs and censorship", "Spam, Sybils and eclipses", "Bugs, exploits and leaks"], "why": "Failures stop nodes, attacks push nodes off the protocol, and collusion is nodes coordinating to defeat it. Security means tolerating all three."},
    {"id": "d_f1rounds", "tag": "mainnet", "src": "blogtrilemma", "q": "Per Optimum's Trilemma post, how many synchronous rounds suffice to solve consensus when at most f nodes may be byzantine or crash?", "a": ["f + 1 rounds", "2f + 1 rounds", "3f rounds", "f squared rounds"], "why": "In a synchronous system with bounded delays, f plus one rounds are enough to agree, one more than the number of nodes that can misbehave."},
    {"id": "d_deltatrade", "tag": "mainnet", "src": "blogtrilemma", "q": "Per Optimum's Trilemma post, what is the risk of choosing a very small consensus slot delta?", "a": ["Unproductive consensus attempts that reduce throughput", "Faster finality with no downside", "Validators getting slashed more often", "Blocks growing too large to propagate"], "why": "If the slot is shorter than the time messages need to arrive, rounds fail and must repeat. Faster gossip is what lets the slot shrink safely."},
    {"id": "d_untethered", "tag": "mainnet", "src": "blogtrilemma", "q": "What does Optimum's Trilemma post conclude RLNC does for a chain's scalability?", "a": ["It untethers scalability from decentralization and security", "It trades decentralization for higher throughput", "It makes security depend on the node count", "It fixes scalability at the consensus layer"], "why": "By making data spread fast at any network size, RLNC lets a chain scale without shrinking its validator set or bounding communication."},
    // batch E: written from the corpus snapshot of 2026-10-02, every answer backed by a verbatim passage of its source
    {"id": "e_junedemo", "tag": "stress", "src": "bloghoodi", "q": "In Optimum's Acceleration post, how long did the June 2025 mump2p demo take to propagate a 4 MB message across 36 nodes?", "a": ["About 1113 milliseconds", "About 150 milliseconds", "About 1577 milliseconds", "About 2600 milliseconds"], "why": "The first public demo moved an average sized Ethereum block across 36 global nodes in roughly 1113 ms. The later Hoodi result of 150 ms shows how much faster the protocol became.", "vol": true},
    {"id": "e_sevenx", "tag": "stress", "src": "bloghoodi", "q": "Beyond the typical 6.5x, how much faster does the Acceleration post say mump2p frequently propagates blocks than Gossipsub on Hoodi?", "a": ["7 or 8 times faster", "Exactly 6 times faster", "20 to 30 times faster", "2 to 3 times faster"], "why": "6.5x is the typical gap, but the 24 hour chart regularly shows blocks arriving 7 or 8 times faster than the Gossipsub baseline.", "vol": true},
    {"id": "e_band130", "tag": "stress", "src": "bloghoodi", "q": "On Hoodi, in what latency band did the majority of blocks reach all 30 mump2p enabled peers, per the Acceleration post?", "a": ["Between 130 and 170 ms", "Between 50 and 90 ms", "Between 300 and 400 ms", "Between 900 and 1100 ms"], "why": "Most blocks landed on every mump2p peer within 130 to 170 ms, which is why Optimum stresses consistency as much as raw speed.", "vol": true},
    {"id": "e_promhist", "tag": "stress", "src": "blogmetrics", "q": "In Behind the Metrics, what bucket range do the Prometheus histograms that store mump2p latency cover?", "a": ["10 ms to 40 seconds", "1 ms to 1 second", "100 ms to 10 seconds", "1 second to 5 minutes"], "why": "Latency samples go into Prometheus histograms with buckets from 10 ms up to 40 seconds, which lets the team compute averages and p50, p95 and p99 automatically.", "vol": true},
    {"id": "e_slotstart", "tag": "stress", "src": "blogmetrics", "q": "In Behind the Metrics, how is a block's propagation latency calculated when it arrives at a gateway?", "a": ["Current time minus the slot's start time", "Time since the previous block arrived", "Round trip time to the proposer", "Time since the gateway's last restart"], "why": "Each slot has a deterministic start time, so the gateway stamps the arrival and subtracts the slot start. That difference is the propagation latency."},
    {"id": "e_pandaops", "tag": "stress", "src": "blogmetrics", "q": "Where does the ~1 second Gossipsub baseline in Optimum's Hoodi comparison come from, per Behind the Metrics?", "a": ["ethPandaOps' monitoring infrastructure", "Optimum's own Devnet measurements", "Etherscan block timestamps", "The Ethereum Foundation's client benchmarks"], "why": "The baseline is an independent third party number from ethPandaOps' sentry node monitoring, which keeps Optimum from grading its own homework."},
    {"id": "e_abslots", "tag": "stress", "src": "blogmetrics", "q": "Besides dual path measurement, what validation approach does Behind the Metrics say runs on alternating slots?", "a": ["AB testing between the two protocols", "Random packet drop injection", "Replaying historical blocks", "Synthetic 10 MB block flooding"], "why": "AB testing alternates slots between protocols so the comparison stays controlled over time, adding a second check on top of the dual path measurement."},
    {"id": "e_600pct", "tag": "stress", "src": "blogdecent", "q": "In Decentralize to Scale, how much lower latency does Optimum say OptimumP2P delivered in testing compared with Gossipsub?", "a": ["600% to 3000% lower", "10% to 50% lower", "50% to 100% lower", "100% to 200% lower"], "why": "Kent Lin's post credits OptimumP2P with 600% to 3000% lower latency than Gossipsub in testing, offered as proof that RLNC thrives where other propagation methods slow down.", "vol": true},
    {"id": "e_gs4mb", "tag": "stress", "src": "blogapps", "q": "In the mump2p killer apps post, at what delay did Gossipsub deliver 4 MB blocks on the 36 node testnet, versus mump2p's roughly 1 second?", "a": ["1.6 seconds, a 60% latency increase", "2.6 seconds, a 160% latency increase", "1.1 seconds, a 10% latency increase", "4 seconds, a 300% latency increase"], "why": "With 36 nodes, mump2p held about 1 second for 4, 6 and 10 MB blocks while Gossipsub needed 1.6 seconds just for 4 MB, and fell further behind as blocks grew.", "vol": true},
    {"id": "e_fifty", "tag": "stress", "src": "blogapps", "q": "In the mump2p killer apps post, what early test result does Optimum say its previous post on validators had shown?", "a": ["50%+ latency improvements", "6x latency improvements", "Twice the block throughput", "Finality in under one second"], "why": "The earliest validator tests showed over 50% lower latency. Later Hoodi runs pushed that to 6x, but the 50% figure was the first public result.", "vol": true},
    {"id": "e_usagegrows", "tag": "stress", "src": "blogdecent", "q": "What does Decentralize to Scale claim happens to RLNC performance as a chain's usage grows?", "a": ["It gets better as usage grows", "It stays flat regardless of usage", "It degrades slowly with usage", "It needs more hardware to keep up"], "why": "RLNC and OptimumP2P are built to scale with transaction counts and message sizes, so heavier usage is where they shine rather than where they strain."},
    {"id": "e_twofactors", "tag": "flex", "src": "blogflex", "q": "In the Flexnodes post, which two factors determine how fast validators collect enough equations to decode a block?", "a": ["Bandwidth and location", "CPU speed and memory", "Stake size and uptime", "Client type and OS"], "why": "Bandwidth sets how many equations can be sent per unit of time and location sets how far they travel. Flexnodes add bandwidth and shorten distance."},
    {"id": "e_viagateway", "tag": "flex", "src": "blogflex", "q": "How does a Flexnode first obtain block data, according to the Flexnodes post?", "a": ["By picking it up via a gateway, like a normal peer", "By downloading it from a central Optimum server", "By proposing the block itself", "By reading it from a validator's keystore"], "why": "A Flexnode behaves like an ordinary peer: it receives block data through a gateway, then shards and codes it into equations to forward."},
    {"id": "e_signal", "tag": "flex", "src": "blogflex", "q": "Until when do validators keep signaling Flexnodes that they need more equations, per the Flexnodes post?", "a": ["Until the decoding threshold is hit", "Until the slot ends", "Until every Flexnode has replied", "Until a fixed 10 equations arrive"], "why": "Validators ask for equations only as long as they still cannot decode. Once enough independent equations arrive, the requests stop."},
    {"id": "e_variants", "tag": "flex", "src": "blogflex", "q": "What does a Flexnode produce while it forwards equations, thanks to RLNC recoding?", "a": ["New equation variants", "Exact copies of the original block", "Compressed block headers", "Signed attestations"], "why": "Recoding lets a Flexnode mix the equations it holds into fresh variants, so validators collect useful new combinations faster."},
    {"id": "e_rollout", "tag": "flex", "src": "blogflex", "q": "Who did the Flexnodes post say would likely be the first Flexnode operators in the short term controlled rollout?", "a": ["Its existing validator partners", "Anyone with a browser extension", "Mobile wallet users", "Random community volunteers"], "why": "Before opening Flexnodes to everyone, Optimum planned a controlled start with the validator partners it already works with.", "vol": true},
    {"id": "e_uiforms", "tag": "flex", "src": "blogflex", "q": "In what forms does the Flexnodes post imagine packaging Flexnodes for non technical users in the long term?", "a": ["An app, browser extension, or wallet integration", "A Docker image and Helm chart", "A dedicated hardware box", "A command line validator client"], "why": "Because RLNC propagation needs little hardware, the long term vision is a simple interface such as an app, extension or wallet plugin.", "vol": true},
    {"id": "e_forcemult", "tag": "flex", "src": "blogflex", "q": "What phrase does the Flexnodes post use for the combined effect of more bandwidth plus more equation variants?", "a": ["A force multiplier for fast propagation", "A single point of failure", "A consensus accelerator", "A latency ceiling"], "why": "More bandwidth to send equations and more variants of them together make Flexnodes a force multiplier for protocols like mump2p."},
    {"id": "e_flexderam", "tag": "flex", "src": "blogflex", "q": "Besides fast propagation, which future Optimum product does the Flexnodes post say Flexnodes will underpin?", "a": ["DeRAM for data storage", "A new Layer 2 rollup", "An MEV relay", "A staking pool"], "why": "Flexnodes are the foundation for the propagation protocol today and for future products like DeRAM, Optimum's decentralized memory for storage.", "vol": true},
    {"id": "e_decfactors", "tag": "flex", "src": "blogdecent", "q": "Which of these does Decentralize to Scale list as a factor for judging how decentralized a chain is?", "a": ["Hardware, bandwidth and stake needed to run a validator", "Total value locked across its DeFi protocols", "Number of dApps deployed on the chain", "Uptime of the chain's main block explorer"], "why": "High hardware, bandwidth or stake requirements shut out smaller validators, so the post counts them among the signals of centralization."},
    {"id": "e_sliding", "tag": "flex", "src": "blogdecent", "q": "How does Decentralize to Scale describe the blockchain trilemma?", "a": ["A sliding scale, not a hard one or the other choice", "A hard binary choice between speed and security", "A myth with no real tradeoffs", "A problem only Layer 2s face"], "why": "The post frames the trilemma as a sliding scale where chains give a little on one side to strengthen another, which is what Optimum wants to escape."},
    {"id": "e_truescaling", "tag": "flex", "src": "blogdecent", "q": "Complete the closing line of Decentralize to Scale: \"True scaling emerges from decentralization, ...\"", "a": ["not despite it", "not because of it", "only on Solana", "only with more hardware"], "why": "The whole post argues that with RLNC each new node adds coding diversity, so decentralization becomes the source of scale rather than its cost."},
    {"id": "e_hetzner", "tag": "flex", "src": "blogdecent", "q": "Which incident does Decentralize to Scale cite as an example of centralization magnifying infrastructure risk?", "a": ["A cloud provider banning a large chunk of Solana validators", "A DNS outage knocking the Ethereum Foundation offline", "A handshake bug taking down Lighthouse validators", "A contentious fork splitting Bitcoin Core developers"], "why": "When many validators sit with one cloud provider, a single ban can knock out a big slice of the network. The post uses this to show why decentralization matters."},
    {"id": "e_udan", "tag": "hoodi", "src": "home", "q": "What does Optimum's home page call Optimum?", "a": ["The Universal Data Acceleration Network", "A Layer 2 rollup for Ethereum", "A decentralized sequencer network", "A consensus client for validators"], "why": "Optimum positions itself as a data acceleration network that speeds up any blockchain, not as a chain, rollup or client."},
    {"id": "e_patents", "tag": "hoodi", "src": "blogfree", "q": "Per the Free and faster post, who primarily holds the patents behind RLNC?", "a": ["Universities such as MIT and Harvard", "Optimum itself, as the commercial operator", "The Ethereum Foundation's research arm", "A consortium of enterprise validators"], "why": "The RLNC patents sit with universities such as MIT, Harvard and National University of Ireland, not a corporation, and licensing revenue flows back into their research and teaching."},
    {"id": "e_license", "tag": "hoodi", "src": "blogfree", "q": "What kind of license does Optimum hold on RLNC technology in Web3, per the Free and faster post?", "a": ["An exclusive license that it pays for", "A free perpetual license", "A public domain grant", "A revocable one year trial"], "why": "Optimum has an exclusive Web3 license to RLNC and pays the universities for it, which is why the RLNC library is source available rather than fully open."},
    {"id": "e_srcavail", "tag": "hoodi", "src": "blogfree", "q": "How does the Free and faster post describe the RLNC library that the gateway calls?", "a": ["Source available, inspectable but not forkable", "Fully open source under the MIT license", "Closed source with no inspection allowed", "Public domain with no license at all"], "why": "The library can be read, audited and researched, but unlike the gateway it cannot be forked or reused, because of the university license.", "vol": true},
    {"id": "e_papertitle", "tag": "hoodi", "src": "blogfree", "q": "What is the title of Optimum's 2025 research paper cited in the Free and faster post?", "a": ["OptimumP2P: Fast and Reliable Gossiping in P2P Networks", "RLNC: Coding for the World Computer", "mump2p: A Sidecar for Ethereum", "Flexnodes: Latency Markets at Scale"], "why": "The 2025 arXiv paper describes the RLNC based gossip protocol behind the network and the RUGBY pollution avoidance protocol."},
    {"id": "e_lidohoodi", "tag": "hoodi", "src": "blogfree", "q": "Per the Free and faster post, where should Lido operators start when onboarding to mump2p?", "a": ["On Hoodi first", "Directly on mainnet", "On Sepolia", "On a private devnet"], "why": "Lido operators are asked to begin on the Hoodi testnet before mainnet, while EtherFi operators had already received onboarding details.", "vol": true},
    {"id": "e_sidecardown", "tag": "hoodi", "src": "home", "q": "Per Optimum's FAQ, what happens to a validator's ability to attest and propose if the mump2p sidecar goes down?", "a": ["It is unaffected", "It pauses until restart", "It falls back to a backup relay", "It is slashed"], "why": "Gossipsub keeps running in parallel the whole time and consensus has no dependency on mump2p, so losing the sidecar costs nothing but the speedup."},
    {"id": "e_nokeys", "tag": "hoodi", "src": "home", "q": "According to Optimum's FAQ, what access does Optimum have to validator keys?", "a": ["None at all", "Read only access", "Access during proposals only", "Access via the sidecar"], "why": "Optimum works purely at the propagation layer. It never touches keys, signing or leader selection, it only changes how data moves."},
    {"id": "e_hoodiops", "tag": "hoodi", "src": "home", "q": "Which operators does Optimum's FAQ name among the initial group running mump2p on Hoodi?", "a": ["Everstake, P2P.org, Blockdaemon and Luganodes", "Coinbase Cloud, Kraken, Binance and OKX", "Lido, Rocket Pool, Frax and StakeWise", "Consensys, Nethermind, Sigma Prime and Teku"], "why": "The Hoodi rollout started with professional node operators such as Everstake, P2P.org, Blockdaemon, Infstones, Luganodes and Ebunker.", "vol": true},
    {"id": "e_acd", "tag": "hoodi", "src": "blogintro", "q": "What three properties does Optimum deRAM guarantee, per the Introducing Optimum post?", "a": ["Atomicity, Consistency, and Durability", "Availability, Confidentiality, and Decentralization", "Atomicity, Compression, and Delivery", "Accuracy, Coverage, and Density"], "why": "deRAM borrows the database idea of ACID but promises Atomicity, Consistency and Durability, shortened to ACD, for real time state access."},
    {"id": "e_memquote", "tag": "hoodi", "src": "blogintro", "q": "In Introducing Optimum, Muriel Médard says that if Web3 is a world computer, Optimum is building which critical component?", "a": ["Memory", "The CPU", "The network card", "The operating system"], "why": "The founding pitch treats blockchains as computers that already have an operating system and processors but lack a proper memory layer."},
    {"id": "e_firstround", "tag": "hoodi", "src": "bloghoodi", "q": "How did the Acceleration post frame its 150 ms Hoodi result?", "a": ["As only the first round of testnet improvements", "As the final production ready number", "As a theoretical maximum for the protocol", "As a measurement taken on Ethereum mainnet"], "why": "Optimum called 150 ms a first round result and promised to keep iterating, so the number is a floor on ambition rather than a finish line.", "vol": true},
    {"id": "e_overhead", "tag": "flood", "src": "blogfree", "q": "Why does scaling a gossip network usually force a choice between more participants and better performance, per the Free and faster post?", "a": ["Each new node adds gossip overhead", "Each new node needs its own validator key", "Each new node slows block execution", "Each new node must be whitelisted"], "why": "In plain gossip every extra node means more duplicate traffic, so growth makes propagation heavier. RLNC flips that by turning new nodes into coded capacity."},
    {"id": "e_membus", "tag": "flood", "src": "blogintro", "q": "What does Introducing Optimum say gossip networks have replaced in blockchains, at a cost in redundancy?", "a": ["Memory buses", "Hard drives", "CPUs", "Operating systems"], "why": "In a normal computer a memory bus moves data between CPU and RAM. Blockchains use gossip for that job, sending the same data to many nodes redundantly."},
    {"id": "e_avalanche", "tag": "flood", "src": "blogintro", "q": "Which network had to push a software update to reduce \"excessive gossip\" between validators, per Introducing Optimum?", "a": ["Avalanche", "Solana", "Polygon", "Cardano"], "why": "Introducing Optimum uses Avalanche's excessive gossip fix as evidence that broadcast everything to everyone networking strains real chains."},
    {"id": "e_eth2wire", "tag": "flood", "src": "blogintro", "q": "Per Introducing Optimum, how did Ethereum 2.0 respond to gossip message overload?", "a": ["With new wire protocols", "By halving the validator set", "By moving to Reed Solomon coding", "By switching to TCP only"], "why": "Ethereum 2.0 had to redesign its wire protocols to cut message overload, a sign that naive gossip did not scale for Ethereum 1.0 or Bitcoin."},
    {"id": "e_weidai", "tag": "flood", "src": "blogapps", "q": "In the Wei Dai quote featured in the mump2p killer apps post, what is named as the real bottleneck for chains?", "a": ["Data propagation, not execution", "Execution, not data propagation", "Consensus, not networking", "Storage, not bandwidth"], "why": "The quote argues that execution keeps up with demand today while Gossipsub style propagation caps performance, which is exactly the layer mump2p targets."},
    {"id": "e_prysm", "tag": "gateway", "src": "blogmetrics", "q": "In Behind the Metrics, why did the gateway first fail to connect to Teku and Lighthouse while Prysm worked?", "a": ["Teku and Lighthouse validate every byte of the handshake", "Teku and Lighthouse use a different serialization", "Prysm skips the handshake entirely", "Teku and Lighthouse reject sidecars by policy"], "why": "Consensus clients apply Ethereum's handshake with different strictness. Prysm is lenient while Teku and Lighthouse check every byte, so a loose implementation failed on them."},
    {"id": "e_strictfix", "tag": "gateway", "src": "blogmetrics", "q": "How did Optimum fix the consensus client handshake problem described in Behind the Metrics?", "a": ["Implemented the handshake to satisfy the strictest clients", "Dropped support for Teku and Lighthouse", "Patched Prysm to be stricter", "Routed through a proxy that skips handshakes"], "why": "The fix was to follow the strictest interpretation of the handshake. If Teku and Lighthouse accepted it, the more lenient Prysm would too."},
    {"id": "e_counters", "tag": "gateway", "src": "blogmetrics", "q": "Which two counters does the gateway increment for messages arriving from consensus clients and messages forwarded to the Optimum network?", "a": ["libp2p_total_messages and optimum_total_messages", "consensus_ingress_total and optimum_egress_total", "gossipsub_blocks_received and rlnc_blocks_forwarded", "cl_messages_in and mump2p_messages_out"], "why": "Ingress from the consensus client bumps libp2p_total_messages and egress to Optimum bumps optimum_total_messages, giving a simple throughput view at both ends."},
    {"id": "e_gwpeers", "tag": "gateway", "src": "bloghoodi", "q": "In the Hoodi setup from the Acceleration post, how do node operators take part?", "a": ["They run gateways as peers and connect beacon nodes to them", "They replace their beacon nodes with Optimum run nodes", "They submit each block to a central Optimum relay", "They run a modified Prysm fork supplied by Optimum"], "why": "Each operator runs a gateway as a network peer and points its beacon node at it. A block reaching any gateway enters the Optimum Network from there."},
    {"id": "e_150b", "tag": "mainnet", "src": "bloghoodi", "q": "How big an industry does the Acceleration post say ETH staking is?", "a": ["About $150 billion", "About $15 billion", "About $1.5 trillion", "About $500 million"], "why": "With $150 billion staked, even a small APY boost from faster propagation adds up to very large network wide validator profits.", "vol": true},
    {"id": "e_paying", "tag": "mainnet", "src": "blogfree", "q": "Who does the Free and faster post say Optimum intends to charge, given that validators ride for free?", "a": ["Traders, market makers and infrastructure providers", "Ethereum consensus client teams", "Lido and EtherFi staking operators", "Block explorers and data indexers"], "why": "Validators are the first users but not customers. A fast, predictable network makes latency sensitive products possible, and those are what Optimum will sell.", "vol": true},
    {"id": "e_40plus", "tag": "mainnet", "src": "blogfree", "q": "Per the Free and faster post, mump2p is being implemented on Ethereum mainnet with how many validators and node operators?", "a": ["A group of 40+ enterprise grade operators", "About 7 early validator operators", "Over 1000 solo home stakers", "Exactly 100 permissionless operators"], "why": "The mainnet rollout began with more than 40 enterprise grade validators and node operators, each connecting through an API key during the permissioned phase.", "vol": true},
    {"id": "e_solleader", "tag": "mainnet", "src": "blogdecent", "q": "How often does Solana rotate block leaders, per Decentralize to Scale?", "a": ["Roughly every four blocks, about 1.6 seconds", "Every block, about 400 ms", "Every epoch, about 2 days", "Every 32 blocks, about 12 seconds"], "why": "Solana's stake weighted schedule hands leadership to a new validator about every four blocks, which drives its throughput but concentrates power in large stakers.", "vol": true},
    {"id": "e_spikes", "tag": "subsea", "src": "blogmetrics", "q": "What causes the regular 200 to 250 ms spikes in mump2p latency on Hoodi, per Behind the Metrics?", "a": ["Cross continental routing when blocks cross from Europe to Asia", "Garbage collection pauses inside the gateway process", "Validators restarting their clients at every epoch boundary", "Prometheus scraping overhead on the gateway hosts"], "why": "Geography and physics: a block born in Europe must cross continents to reach Asia, and transient congestion on those routes hits the whole fleet at once.", "vol": true},
    {"id": "e_regions", "tag": "subsea", "src": "blogmetrics", "q": "In which regions were Optimum's Hoodi gateways distributed at the time of Behind the Metrics?", "a": ["US, EU, and Asia", "US only", "EU and Africa", "Asia and South America"], "why": "The 30 gateways sat across the US, EU and Asia to mimic Ethereum's real geographic spread, which is also why cross continental spikes appear.", "vol": true},
    {"id": "e_lossaccum", "tag": "subsea", "src": "blogapps", "q": "Per the killer apps post, how does mump2p avoid the compounding packet losses that plague Turbine and Rotor?", "a": ["Data is recoded on the fly, so missing pieces are regenerated continuously", "Every packet is retransmitted three times over separate routes", "Each hop acknowledges every packet before the next hop sends", "Blocks are shrunk until each one fits inside a single packet"], "why": "Because each hop recodes, a lost packet is replaced by fresh combinations downstream instead of accumulating as a gap that must be retransmitted."},
    {"id": "e_rugby", "tag": "shard", "src": "blogfree", "q": "What is RUGBY, described alongside the gossip protocol in Optimum's 2025 OptimumP2P paper?", "a": ["A pollution avoidance protocol for peer to peer networks", "A mesh pruning heuristic for Gossipsub topics", "A compression scheme for Ethereum blob data", "A reward formula for Flexnode operators"], "why": "RUGBY keeps the network propagating useful data even when some peers are faulty or adversarial, which matters once anyone can contribute coded shards."},
    {"id": "e_threeprops", "tag": "shard", "src": "blogdecent", "q": "Which three RLNC properties does Decentralize to Scale say let it thrive in massive distributed networks?", "a": ["Recoding, early forwarding, and decoding from any shard mix", "Hashing, signing, and ordering of every packet", "Sharding, pruning, and caching of block data", "Compression, encryption, and routing of messages"], "why": "Nodes can recode what they hold, forward before decoding, and decode from any sufficient mix of shards, so bigger networks help instead of hurting."},
    {"id": "e_algebraic", "tag": "shard", "src": "hamming", "q": "Per the Hamming Medal post, how does RLNC treat data to achieve its efficiency?", "a": ["As algebraic equations rather than discrete packets", "As encrypted blobs rather than plain text", "As Merkle leaves rather than lists", "As fixed size frames rather than streams"], "why": "Treating data as equations means any node can combine or regenerate pieces mathematically, which is what gives RLNC its resilience and speed."},
    {"id": "e_morblobs", "tag": "blob", "src": "blogapps", "q": "Per the killer apps post, what does sending small coded pieces instead of full blobs free up capacity for?", "a": ["Larger blocks or more blobs per block", "Longer slot times", "More validator keys", "Bigger mempools"], "why": "Not sending whole blobs to every peer cuts redundant traffic, and that saved bandwidth can carry bigger blocks or more blobs in each one."},
    // batch F: written from the corpus snapshot of 2026-10-02, every answer backed by a verbatim passage of its source
    {"id": "f_biduplift", "tag": "mainnet", "src": "blogapr", "q": "In Optimum's ETH staking revenue study, what average relative MEV bid value uplift does 50 to 150 ms of extra usable slot time give?", "a": ["About 13% to 16%", "About 1% to 2%", "About 30% to 40%", "About 50% to 60%"], "why": "Waiting a little longer lets a proposer see later, higher builder bids. The study measured that as a 13% to 16% average uplift in bid value.", "vol": true},
    {"id": "f_weeklyeth", "tag": "mainnet", "src": "blogapr", "q": "Over one week of bid traces, roughly how much extra revenue did Optimum's staking study find sitting in higher bids that arrived just too late?", "a": ["About 150 to 190 ETH", "About 15 to 19 ETH", "About 1,500 to 1,900 ETH", "About 5 to 10 ETH"], "why": "Small per slot gains add up: across a week the later, higher bids summed to roughly 150 to 190 ETH that proposers could have captured with more slot time.", "vol": true},
    {"id": "f_headvoteup", "tag": "mainnet", "src": "blogapr", "q": "Per Optimum's staking study, cutting network latency by 50 to 150 ms would lift network wide head vote accuracy to roughly what level?", "a": ["About 98.8% to 99.1%", "About 95% to 96%", "About 99.9%", "About 90% to 92%"], "why": "Blocks that arrive sooner let more validators vote for the right head in time, moving accuracy from about 98.6% up to roughly 98.8% to 99.1%.", "vol": true},
    {"id": "f_ceiling", "tag": "mainnet", "src": "blogapr", "q": "Why does Optimum's staking study put the theoretical ceiling for head vote accuracy near 99.4% rather than 100%?", "a": ["About 0.6% of slots are missed, and a missed slot always scores zero", "Network latency can never be driven all the way down to zero", "Some validators are always offline for client maintenance", "Attestation counts are capped by the committee size each slot"], "why": "When a slot has no block, nobody can vote correctly for it, so the roughly 0.6% of missed slots sets a hard ceiling that no amount of propagation speed can fix.", "vol": true},
    {"id": "f_halfgap", "tag": "mainnet", "src": "blogapr", "q": "According to Optimum's staking study, how much of the gap between today's head vote accuracy and the theoretical optimum can latency improvements alone close?", "a": ["More than half of it", "About a tenth of it", "Almost none of it", "All of it"], "why": "Faster propagation cannot fix missed slots, but it addresses more than half of the remaining distance to the protocol's ceiling."},
    {"id": "f_mevshare", "tag": "mainnet", "src": "blogapr", "q": "Per Optimum's staking study, roughly what share of Ethereum validators rely on external MEV builders via PBS or MEV-Boost instead of building blocks locally?", "a": ["More than 90%", "About half", "About a quarter", "Fewer than 10%"], "why": "Almost all validators outsource block building, which is why the value of extra slot time shows up mostly as higher builder bids.", "vol": true},
    {"id": "f_p80def", "tag": "stress", "src": "blogapr", "q": "In Optimum's staking study, what does the p80 propagation latency measure?", "a": ["The time for a block to reach 80% of nodes", "The time for 80% of attestations to arrive", "The 80th slowest block in an epoch", "The latency of the 80 largest validators"], "why": "p80 is a reach metric: how long until 80% of nodes have the block. The study uses it as the practical point where a block is safely out there."},
    {"id": "f_stake40", "tag": "mainnet", "src": "blogapr", "q": "Why does Optimum's staking study treat p80 propagation as a useful safety proxy for a proposer?", "a": ["It should mean at least 40% of stake can attest before the 4 second deadline", "It guarantees the block is finalized within one slot", "It equals the share of stake needed for finality", "It matches the committee size in each slot"], "why": "Reaching 80% of nodes stands in for 40% of stake attesting before the 4 second mark, which the study says is usually enough to prevent a reorg."},
    {"id": "f_timinggame", "tag": "mainnet", "src": "blogapr", "q": "In Optimum's staking study, what is the name for a proposer's balancing act between proposing early for safe propagation and late for higher bids?", "a": ["A timing game", "A fee auction", "A fork choice", "A sealed bid"], "why": "Proposers play a timing game: earlier means safer propagation, later means seeing more builder bids. Lower latency shifts that balance in their favor."},
    {"id": "f_steeper", "tag": "mainnet", "src": "blogapr", "q": "Per Optimum's staking study, which validators gain the most APR from a given latency reduction?", "a": ["Those who proposed early in the slot to prioritize safety", "Those already proposing at the latest safe moment", "Those with the largest stake", "Those running the newest client software"], "why": "Validators that proposed early for safety sit on the steeper part of the APR versus latency curve, so extra usable slot time moves them further."},
    {"id": "f_20x", "tag": "mainnet", "src": "blogapr", "q": "What does Optimum's staking study say about the largest MEV bid uplifts seen with extra slot time?", "a": ["Some reached up to 20x, a sign of a heavy tailed market", "They never exceeded 2x even in the busiest slots", "Relay rules capped every uplift at 5x", "They appeared only on the Hoodi testnet"], "why": "Most slots gain a modest amount, but a few late bids were worth up to 20 times the chosen one, which is what a heavy tailed MEV market looks like.", "vol": true},
    {"id": "f_sharpdrop", "tag": "mainnet", "src": "blogapr", "q": "In Optimum's one month head vote data, what happens once p80 block arrival latency approaches about 4 seconds?", "a": ["Accuracy drops sharply as validators fall back to attesting to the previous block", "Accuracy rises because late blocks get proposer boost", "Nothing changes until the 8 second mark", "Validators stop attesting entirely for that epoch"], "why": "Validators must vote around 4 seconds in. If the block has not reached them yet, they vote for the old head, so accuracy falls off a cliff there."},
    {"id": "f_variancekey", "tag": "mainnet", "src": "blogpbs", "q": "In \"The Cost of Uncertainty in Ethereum's PBS Hot Path\", what does Optimum say is the critical variable, more than latency itself?", "a": ["Variance in propagation time", "The size of each block", "The gas price in the slot", "The number of validators"], "why": "A known, steady delay can be planned around. What breaks PBS optimization is not knowing whether a message will arrive early or late."},
    {"id": "f_hedgeloop", "tag": "mainnet", "src": "blogpbs", "q": "Per Optimum's PBS hot path post, what happens when every PBS participant hedges against propagation variance?", "a": ["The hedging amplifies the very uncertainty it tried to mitigate", "Variance disappears because everyone's cutoffs line up", "Relays sit idle around the proposer cutoff", "Builders stop submitting bids late in the slot"], "why": "Early cutoffs push bid bursts into the busiest moment of the slot, relays absorb that load, and variance grows. Each rational hedge feeds the loop."},
    {"id": "f_vanilla", "tag": "mainnet", "src": "blogpbs", "q": "In Optimum's PBS hot path post, what is a \"vanilla block\"?", "a": ["A locally built block with no MEV", "A block with only blob transactions", "An empty block with no transactions", "A block built by the top relay"], "why": "If no builder bid arrives in time, the proposer falls back to a plain block it built itself, giving up the MEV a builder would have paid for."},
    {"id": "f_8sec", "tag": "mainnet", "src": "blogpbs", "q": "Per Optimum's PBS hot path post, before which deadline must an attester vote correctly to earn the full reward?", "a": ["The 8 second mark", "The 4 second mark", "The 12 second mark", "The 2 second mark"], "why": "The post lists binary cutoffs: a block reaching 40% of stake before 4 seconds, and a correct attestation before 8 seconds. A late vote loses the reward.", "vol": true},
    {"id": "f_atlantic", "tag": "subsea", "src": "blogpbs", "q": "How does Optimum's PBS hot path post explain validator concentration around the Atlantic corridor?", "a": ["An economic response: being near relays and builders cuts exposure to variance", "A legacy of where the early mining pools and exchanges were hosted", "A result of cheaper electricity and hosting costs in that region", "A requirement written into the beacon chain networking spec"], "why": "Being close to the dominant relay and builder infrastructure makes delivery more predictable, so the market quietly rewards clustering there."},
    {"id": "f_liveness", "tag": "subsea", "src": "blogpbs", "q": "Per research cited in Optimum's PBS hot path post, what does Ethereum's liveness coefficient trending toward one imply?", "a": ["A single regional outage would be enough to halt the chain", "Finality would take one epoch longer", "One relay would carry all bids", "Block times would drop to one second"], "why": "Geographic clustering driven by variance has a cost: the cited modeling finds one regional outage could be sufficient to halt the chain.", "vol": true},
    {"id": "f_top5", "tag": "mainnet", "src": "blogpbs", "q": "Per Optimum's PBS hot path post, roughly what combined annual gain would 150 ms of extra slot time mean for the top five staking operators?", "a": ["About $6M", "About $400K", "About $60M", "About $1M"], "why": "At about +1.97% APR for the five largest operators, the post puts the combined figure near $6M per year, all from a slightly later cutoff.", "vol": true},
    {"id": "f_90nodes", "tag": "stress", "src": "blogpbs", "q": "In the benchmark cited in Optimum's PBS hot path post (a network of up to 90 nodes), how much faster was mump2p's p95 latency than GossipSub?", "a": ["150% faster", "15% faster", "6x faster", "2x faster"], "why": "In that benchmark mump2p delivered 150% faster p95 latency, and the post pairs it with roughly 7x lower propagation variance.", "vol": true},
    {"id": "f_peerdas", "tag": "blob", "src": "blogpbs", "q": "Per Optimum's PBS hot path post, what did studies from EthPandaOps, MigaLabs and Chainbound confirm about growing payload sizes after PeerDAS?", "a": ["Head vote accuracy drops, missed slots climb, attestation quality worsens", "Propagation got faster because sampling shrinks what each node downloads", "Validator counts rose sharply as cheaper blobs attracted new operators", "Blob fees fell to zero because supply finally outran rollup demand"], "why": "Bigger payloads mean more data to move in the same slot. The independent studies all saw consensus quality degrade as sizes grew."},
    {"id": "f_blobunder", "tag": "blob", "src": "blogpbs", "q": "How does Optimum's PBS hot path post explain Ethereum running well below its target blob count?", "a": ["The market responding to the cost of uncertainty, not a lack of demand", "Rollups moving most of their data to other data availability layers", "Blob fees that are still too high for most rollups to justify", "Clients capping the number of blobs per block by default"], "why": "Blob carrying transactions pay more, but miss rates spike at high blob loads, so actors exposed to propagation variance often decide the risk is not worth it.", "vol": true},
    {"id": "f_scarce", "tag": "mainnet", "src": "blogpbs", "q": "Per Optimum's PBS hot path post, what is the scarce resource in Ethereum's blockspace market today?", "a": ["Reliable delivery under uncertainty", "The value packed into each block", "The amount of validator stake", "Headroom under the gas limit"], "why": "In a healthy blockspace market the scarce thing would be block value. With propagation variance, whoever can deliver reliably wins instead."},
    {"id": "f_turbinebt", "tag": "mainnet", "src": "blogsol", "q": "Per Optimum's Solana post, Solana's Turbine block propagation protocol was inspired by what?", "a": ["BitTorrent", "Gossipsub", "The Kademlia DHT", "Ethereum's devp2p stack"], "why": "Like BitTorrent, Turbine splits a block into small pieces and spreads them through a layered fanout instead of sending whole blocks to every node."},
    {"id": "f_shreds", "tag": "mainnet", "src": "blogsol", "q": "In Solana's Turbine, as described by Optimum, what are the small packets a leader splits each block into called?", "a": ["Shreds", "Shards", "Blobs", "Cells"], "why": "A Solana leader cuts its block into data shreds sized to fit the network MTU, then adds Reed-Solomon coding shreds for redundancy."},
    {"id": "f_stakeweight", "tag": "mainnet", "src": "blogsol", "q": "Per Optimum's Solana post, which validators does Turbine's stake weighted tree deliver shreds to first?", "a": ["Validators with higher stake", "Validators closest to the leader geographically", "Validators with the lowest latency last epoch", "Validators chosen at random each slot"], "why": "Big stakers vote sooner so blocks confirm fast, but smaller nodes can end up consistently a few hops behind, which raises fairness questions."},
    {"id": "f_udploss", "tag": "subsea", "src": "blogsol", "q": "What tradeoff does Optimum's Solana post note about Turbine sending shreds over UDP?", "a": ["UDP does not guarantee delivery, so shreds can drop under congestion", "UDP requires a full handshake before every single shred is sent", "UDP caps each packet at about 100 bytes, forcing many more shreds", "UDP only works between validators inside the same datacenter"], "why": "UDP is light and fast, but packets can vanish under congestion. Turbine leans on erasure coded redundancy and multiple forwarders to cope."},
    {"id": "f_25mbps", "tag": "subsea", "src": "blogsol", "q": "Per Optimum's Solana post, roughly how much bandwidth does running an Ethereum node need, far less than a Solana node?", "a": ["Roughly 25 Mbps", "Roughly 1 Gbps", "Roughly 10 Gbps", "Roughly 2 Mbps"], "why": "Solana pushes far more transactions through, so its nodes need much more bandwidth than Ethereum's roughly 25 Mbps.", "vol": true},
    {"id": "f_shredstream", "tag": "subsea", "src": "blogsol", "q": "Per Optimum's Solana post, what is ShredStream?", "a": ["A complementary Jito Labs feed that speeds up block data delivery", "Solana's protocol for broadcasting consensus votes between validators", "An Anza tool that streams historical ledger data for indexing", "A Solana light client that verifies blocks by sampling shreds"], "why": "ShredStream taps leaders directly so RPC nodes and traders get block data a few hops earlier than normal Turbine propagation would deliver it."},
    {"id": "f_everstake", "tag": "stress", "src": "blogsol", "q": "Per Everstake measurements cited in Optimum's Solana post, raw shred streams can cut a typical ~400 ms public RPC delay down to roughly what, in a nearby region?", "a": ["On the order of 10 to 50 ms", "On the order of 200 to 300 ms", "Under 1 ms", "About 1 second"], "why": "Skipping hops makes a huge difference: from about 400 ms for a public RPC feed to tens of milliseconds for a nearby raw shred stream.", "vol": true},
    {"id": "f_jetstreamer", "tag": "stress", "src": "blogsol", "q": "Per Optimum's Solana post, what replay throughput did Anza's JetStreamer reach on a 64 core machine with a 30 Gbps link?", "a": ["Over 2.7 million transactions per second", "About 50,000 transactions per second", "About 270,000 transactions per second", "About 27 million transactions per second"], "why": "JetStreamer is not consensus, but it shows that with enough bandwidth and optimized code, data movement can scale far beyond live network norms.", "vol": true},
    {"id": "f_400slot", "tag": "mainnet", "src": "blogsol", "q": "Per Optimum's Solana post, roughly how long is a Solana slot, which makes even a 100 ms propagation delay significant?", "a": ["About 400 ms", "About 12 seconds", "About 2 seconds", "About 40 ms"], "why": "With slots of only about 400 ms, a 100 ms propagation delay eats a quarter of the slot, so propagation speed matters enormously on Solana.", "vol": true},
    {"id": "f_rsstall", "tag": "shard", "src": "blogsol", "q": "Per Optimum's Solana post, what weakness do Turbine's Reed-Solomon codes have that RLNC avoids?", "a": ["Propagation stalls when intermediate nodes miss too many packets", "Shreds cannot be verified by signature", "Coding shreds are larger than data shreds", "Decoding needs the leader's private key"], "why": "With fixed Reed-Solomon shreds, a relay that lost too many packets has nothing useful to pass on. RLNC relays can recode and forward partial data instead."},
    {"id": "f_mincut", "tag": "shard", "src": "blogsol", "q": "Per Optimum's Solana post, why can RLNC tolerate partial relay failures better than a Turbine style tree?", "a": ["It only needs to cross the network's min cut, not every branch of the tree", "It retransmits every shred three times", "It routes only through the highest stake nodes", "It waits for full block reconstruction at each hop"], "why": "A tree depends on every layer working. Coded data only needs enough capacity across the network's min cut, so a failed branch is not fatal."},
    {"id": "f_4xloss", "tag": "stress", "src": "blogsol", "q": "Per benchmark models in Optimum's Solana post, how does RLNC compare with Reed-Solomon at the same redundancy under 1 to 5% network loss?", "a": ["Much lower residual loss and up to 4x lower latency", "Equal latency but half the bandwidth", "Higher latency but no residual loss", "Identical results at every loss rate"], "why": "At the same redundancy, RLNC loses far less data and delivers up to 4x faster under a few percent packet loss, and the gap widens with network depth.", "vol": true},
    {"id": "f_threeclients", "tag": "mainnet", "src": "eth", "q": "On Ethereum, which three pieces of software must a validator run after depositing 32 ETH?", "a": ["An execution client, a consensus client and a validator client", "A miner, a wallet and a relay", "A builder, a relay and a sequencer", "A light client, an archive node and a bootnode"], "why": "The execution client handles transactions, the consensus client follows the beacon chain, and the validator client signs duties like attestations.", "vol": true},
    {"id": "f_committees", "tag": "mainnet", "src": "eth", "q": "On Ethereum, why is the validator set divided into committees, with a committee chosen for each slot?", "a": ["To keep network load manageable, with each validator attesting once per epoch", "To let each committee propose its own competing block for the slot", "To reduce the 32 ETH stake that each validator needs to deposit", "To shorten each slot from 12 seconds down to a few seconds"], "why": "If every validator voted every slot, the gossip network would drown in attestations. Committees spread the voting across the epoch."},
    {"id": "f_latencyview", "tag": "mainnet", "src": "eth", "q": "On Ethereum, why might validators have different views of the head of the chain, requiring a fork choice algorithm?", "a": ["Network latency or an equivocating block proposer", "Different client software versions", "Differences in staked balance", "Because every slot has two proposers"], "why": "If a block reaches some validators late, they may vote for a different head. That is why propagation speed and the fork choice rule go hand in hand."},
    {"id": "f_inactivityleak", "tag": "mainnet", "src": "eth", "q": "On Ethereum, when does the inactivity leak activate?", "a": ["When the chain fails to finalize for more than four epochs", "When a block arrives after the 4 second mark of its slot", "When a validator misses two attestations in a row", "When a validator proposes two blocks for the same slot"], "why": "The leak drains stake from validators voting against the majority until the majority regains two thirds and can finalize again."},
    {"id": "f_gasper", "tag": "mainnet", "src": "gasper", "q": "On Ethereum, Gasper combines which two components?", "a": ["Casper FFG finality gadget and the LMD GHOST fork choice", "RANDAO proposer selection and the deposit contract", "Proposer builder separation and MEV-Boost relays", "Turbine style trees and Gossipsub meshes"], "why": "Casper FFG upgrades checkpoints to finalized, while LMD GHOST picks the heaviest fork when validators disagree about the head."},
    {"id": "f_forkneeded", "tag": "mainnet", "src": "gasper", "q": "On Ethereum, under what conditions is a fork choice algorithm actually needed, per the Gasper docs?", "a": ["Large network asynchronicity or a dishonest proposer equivocating", "Every slot, since there are always competing blocks", "Only at epoch boundaries", "Only when a validator is slashed"], "why": "Normally one proposer per slot and honest votes mean no forks. Slow or uneven propagation is one of the two things that makes fork choice matter."},
    {"id": "f_lmdmeaning", "tag": "mainnet", "src": "gasper", "q": "On Ethereum, what does the \"latest message driven\" part of LMD GHOST mean?", "a": ["If multiple messages come from a validator, only the latest is considered", "The newest block always wins the fork choice", "Messages are ordered by arrival time", "Only the proposer's message counts"], "why": "Each validator's most recent vote is the one that counts toward subtree weight, which also neutralizes avalanche style attacks."},
    {"id": "f_aggregators", "tag": "mainnet", "src": "attest", "q": "On Ethereum, how many validators in each subnet are selected as attestation aggregators per epoch?", "a": ["16", "64", "128", "4"], "why": "Aggregators collect matching attestations heard over gossip, merge the signatures, and broadcast one aggregate to the wider network.", "vol": true},
    {"id": "f_incldelay", "tag": "mainnet", "src": "attest", "q": "On Ethereum, what happens to an attestation reward if the inclusion delay doubles from one slot to two?", "a": ["It halves", "It is unchanged", "It doubles", "It drops to zero"], "why": "The base reward is multiplied by the reciprocal of the inclusion delay, so a vote that propagates slowly and lands a slot late earns half as much."},
    {"id": "f_flags", "tag": "mainnet", "src": "attest", "q": "On Ethereum, which three participation flags determine an attestation reward?", "a": ["Source, target and head", "Slot, index and root", "Proposer, builder and relay", "Justified, finalized and pending"], "why": "Each flag can be true or false depending on the vote and its inclusion delay. The head flag is the one most sensitive to how fast blocks arrive."},
    {"id": "f_whyaggregate", "tag": "flood", "src": "attest", "q": "On Ethereum, why are individual attestations aggregated within subnets before being broadcast more widely?", "a": ["Sending every validator's attestation around the network costs too much overhead", "Aggregation hides which individual validator voted for which head", "Only aggregated attestations can be used as evidence for slashing", "Subnets are unable to carry attestations with a single signature"], "why": "One aggregate carries the shared data plus a single combined BLS signature, so the whole network does not have to gossip every individual vote."},
    {"id": "f_twoepochs", "tag": "mainnet", "src": "proposal", "q": "On Ethereum, how far in advance is the block proposer selection fixed, to protect against seed manipulation?", "a": ["Two epochs", "Two slots", "One year", "Not at all"], "why": "RANDAO mixes proposer hashes into a seed, and locking the selection two epochs ahead makes it harder to game that seed."},
    {"id": "f_proposerpay", "tag": "mainnet", "src": "proposal", "q": "On Ethereum, how does the number of attestations included in a block affect the proposer's reward?", "a": ["A fraction of base_reward per valid attestation, so more attestations pay more", "The proposer reward is fixed regardless of how many attestations it includes", "More attestations reduce the reward because they make the block larger", "Only the first 64 attestations in a block earn the proposer anything"], "why": "A proposer is paid per attestation it packs in, so fast propagation that lets more validators see and vote on the chain head pays off directly."},
    {"id": "f_blockchecks", "tag": "mainnet", "src": "proposal", "q": "On Ethereum, which checks does a validator run on a received block before adding it to its chain?", "a": ["Correct parent and slot, expected proposer, valid RANDAO reveal, proposer not slashed", "A valid builder signature and the relay fee the proposer was paid", "A gas price above the base fee for every transaction in the payload", "That it contains at least one blob and one aggregate attestation"], "why": "After these checks the execution payload is unbundled and the transactions are re executed to confirm the proposed state change."},
    {"id": "f_pbsblind", "tag": "mainnet", "src": "pbs", "q": "On Ethereum's planned proposer builder separation, what does the block proposer know about the block it chooses?", "a": ["Nothing of its contents; it simply picks the most profitable offer", "Every transaction, which it may reorder before broadcasting", "Only the blob data attached to the execution payload", "Only the sender addresses of the included transactions"], "why": "Builders build, proposers pick the best bid and broadcast. Not seeing the contents is what removes the proposer's ability to censor or steal MEV."},
    {"id": "f_inclusionlists", "tag": "mainnet", "src": "pbs", "q": "On Ethereum, what are inclusion lists meant to do under PBS?", "a": ["Let proposers force known transactions into the next block if builders omit them", "Rank block builders by reputation so proposers can prefer trusted ones", "Cap the number of blobs a builder may put into a single block", "List which validators are eligible to propose in the coming epoch"], "why": "The list comes from the proposer's own mempool and is sent to peers just before a block, giving proposers a lever against censoring builders.", "vol": true},
    {"id": "f_dank100k", "tag": "blob", "src": "pbs", "q": "On Ethereum's roadmap, Danksharding is meant to scale the chain to more than how many transactions per second?", "a": ["More than 100,000", "More than 1,000", "More than 10,000", "More than 2.7 million"], "why": "That scale comes from cheap rollup data, which means much larger payloads that the network layer has to propagate within each slot.", "vol": true},
    {"id": "f_mevdef", "tag": "mainnet", "src": "mev", "q": "On Ethereum, how is maximal extractable value (MEV) defined?", "a": ["Value beyond block reward and gas fees from how transactions are included and ordered", "The total gas fees paid by every transaction included in a block", "The staking yield a validator earns from attestations and proposals", "The fee a relay charges builders for forwarding their bids to proposers"], "why": "MEV is the extra value a block producer can capture by including, excluding or reordering transactions, on top of the standard reward and fees."},
    {"id": "f_reorgmev", "tag": "mainnet", "src": "mev", "q": "On Ethereum, what consensus risk arises when the MEV in a block far exceeds the standard block reward?", "a": ["Validators may be tempted to reorg blocks to capture the MEV themselves", "Blocks grow too large to propagate within the slot", "Gas prices collapse to zero across the network", "Attestations stop being rewarded for that epoch"], "why": "Big MEV can make rewriting recent history worth more than extending the chain, which threatens consensus stability."},
    {"id": "f_unconditional", "tag": "mainnet", "src": "mev", "q": "On Ethereum's PBS design, why don't validators have to trust builders not to withhold block bodies or publish invalid blocks?", "a": ["Payment to the validator is unconditional, even if the block is unavailable or invalid", "Builders must post a 32 ETH bond that is slashed on misbehavior", "Relays rebuild every winning block locally before forwarding it", "The proposer can sign a second block if the first one fails"], "why": "The proposer's fee goes through regardless. If the block turns out invalid it is discarded and the builder loses its fees and MEV, not the validator."},
    {"id": "f_builderapi", "tag": "mainnet", "src": "mev", "q": "On Ethereum, why is the Builder API described as a temporary solution for proposer builder separation?", "a": ["True PBS needs fork choice changes; the API works now with higher trust assumptions", "It is only allowed to run on testnets until in protocol PBS ships", "It expires automatically one year after a validator registers", "It supports only a single relay per validator at a time"], "why": "In protocol PBS would change the beacon chain's fork choice rule. The Builder API, used by MEV-Boost, gives a working version today with more trust.", "vol": true},
    {"id": "f_localfallback", "tag": "mainnet", "src": "mev", "q": "On Ethereum, why must a validator using the Builder API still build a block locally?", "a": ["In case the builder fails to respond promptly, so it does not miss proposal rewards", "To compare gas usage against the block the builder delivered", "Because relays require two candidate blocks from every proposer", "To earn a second proposer reward within the same slot"], "why": "The slot is short. If the builder is late with the full payload, the local block is the backup, though signing two blocks would be equivocation."},
    // batch G: written from the corpus snapshot of 2026-10-02, every answer backed by a verbatim passage of its source
    {"id": "g_audit", "tag": "gateway", "src": "gateway", "q": "Which firm independently audited the security of the Optimum Gateway?", "a": ["ProbeLab", "Trail of Bits", "Sigma Prime", "ConsenSys Diligence"], "why": "The Gateway README states the code was independently audited by ProbeLab, and links the audit report for anyone who wants to read it.", "vol": true},
    {"id": "g_mitpatent", "tag": "gateway", "src": "gateway", "q": "The Optimum Gateway source is under the MIT License. What does the README say about patent rights?", "a": ["MIT grants copyright permissions only, no patent rights", "MIT grants a worldwide royalty free patent license", "Patent rights are included for non commercial use", "Patent rights come automatically with any fork"], "why": "The MIT License covers copyright only. A separate PATENTS file lists patents, and any patent rights you need must come from the patent holder directly."},
    {"id": "g_ttlmin", "tag": "gateway", "src": "gateway", "q": "Roughly how long does the Optimum Gateway keep a message fingerprint in its dedup cache?", "a": ["About one minute", "About one second", "About one hour", "For the whole process lifetime"], "why": "Each message is fingerprinted with a fast hash and stored in a short TTL cache of about one minute, long enough to drop repeats without growing forever.", "vol": true},
    {"id": "g_telemetry3", "tag": "gateway", "src": "gateway", "q": "Besides lower propagation delay and better validator rewards, what third result does the Gateway README promise?", "a": ["Cross network latency telemetry", "Lower hardware requirements for the CL client", "Automatic MEV relay selection", "Faster execution layer sync"], "why": "The Gateway also records latency telemetry across both networks, so operators can see how the Ethereum path and the mump2p path compare."},
    {"id": "g_resilience", "tag": "gateway", "src": "gateway", "q": "Besides accelerating message propagation, which purpose does the Optimum Gateway integration guide list for the gateway?", "a": ["Improve resilience and redundancy across validator networks", "Replace the beacon node's own peer discovery", "Reduce the disk space a validator needs", "Provide MEV protection for proposers"], "why": "The guide lists three purposes: faster propagation through the mump2p mesh, more resilience and redundancy across validator networks, and no changes to the CL client code."},
    {"id": "g_bootstraprole", "tag": "gateway", "src": "gateway", "q": "In the Optimum Gateway topology, what does the Bootstrap service provide?", "a": ["Peer discovery, registration, fork digest and telemetry collection", "Block building and MEV relay bidding", "Checkpoint sync states for the beacon node", "Encoding of RLNC shards for every gateway"], "why": "Bootstrap is the coordination point: gateways register with it, learn the fork digest and peers from it, and report telemetry to it."},
    {"id": "g_gw2gw", "tag": "mesh", "src": "gateway", "q": "How do Optimum Gateways reach each other once they have joined the mump2p mesh?", "a": ["They connect directly to other gateways over the mesh", "All traffic is relayed through Bootstrap", "They tunnel through the beacon node's libp2p host", "Only through a central Optimum proxy"], "why": "Bootstrap only hands out peer addresses. After that, gateways talk to one another directly over the mump2p mesh."},
    {"id": "g_directpeers", "tag": "gateway", "src": "gateway", "q": "For which two consensus clients does the Gateway guide say the CL node must also be listed as a direct peer on the gateway side?", "a": ["Lighthouse and Nimbus", "Prysm and Teku", "Teku and Lodestar", "Prysm and Grandine"], "why": "Most clients only need a trusted peer entry pointing at the gateway, but for Lighthouse and Nimbus the guide also adds the CL node to the gateway's direct peer list."},
    {"id": "g_aggr25", "tag": "gateway", "src": "gateway", "q": "How often does the Optimum Gateway's aggregator batch messages for high volume topics?", "a": ["About every 25 milliseconds", "About every 250 milliseconds", "Once per slot", "Once per epoch"], "why": "The aggregator ticks roughly every 25 ms and packs whatever it has per topic into one container, trading a tiny delay for far fewer messages.", "vol": true},
    {"id": "g_protobuf", "tag": "gateway", "src": "gateway", "q": "How does the Gateway shrink the number of messages it sends for high volume topics like attestations?", "a": ["It aggregates several messages into one protobuf container", "It compresses each message with gzip", "It drops every second message", "It splits each message into RLNC shards itself"], "why": "Instead of sending thousands of small attestation messages, the aggregator wraps many of them into a single protobuf container that is unpacked on the other side."},
    {"id": "g_prysmmap", "tag": "gateway", "src": "gateway", "q": "Which client's gossip topic mappings does the Optimum Gateway rely on to decode consensus messages?", "a": ["Prysm", "Lighthouse", "Teku", "Nimbus"], "why": "The Gateway decodes CL messages using Prysm's topic mappings, which is handy but means updates may be needed when CL versions change."},
    {"id": "g_critpath", "tag": "gateway", "src": "gateway", "q": "What trade off does the Gateway architecture ADR name for running CL and mump2p bridging in one process?", "a": ["A bug can affect both directions at once", "Each direction needs its own API key", "Messages must be decoded twice", "The CL client has to be patched"], "why": "Being on the critical path for both networks is the cost of simplicity: a single bug in the gateway process can hurt traffic in both directions."},
    {"id": "g_opt2reject", "tag": "gateway", "src": "gateway", "q": "Why did the beacon block latency ADR reject embedding an ingress timestamp inside every mump2p message?", "a": ["A wire format change would need coordinated redeploys everywhere", "Timestamps cannot be serialized in SSZ", "It would reveal validator identities", "It would double the message size"], "why": "Changing the wire format touches every component that handles messages, gateway, proxy and P2P nodes, for a metric the backend could already compute."},
    {"id": "g_theoslot", "tag": "gateway", "src": "gateway", "q": "From what moment do the Gateway's slot based latency metrics start counting?", "a": ["The theoretical slot start time", "The moment the block entered Ethereum gossip", "The proposer's signing time", "The first attestation of the slot"], "why": "The gateway is a passive listener, so it can only measure from the theoretical slot start, not from when the proposer actually released the block."},
    {"id": "g_negdelta", "tag": "gateway", "src": "gateway", "q": "In the Gateway's beacon block latency model, what does a negative mum minus eth value mean?", "a": ["mump2p delivered the block first", "Ethereum gossip delivered the block first", "The block was never seen on mump2p", "The slot was skipped"], "why": "The delta subtracts the Ethereum arrival time from the mump2p arrival time, so a negative value means the mump2p copy came in earlier."},
    {"id": "g_timinggames", "tag": "mainnet", "src": "gateway", "q": "Why does the validator metrics ADR say slot start latency is a poor measure of what Optimum improves?", "a": ["Proposer timing games can delay blocks deep into the slot", "Slot start times differ per client", "Clocks on gateways cannot read slot numbers", "Attestations arrive before blocks"], "why": "Relays and proposers may hold blocks for seconds on purpose, and that delay is outside Optimum's control, so slot start latency mixes two different things."},
    {"id": "g_kpiwhere", "tag": "gateway", "src": "gateway", "q": "Under the Gateway's validator metrics redesign, where are stable KPIs computed?", "a": ["At the Bootstrap collector, from raw gateway events", "Inside each gateway's Prometheus exporter", "In the consensus client itself", "In the partner's Grafana dashboard"], "why": "Gateways only emit raw per block timestamps. Bootstrap collects them and computes baselines and stable KPIs that dashboards then read."},
    {"id": "g_gaptobest", "tag": "gateway", "src": "gateway", "q": "What does the Gateway KPI called gap to best measure for a block?", "a": ["How far behind the best gateway in the population this gateway saw it", "How long after slot start the proposer published it", "The difference between Eth and mump2p arrival at one gateway", "The number of mesh hops the block traveled"], "why": "Gap to best compares a gateway's first sight of a block with the earliest sight anywhere in the population, independent of when the proposer published."},
    {"id": "g_mumspread", "tag": "gateway", "src": "gateway", "q": "Which question does the Gateway's mum spread KPI answer?", "a": ["Once a gateway publishes a block into Optimum, how fast others receive it", "How long the proposer waited before publishing", "How many validators attested to the block", "How much bandwidth each shard consumed"], "why": "Mum spread starts the clock when the first gateway publishes into mump2p, isolating the part of propagation that Optimum actually controls."},
    {"id": "g_upstreamchain", "tag": "mesh", "src": "gateway", "q": "How does Bootstrap reconstruct the path a block took through the Gateway mesh?", "a": ["By following the upstream peer ID chain in gateway reports", "By reading the IP header of each shard", "By asking each gateway for its routing table", "By decoding the block's parent root"], "why": "Every mump2p message carries the immediate sender's peer ID, so Bootstrap can chain those upstream IDs together to trace the route."},
    {"id": "g_hermes", "tag": "gateway", "src": "gateway", "q": "What is a Hermes node in Optimum's block ingestion design?", "a": ["A lightweight node running Gossipsub to capture propagated blocks", "A full execution client with an archive database", "A relay that builds blocks for proposers", "A Bootstrap replica for peer discovery"], "why": "Hermes nodes are light Gossipsub listeners that just capture blocks. Unlike full CL nodes, several of them can hang off one CL and EL pair."},
    {"id": "g_relay3", "tag": "gateway", "src": "gateway", "q": "How many gateway nodes does Optimum plan to provide for each connected relay, and where?", "a": ["Three: one in the US, one in the EU, one in Asia", "One, hosted next to the relay", "Two: one primary and one backup", "Five, spread across every continent"], "why": "Giving each relay a gateway in each major region maximizes the chance of catching its blocks quickly no matter where they are published.", "vol": true},
    {"id": "g_bidtrace", "tag": "mainnet", "src": "gateway", "q": "How does Optimum find out which slots a given relay actually produced blocks for?", "a": ["By polling the relay's public bid trace endpoint", "By asking the relay operator over email", "By decoding the fee recipient in each block", "By scanning Bootstrap logs for the relay's IP"], "why": "Relays expose a public bid trace endpoint listing delivered payloads. Polling it gives the slots and proposer keys needed to attribute blocks to that relay."},
    {"id": "g_att30k", "tag": "mainnet", "src": "gateway", "q": "About how many attestations per slot does the Gateway's attestation ADR say flow across the Ethereum network?", "a": ["About 30,000", "About 3,000", "About 300,000", "About 640"], "why": "With 64 attestation subnets and tens of thousands of validators voting each slot, roughly 30,000 attestations cross the network per slot.", "vol": true},
    {"id": "g_wasted80", "tag": "flood", "src": "gateway", "q": "Before validator scoped filtering, roughly what share of attestation bytes crossing mump2p were duplicates?", "a": ["About 80 percent", "About 20 percent", "About 50 percent", "About 5 percent"], "why": "Every gateway forwarded every attestation it saw, so receivers deduplicated about 80 percent of what arrived, after the bytes had already been sent.", "vol": true},
    {"id": "g_dedupbytes", "tag": "flood", "src": "gateway", "q": "Why was receiver side deduplication not enough to fix attestation duplication in the Gateway mesh?", "a": ["The duplicate bytes had already traveled over mump2p", "The hash function produced collisions", "Deduplication only worked for beacon blocks", "The CL client rejected deduplicated messages"], "why": "Dropping duplicates on arrival protects the consensus client, but the bandwidth is spent before the drop, so the fix had to happen at the sender."},
    {"id": "g_partneronly", "tag": "gateway", "src": "gateway", "q": "Which attestations does the Optimum Gateway forward from its consensus client into mump2p?", "a": ["Only attestations from known partner validators", "Every attestation it receives", "Only attestations for the current proposer", "Only aggregated attestations"], "why": "The gateway's job is to accelerate its partner's validators, so it forwards only their attestations and trusts other gateways to do the same for theirs."},
    {"id": "g_jwtindexes", "tag": "gateway", "src": "gateway", "q": "How does the Gateway learn which validator indices belong to its partner?", "a": ["They arrive as a claim inside the JWT minted from the auth service", "They are read from the beacon node's validator API", "They are hard coded in the config file", "Bootstrap pushes them over the mesh"], "why": "The token the gateway mints from the auth service carries a validator indexes claim, and a background job keeps the local set in sync with it."},
    {"id": "g_lightssz", "tag": "gateway", "src": "gateway", "q": "Why does the Gateway peek at attestation SSZ bytes before fully decoding them?", "a": ["To avoid a full SSZ decode for attestations that get dropped", "To verify the BLS signature early", "To compress the attestation before forwarding", "To find the block root for deduplication"], "why": "Most attestations are dropped as non partner, so extracting just the attester index and slot from the raw bytes saves a full decode on each of them."},
    {"id": "g_pairedmode", "tag": "gateway", "src": "gateway", "q": "When a Gateway is paired with a Hermes node or a relay instead of a partner, what does it stop forwarding back to its CL?", "a": ["Beacon blocks", "Attestations", "Both blocks and attestations", "Only aggregated attestations"], "why": "Attestation forwarding to the CL is identical in every pairing mode. Only beacon block re forwarding differs, and it is off for Hermes and relay pairings."},
    {"id": "g_reduce98", "tag": "stress", "src": "gateway", "q": "By roughly how much did validator scoped filtering cut the Gateway's attestation traffic on mump2p?", "a": ["About 98 percent", "About 50 percent", "About 25 percent", "About 10 percent"], "why": "Publishing only partner attestations instead of everything drops mump2p attestation traffic by about 98 percent while still covering every partner validator.", "vol": true},
    {"id": "g_window48", "tag": "mainnet", "src": "gateway", "q": "Within a 12 second Ethereum slot, during which window does the Gateway's aggregator emit attestations into mump2p?", "a": ["From 4 seconds to 8 seconds into the slot", "From 0 to 2 seconds into the slot", "From 8 to 12 seconds into the slot", "During the entire slot"], "why": "The gate opens at four seconds, after the block propagation window, and closes at eight, Ethereum's aggregation deadline, when late attestations stop being useful.", "vol": true},
    {"id": "g_gatewhy", "tag": "gateway", "src": "gateway", "q": "What is the reasoning behind the Gateway's slot aware attestation publish gate?", "a": ["Latency critical blocks and bandwidth heavy attestations should not compete", "Attestations are invalid before four seconds", "The mesh cannot carry two topics at once", "Validators sleep during the first part of the slot"], "why": "Blocks need the first seconds of the slot for themselves. Holding attestation batches until the block window has passed keeps them from contending for mesh capacity."},
    {"id": "g_jitterremoved", "tag": "gateway", "src": "gateway", "q": "Why was the per gateway jitter on the attestation publish gate removed in 2026?", "a": ["Validator scoping means each gateway publishes a disjoint slice, so no burst remains", "Jitter broke the fork digest handshake between gateways and Bootstrap", "Gateways in different regions could not agree on the slot start time", "The mump2p mesh now enforces its own rate limit, making jitter redundant"], "why": "Jitter was meant to spread a fleet wide burst of identical attestation sets. Once each gateway only publishes its own validators, that burst no longer exists."},
    {"id": "g_gate4s", "tag": "mainnet", "src": "gateway", "q": "Why was 4 seconds chosen as the opening of the Gateway's attestation publish window?", "a": ["It aligns with Ethereum's attestation deadline, one third of a slot", "It is half of the block propagation window", "It matches the gossipsub heartbeat interval", "It is when the next proposer is chosen"], "why": "Validators are expected to attest one third of the way into the 12 second slot, so by four seconds the block has typically propagated and attestations begin.", "vol": true},
    {"id": "g_samesource", "tag": "shard", "src": "gateway", "q": "Why does the Gateway's attestation synchronization ADR want partner gateways to emit byte identical payloads?", "a": ["RLNC benefits when multiple senders encode the same source message", "SSZ requires identical payloads to decode", "Bootstrap rejects differing hashes", "It reduces the size of each attestation"], "why": "Network coding can exploit overlap only when senders code the same source bytes. Slightly different encodings of the same attestations look like different messages.", "vol": true},
    {"id": "g_chunkdeadline", "tag": "gateway", "src": "gateway", "q": "In deterministic attestation chunking, what happens when a chunk's deadline arrives before every validator has contributed?", "a": ["The gateway publishes the best partial chunk it has", "The chunk is discarded entirely", "The gateway waits until the next slot", "Bootstrap fills in the missing signatures"], "why": "A deadline keeps the design latency safe: one slow or missing validator cannot hold back the rest of the chunk, so a partial canonical chunk goes out.", "vol": true},
    {"id": "g_streamoptin", "tag": "gateway", "src": "gateway", "q": "How is the Gateway's consumer block stream API shipped by default?", "a": ["Opt in, read only and off by default", "Enabled on all interfaces", "Enabled but write capable", "Only available on mainnet"], "why": "The consumer stream is an optional feature operators turn on deliberately, and consumers can only read block events, never publish into the mesh."},
    {"id": "g_ringbuf", "tag": "gateway", "src": "gateway", "q": "What happens when a Gateway stream consumer's ring buffer overflows?", "a": ["The event is dropped and a lagged frame reports the drop count", "The gateway pauses ingest until the consumer catches up", "The oldest event is resent later", "The connection is closed immediately"], "why": "Each subscriber has a bounded ring buffer. On overflow the hub drops the incoming event, counts it, and sends a lagged frame so the consumer knows it missed data."},
    {"id": "g_rawverify", "tag": "gateway", "src": "gateway", "q": "Which Gateway stream mode lets a consumer check the proposer signature of a block itself?", "a": ["Raw mode, which carries the verbatim SSZ snappy block", "Metadata mode, which carries the state root", "Both modes equally", "Neither, verification needs Bootstrap"], "why": "Raw mode delivers the actual signed beacon block bytes, so a consumer holding beacon state can verify it. Metadata mode only carries gateway assertions."},
    {"id": "g_heartbeatsrc", "tag": "gateway", "src": "gateway", "q": "Where is the Gateway stream's heartbeat frame generated?", "a": ["In each transport's send loop, never in the hub", "In the broadcast hub with the block events", "On the Bootstrap service", "Inside the consensus client"], "why": "A hub sourced heartbeat could be dropped by a full ring buffer exactly when liveness proof matters, and would fire a false lagged frame, so each transport sends its own."},
    {"id": "g_slotlist", "tag": "gateway", "src": "gateway", "q": "In the slot based acceleration design, how does a Gateway decide which beacon blocks go on the Optimum fast path?", "a": ["Bootstrap publishes a list of slot numbers that the gateway polls", "The gateway inspects the block's transaction count", "Partners toggle acceleration per block in the console", "The CL client marks blocks for acceleration"], "why": "The selection is made centrally and only slot numbers are shared, so gateways are armed before a block exists and never learn why a slot was chosen.", "vol": true},
    {"id": "g_toslotfail", "tag": "gateway", "src": "gateway", "q": "What does a Gateway do with a block whose slot lies beyond the horizon of its acceleration list?", "a": ["Treats it as unknown and accelerates it", "Drops it until the list is refreshed", "Propagates it normally without acceleration", "Asks Bootstrap for a verdict synchronously"], "why": "Past the list's horizon everything reads as unknown, and unknown fails open to accelerating, which is today's behaviour, so a stale list can never silently switch acceleration off.", "vol": true},
    {"id": "g_hoodivalidate", "tag": "hoodi", "src": "gateway", "q": "Why does the slot acceleration ADR want the feature validated on Hoodi before wider use?", "a": ["Shard distribution and peer scoring were tuned on all blocks traffic", "Hoodi has no MEV relays, so block timing is simpler to measure there", "Mainnet gateways cannot poll Bootstrap for the slot list yet", "Hoodi slots are shorter, so a stale list expires much faster"], "why": "Accelerating only some slots cuts mesh block volume. The mesh's shard distribution and peer scoring were tuned with every block flowing, so Hoodi is the safe test bed.", "vol": true},
    {"id": "g_joinkey", "tag": "gateway", "src": "gateway", "q": "With Gateway self enrollment, what does the enrollment response contain?", "a": ["A client ID and no secret", "A fresh per host API key", "The org's join key", "A signed copy of the private key"], "why": "The gateway generates its own keypair, proves it holds the private half, and receives only a client ID. No gateway secret is transmitted or stored server side."},
    {"id": "g_revokejoin", "tag": "gateway", "src": "gateway", "q": "What happens to already enrolled Gateways when an operator revokes the org join key?", "a": ["They keep working with their own independent credentials", "They are logged out at the next token mint", "They must re enroll within three hours", "They fall back to the legacy API key"], "why": "Revoking a join key only stops future enrollments. Each enrolled gateway holds its own credential, which has to be revoked separately if needed."},
    {"id": "g_sepoliadefault", "tag": "hoodi", "src": "ethnets", "q": "Which public Ethereum testnet is the recommended default for application development?", "a": ["Sepolia", "Hoodi", "Holesky", "Ephemery"], "why": "Sepolia serves contract and app developers, while Hoodi is where protocol developers test upgrades and stakers test validators.", "vol": true},
    {"id": "g_hoodimetro", "tag": "hoodi", "src": "ethnets", "q": "The Hoodi testnet is named after a metro station in which city?", "a": ["Bengaluru, India", "Athens, Greece", "Prague, Czech Republic", "Singapore"], "why": "Ethereum testnets are traditionally named after metro stations in cities where contributors have lived. Hoodi is a station in Bengaluru."},
    {"id": "g_holeskydep", "tag": "hoodi", "src": "ethnets", "q": "Which Ethereum testnet, deprecated in September 2025, were staking operators told to replace with Hoodi for validator testing?", "a": ["Holesky", "Goerli", "Sepolia", "Ropsten"], "why": "Holesky was deprecated in September 2025, and staking operators and infrastructure providers were told to use Hoodi for validator testing instead.", "vol": true},
    {"id": "g_hoodicost", "tag": "hoodi", "src": "ethnets", "q": "What downside does ethereum.org list for running a node on the Hoodi testnet?", "a": ["Longer to sync and more storage required", "No block explorer is available", "The validator set is closed", "It resets every month"], "why": "Hoodi carries a large state, which is useful for complex contract testing but means longer sync times and more disk than smaller testnets."},
    {"id": "g_twoclients", "tag": "gateway", "src": "clients", "q": "According to ethereum.org, how many clients must an Ethereum node run, and which?", "a": ["Two: a consensus client and an execution client", "One combined client", "Three: execution, consensus and relay", "Two: a light client and an archive client"], "why": "A node pairs an execution client, which runs transactions, with a consensus client, which runs proof of stake. The Gateway peers with the consensus side."},
    {"id": "g_nimbuslang", "tag": "gateway", "src": "clients", "q": "Which consensus client is written in the Nim language?", "a": ["Nimbus", "Lighthouse", "Lodestar", "Grandine"], "why": "Nimbus is written in Nim and designed for resource efficiency, which is why it runs comfortably on small devices as well as enterprise hardware."},
    {"id": "g_tekuteam", "tag": "gateway", "src": "clients", "q": "Which team develops the Teku consensus client, and which execution client does it also maintain?", "a": ["The ConsenSys Protocols team, which also builds Besu", "Sigma Prime, which also builds Lighthouse", "Paradigm, which also builds Reth", "Offchain Labs, which also builds Prysm"], "why": "Teku comes from the Protocols team at ConsenSys, the same team responsible for the Besu execution client and Web3Signer."},
    {"id": "g_checkpointsync", "tag": "gateway", "src": "clients", "q": "By what other name is checkpoint sync for a beacon node known?", "a": ["Weak subjectivity sync", "Snap sync", "Optimistic sync", "Light sync"], "why": "Checkpoint sync starts the beacon chain from a recent weak subjectivity checkpoint instead of genesis, making the initial sync much faster."},
    {"id": "g_gossipsubv1", "tag": "mesh", "src": "netlayer", "q": "Which protocol carries the consensus layer's gossip domain, including beacon blocks and attestations?", "a": ["libp2p gossipsub v1", "DevP2P wire protocol", "Discv4 over UDP", "Whisper"], "why": "Everything that must spread fast on the consensus layer, blocks, attestations, exits and slashings, travels over libp2p gossipsub, the mesh the Gateway subscribes to."},
    {"id": "g_eth2key", "tag": "gateway", "src": "netlayer", "q": "What does the eth2 key in a consensus node's ENR tell its peers?", "a": ["Which Ethereum fork version the node is on", "The node's validator public key", "How many attestation subnets it serves", "Its geographic region"], "why": "The eth2 key carries fork version information, so peers only connect to nodes on the right Ethereum, which is why the Gateway resolves a fork digest at startup."},
    {"id": "g_sszoffsets", "tag": "gateway", "src": "netlayer", "q": "Why does the consensus client prefer SSZ over RLP, according to ethereum.org?", "a": ["Fixed offsets let it decode parts of a message without decoding the whole", "SSZ messages are always smaller than RLP", "RLP cannot encode lists", "SSZ is required by the execution layer"], "why": "SSZ's fixed offsets let a client grab specific fields cheaply, exactly what the Gateway does when it peeks at an attestation before a full decode."},
    {"id": "g_engineapi", "tag": "gateway", "src": "netlayer", "q": "How do an Ethereum execution client and consensus client talk to each other?", "a": ["Over a local RPC connection using the Engine API", "Over the gossipsub mesh", "Through a shared database file", "Through the discovery protocol"], "why": "The two clients sit on one machine and exchange instructions and payloads over a local RPC connection whose instructions are defined by the Engine API."},
    // batch H: written from the corpus snapshot of 2026-10-02, every answer backed by a verbatim passage of its source
    {"id": "h_floodsub", "tag": "flood", "src": "gossipsub", "q": "In the Gossipsub specification, how does floodsub, the earliest libp2p pubsub router, propagate a message?", "a": ["Every peer broadcasts it to every other peer it knows in the topic", "Each peer forwards it to a random subset of six peers", "Only the publisher sends it, directly to all subscribers", "Peers announce message ids and wait for requests"], "why": "Floodsub simply floods: each peer sends the message to all known peers in the topic. It is simple and fast, but it wastes bandwidth."},
    {"id": "h_floodproblem", "tag": "flood", "src": "gossipsub", "q": "In the Gossipsub specification, what is the core problem with floodsub's flooding strategy?", "a": ["The outbound degree of the network is unbounded", "Messages take only the slowest paths", "Peers must keep a large routing table", "It cannot work without a central tracker"], "why": "Flooded messages follow every edge, so a peer's outbound degree is unbounded. Gossipsub bounds that degree to cut bandwidth and improve scaling."},
    {"id": "h_gsfix", "tag": "mesh", "src": "gossipsub", "q": "In the Gossipsub specification, how does gossipsub fix the key shortcomings of floodsub?", "a": ["By bounding each peer's outbound degree and controlling amplification globally", "By replacing gossip with a central relay that forwards messages for each topic", "By compressing every message and its control data before forwarding it", "By limiting each topic to a fixed number of publishers chosen at startup"], "why": "Gossipsub peers forward to a bounded subset of peers, the mesh, so the amplification factor is controlled across the whole overlay."},
    {"id": "h_bidir", "tag": "mesh", "src": "gossipsub", "q": "In the Gossipsub specification, what happens when a peer receives a GRAFT telling it that it was added to another peer's mesh?", "a": ["It adds that peer to its own mesh too, if still subscribed", "It replies with an IHAVE listing recent messages", "It removes the sender from its fanout set", "It forwards the GRAFT to its other mesh peers"], "why": "Mesh links are bidirectional. If A is in B's mesh, B is also in A's mesh, so a GRAFT is answered by grafting back."},
    {"id": "h_dlazy", "tag": "mesh", "src": "gossipsub", "q": "In the Gossipsub v1.0 specification, what is the default value of the optional D_lazy parameter, the degree for gossip emission?", "a": ["The same as D", "Half of D", "Always 3", "D_high plus one"], "why": "D_lazy lets you tune lazy gossip separately from eager forwarding, but by default the spec simply reuses D for both.", "vol": true},
    {"id": "h_heartbeat3", "tag": "mesh", "src": "gossipsub", "q": "In the Gossipsub specification, which three functions does the periodic heartbeat serve?", "a": ["Mesh maintenance, fanout maintenance and gossip emission", "Peer discovery, message validation and signing", "Topic subscription, score decay and blacklisting", "Connection setup, encryption and compression"], "why": "Once per heartbeat a peer repairs its mesh sizes, refreshes fanout peers, and emits IHAVE gossip to peers outside the mesh."},
    {"id": "h_fanoutttl", "tag": "mesh", "src": "gossipsub", "q": "In the Gossipsub v1.0 specification, what is the reasonable default for fanout_ttl, the time fanout state is kept for a topic?", "a": ["60 seconds", "5 seconds", "10 minutes", "1 hour"], "why": "If a peer does not publish to a topic within fanout_ttl, the fanout peers for that topic are discarded. The default is 60 seconds.", "vol": true},
    {"id": "h_seenttl", "tag": "flood", "src": "gossipsub", "q": "In the Gossipsub v1.0 specification, what is the reasonable default for seen_ttl, how long seen message ids are remembered?", "a": ["Two minutes", "Ten seconds", "One hour", "One heartbeat"], "why": "The seen cache should outlast the propagation delay of the overlay with a healthy margin, so the spec suggests two minutes.", "vol": true},
    {"id": "h_seencache", "tag": "flood", "src": "gossipsub", "q": "In the Gossipsub specification, why does every pubsub implementation check the seen cache before forwarding a message?", "a": ["To avoid wastefully republishing the same message multiple times", "To keep full message bodies available for a week of replays", "To rank peers by how quickly they delivered earlier messages", "To encrypt each message with a fresh key before sending it on"], "why": "Checking the seen cache before forwarding stops a peer from sending the same message again and again, which is exactly the duplicate waste of flooding."},
    {"id": "h_fanoutmap", "tag": "mesh", "src": "gossipsub", "q": "In the Gossipsub specification, what does the fanout map hold, in contrast to the mesh map?", "a": ["Peers for topics the router is not subscribed to", "Peers that failed validation recently", "Backup peers for every subscribed topic", "Peers reachable only through relays"], "why": "Fanout lets a peer publish into topics it has not joined. The fanout map records the peers it sends to for those unsubscribed topics."},
    {"id": "h_piggyback", "tag": "flood", "src": "gossipsub", "q": "In the Gossipsub specification, how can gossip and other control messages be sent to reduce the message rate?", "a": ["Piggybacked on any other message in the regular flow", "Only in a dedicated control channel per topic", "Batched once per minute in a single packet", "Sent exclusively during the heartbeat"], "why": "Control messages can be coalesced and ride along with regular messages for any topic, which cuts message rate for densely connected peers."},
    {"id": "h_dhighrandom", "tag": "mesh", "src": "gossipsub", "q": "In the Gossipsub v1.0 specification, how does a peer choose which mesh peers to drop when a topic mesh grows above D_high?", "a": ["It randomly selects peers for removal", "It drops the peers with the oldest connections", "It drops the peers with the highest latency", "It drops the most recently grafted peers"], "why": "In v1.0 pruning on oversubscription is random: the peer removes enough randomly chosen peers to get back down to D. Scoring only arrives in v1.1."},
    {"id": "h_discovery", "tag": "mesh", "src": "gossipsub", "q": "In the Gossipsub specification, which peer discovery mechanism does the spec prescribe for finding pubsub peers?", "a": ["None; discovery is assumed to be provided by the environment", "Random walks through the libp2p Kademlia DHT, and nothing else", "MulticastDNS announcements on the local network only", "A tracker run by the creator of each topic"], "why": "Gossipsub relies on ambient peer discovery. The spec deliberately leaves the mechanism to the application and its libp2p environment."},
    {"id": "h_protostr", "tag": "mesh", "src": "gossipsub11", "q": "In the Gossipsub v1.1 specification, which protocol string do peers advertise to signal they support the v1.1 extensions?", "a": ["/meshsub/1.1.0", "/gossipsub/1.1.0", "/floodsub/1.1.0", "/pubsub/v1.1"], "why": "Gossipsub keeps its historical meshsub protocol id, so v1.1 peers advertise /meshsub/1.1.0 while staying backwards compatible with v1.0.", "vol": true},
    {"id": "h_explicitgraft", "tag": "mesh", "src": "gossipsub11", "q": "In the Gossipsub v1.1 specification, what should happen if a peer tries to GRAFT an explicit (direct) peer?", "a": ["It is an error; the attempt is logged and rejected with a PRUNE", "The explicit peer joins the mesh with top priority", "The GRAFT is accepted but scored negatively", "The explicit peering is silently cancelled"], "why": "Explicit peers live outside the mesh and always receive new messages anyway, so grafting them makes no sense and is refused."},
    {"id": "h_px", "tag": "mesh", "src": "gossipsub11", "q": "In the Gossipsub v1.1 specification, what does Peer Exchange add to a PRUNE sent because of oversubscription?", "a": ["A set of other peers the pruned peer can connect to", "A list of recent message ids to fetch", "The pruning peer's full score table", "A signed request to unsubscribe from the topic"], "why": "Instead of just telling a peer to go away, the pruning peer may hand it other peers so it can rebuild its mesh without an external discovery service."},
    {"id": "h_backoff", "tag": "mesh", "src": "gossipsub11", "q": "In the Gossipsub v1.1 specification, what is the recommended backoff period before two peers may regraft after a PRUNE?", "a": ["1 minute", "1 second", "10 minutes", "1 hour"], "why": "Both the pruning and the pruned peer wait out the backoff before regrafting, and the spec also recommends exchanging more peers than D_hi.", "vol": true},
    {"id": "h_floodpub", "tag": "flood", "src": "gossipsub11", "q": "In the Gossipsub v1.1 specification, what is the main reason flood publishing sends a peer's own messages to all known topic peers?", "a": ["To counter eclipse attacks so an honest message reaches all honest peers", "To reduce the size of the message cache kept at every peer", "To let unsubscribed peers skip validation of new messages", "To avoid the cost of exchanging signed peer records"], "why": "With flood publishing, the mesh carries other peers' messages but your own go to every known peer, so an attacker surrounding you cannot swallow them."},
    {"id": "h_gossipfactor", "tag": "flood", "src": "gossipsub11", "q": "In the Gossipsub v1.1 specification, what is the recommended gossip factor, the share of peers that receive gossip each heartbeat?", "a": ["0.25", "0.5", "0.1", "1.0"], "why": "With a 0.25 gossip factor and 3 rounds of gossip per message, each peer has better than a 50% chance of hearing gossip about any message.", "vol": true},
    {"id": "h_dout", "tag": "mesh", "src": "gossipsub11", "q": "In the Gossipsub v1.1 specification, how must the outbound quota parameter D_out relate to the other degree parameters?", "a": ["Below D_lo and at most D/2", "Equal to D_hi", "Above D but below D_hi", "Exactly D_lo"], "why": "D_out guarantees some mesh peers are connections you opened yourself, so an inbound Sybil flood cannot take over your whole mesh."},
    {"id": "h_scorelocal", "tag": "mesh", "src": "gossipsub11", "q": "In the Gossipsub v1.1 specification, who computes a peer's score and who can see it?", "a": ["Each peer computes it locally from observed behaviour; it is not shared", "A bootstrapper computes it and gossips it to every peer in the topic", "Peers vote on it and publish the agreed result on the topic", "The application server assigns it and signs it for everyone to read"], "why": "Scoring is purely local. A peer judges its neighbors from what it sees, and that judgement never leaves the peer."},
    {"id": "h_oppgraft", "tag": "mesh", "src": "gossipsub11", "q": "In the Gossipsub v1.1 specification, what triggers opportunistic grafting?", "a": ["The median score of mesh peers dropping below a threshold", "A new peer connecting with a signed peer record", "The mesh size falling below the D_low threshold", "An IWANT request that was never answered by a peer"], "why": "If the mesh median score sinks below OpportunisticGraftThreshold, the router grafts at least two better scoring peers to escape a poor or Sybil heavy mesh."},
    {"id": "h_extval", "tag": "flood", "src": "gossipsub11", "q": "In the Gossipsub v1.1 specification, what does the \"Ignore\" outcome of an extended validator do with a message?", "a": ["Neither delivers nor forwards it, without triggering the invalid message penalty", "Forwards it to the network but does not deliver it to the application", "Delivers it to the application and applies the invalid message penalty", "Queues it locally until the node has finished syncing its chain"], "why": "Ignore is for cases like duplicate beacon messages or syncing nodes: drop the message quietly without punishing the sender."},
    {"id": "h_graftunknown", "tag": "flood", "src": "gossipsub11", "q": "In the Gossipsub v1.1 specification, how does a router treat a GRAFT for a topic it does not know, as a spam protection measure?", "a": ["It ignores it, whereas v1.0 always replied with a PRUNE", "It replies with a PRUNE carrying peer exchange data", "It subscribes to the topic automatically", "It graylists the sender immediately"], "why": "Replying to every unknown GRAFT with a PRUNE let spammers burn resources, so v1.1 simply ignores such GRAFTs."},
    {"id": "h_bootstrap", "tag": "mesh", "src": "gossipsub11", "q": "In the Gossipsub v1.1 recommendations, how should dedicated bootstrapper nodes be configured?", "a": ["Without a mesh (D set to 0) and with Peer Exchange enabled", "With a very large mesh of at least 64 peers", "As ordinary subscribers with default parameters", "With flood publishing disabled and gossip turned off"], "why": "Bootstrappers act purely as gossip and peer exchange nodes, so they run with D=D_lo=D_hi=D_out=0 and hand out signed peer records."},
    {"id": "h_pubsubname", "tag": "flood", "src": "libp2ppubsub", "q": "According to the libp2p pubsub overview, why is gossipsub called gossipsub?", "a": ["Peers gossip to each other about which messages they have seen", "Messages are spread as rumors with no sender identity", "Every message is sent to a random stranger peer", "It was first used by a chat app called Gossip"], "why": "The name comes from the gossip of metadata: peers tell each other which messages they have seen and use that to keep the delivery network healthy."},
    {"id": "h_grafting", "tag": "mesh", "src": "libp2ppubsub", "q": "According to the libp2p pubsub overview, what is \"grafting\" a peering?", "a": ["Converting a metadata only connection into a full message peering", "Opening a brand new network connection to a previously unknown peer", "Merging two separate topics into one shared topic", "Pinning a peer so that it can never be pruned from the mesh"], "why": "Peerings come in two types. Grafting upgrades a metadata only link to full message; pruning is the reverse."},
    {"id": "h_fanoutuni", "tag": "mesh", "src": "libp2ppubsub", "q": "According to the libp2p pubsub overview, how do fan out peerings differ in direction from other peerings?", "a": ["They are unidirectional, pointing from the outside peer into the topic", "They are bidirectional, exactly like full message and metadata only peerings", "They point from subscribers inside the topic out to the publisher", "They have no direction at all because they carry only metadata"], "why": "A publisher outside a topic picks fan out peers inside it. Those peers are not told and treat the link as ordinary metadata only."},
    {"id": "h_msgid", "tag": "flood", "src": "libp2ppubsub", "q": "According to the libp2p pubsub overview, which two pieces of information are enough to uniquely identify any pubsub message?", "a": ["The sender and the sequence number", "The topic name and a timestamp", "The message hash and its size", "The publisher's IP address and port"], "why": "A peer's recently seen cache stores sender plus sequence number per message, which is enough to spot and ignore retransmissions."},
    {"id": "h_butterfly", "tag": "shard", "src": "wikinc", "q": "In the classic butterfly network example of network coding, how many time slots does coding need to deliver A and B to both sinks, versus four with routing?", "a": ["Three", "Two", "Four", "Five"], "why": "Sending A+B over the shared middle link lets each sink subtract what it already has, so both learn A and B in three slots instead of four."},
    {"id": "h_ahlswede", "tag": "shard", "src": "wikinc", "q": "In network coding theory, what did Ahlswede et al. prove about the multicast capacity upper bound?", "a": ["It is reachable if intermediate nodes combine the packets they receive", "It can never be reached by any real multicast network", "Plain routing already reaches it in every network", "It holds only for networks with a single sink node"], "why": "Routing alone cannot hit the multicast bound. Letting middle nodes compute combinations of packets, which is network coding, closes the gap."},
    {"id": "h_gauss", "tag": "shard", "src": "wikinc", "q": "In linear network coding, which method do sink nodes use on the matrix of collected coded messages to recover the originals?", "a": ["Gaussian elimination", "Fast Fourier transform", "Huffman decoding", "Viterbi decoding"], "why": "Each coded packet is a linear equation. Stacking them into a matrix and running Gaussian elimination solves for the original packets."},
    {"id": "h_generation", "tag": "shard", "src": "wikinc", "q": "In random linear network coding, what is the \"generation size\"?", "a": ["The number of original packets combined and recombined together", "The size in bytes of one coded packet sent over the network", "The number of hops a coded packet may travel before decoding", "The number of elements in the Galois field used for coefficients"], "why": "The original packets form a block called a generation. Its size sets how many packets get mixed together and how many a receiver needs."},
    {"id": "h_coeffappend", "tag": "shard", "src": "wikinc", "q": "In random linear network coding, why are the coding coefficients appended to each transmitted packet?", "a": ["To keep the code stateless so any node can see how a packet was formed", "To let intermediate routers compress the packet payload further", "To sign the packet so receivers can detect tampering in transit", "To record the full route the packet has taken through the network"], "why": "Carrying the coefficients inside the packet means no node needs shared state; anyone can read how a coded packet was built and recode or decode it."},
    {"id": "h_overhead2", "tag": "shard", "src": "wikinc", "q": "In network coding, with a 32 packet generation over a 256 element field, what overhead do the appended coefficients add to a 1500 byte packet?", "a": ["About 2%", "About 20%", "About 50%", "Under 0.1%"], "why": "32 coefficients of one byte each is 32 bytes on a 1500 byte Ethernet MTU packet, so the often feared coefficient overhead is only about 2%.", "vol": true},
    {"id": "h_lindep16", "tag": "shard", "src": "wikinc", "q": "In random linear network coding over the binary field GF(2), the worst case, how many linearly dependent extra packets per generation are expected?", "a": ["About 1.6", "About 16", "Exactly one", "None at all"], "why": "Random coefficients sometimes repeat combinations. Even in the smallest field this costs only about 1.6 extra packets per generation; in binary 8 it is practically zero.", "vol": true},
    {"id": "h_ltcodes", "tag": "shard", "src": "wikifountain", "q": "In coding theory, which codes were the first practical realization of fountain codes?", "a": ["LT codes", "Raptor codes", "Reed-Solomon codes", "Hamming codes"], "why": "LT codes came first; Raptor and online codes followed and added a precoding stage for linear time encoding and decoding."},
    {"id": "h_optimalfountain", "tag": "shard", "src": "wikifountain", "q": "In coding theory, when is a fountain code called optimal?", "a": ["When any k received encoding symbols recover the k source symbols", "When it never needs more than one retransmission per source symbol", "When its code rate is fixed at exactly one half of the symbols", "When encoding every symbol runs in constant time"], "why": "An optimal fountain code needs no overhead: any k successfully received symbols, whichever ones survived, rebuild the k originals."},
    {"id": "h_raptor", "tag": "shard", "src": "wikifountain", "q": "In coding theory, which family is described as the most efficient fountain codes, with linear time encoding and decoding?", "a": ["Raptor codes", "Tornado codes", "Golay codes", "Turbo codes"], "why": "Raptor codes need only a small constant number of XOR operations per symbol and are standardized in RFC 5053 and, as RaptorQ, RFC 6330.", "vol": true},
    {"id": "h_coupon", "tag": "shard", "src": "wikifountain", "q": "In a broadcast data carousel using a fixed rate erasure code, which classic problem does a receiver missing a symbol face?", "a": ["The coupon collector's problem", "The Byzantine generals problem", "The two generals problem", "The dining philosophers problem"], "why": "With a fixed code the receiver must catch the specific symbols it lacks, like collecting the last coupons. A fountain code makes any new symbol useful."},
    {"id": "h_epidemic", "tag": "flood", "src": "wikigossip", "q": "In distributed systems, a gossip protocol is also known by what other name, after the way it spreads information?", "a": ["Epidemic protocol", "Consensus protocol", "Routing protocol", "Handshake protocol"], "why": "Gossip protocols mimic how an epidemic spreads from person to person, so the terms gossip protocol and epidemic protocol are used interchangeably."},
    {"id": "h_doubling", "tag": "flood", "src": "wikigossip", "q": "In the water cooler analogy for gossip protocols, what happens to the number of people who know a rumor after each round?", "a": ["It roughly doubles", "It grows by one person", "It stays about the same", "It grows by ten people"], "why": "Each round everyone who knows the rumor tells one random person, so the informed group roughly doubles, giving logarithmic spread time."},
    {"id": "h_twostyles", "tag": "flood", "src": "wikigossip", "q": "In gossip protocol theory, how do dissemination (rumor mongering) protocols spread information through a network?", "a": ["By flooding the network, but with bounded worst case loads", "By sending each message to exactly one peer and no more", "Through a central coordinator that picks every route", "Along a single fixed path per message to each node"], "why": "Dissemination protocols still work by flooding the network with information, but they do it in a way that keeps the worst case load on any node bounded."},
    {"id": "h_rsorigin", "tag": "shard", "src": "wikirs", "q": "Reed-Solomon codes were introduced in 1960 by Irving Reed and Gustave Solomon while they were staff at which institution?", "a": ["MIT Lincoln Laboratory", "Bell Labs", "IBM Research", "Stanford Research Institute"], "why": "Reed and Solomon published \"Polynomial Codes over Certain Finite Fields\" from MIT Lincoln Laboratory in 1960."},
    {"id": "h_rshalf", "tag": "shard", "src": "wikirs", "q": "In a Reed-Solomon code, if error locations are unknown, how many erroneous symbols can be corrected relative to the redundant symbols added?", "a": ["Half as many errors as redundant symbols", "As many errors as redundant symbols", "Twice as many errors as redundant symbols", "One error regardless of redundancy"], "why": "Locating an error costs as much as fixing it, so n minus k check symbols correct (n minus k)/2 unknown errors but up to n minus k known erasures."},
    {"id": "h_mds", "tag": "shard", "src": "wikirs", "q": "Reed-Solomon codes reach the Singleton bound on minimum distance. What are codes with this property called?", "a": ["Maximum distance separable (MDS) codes", "Low density parity check codes", "Perfect Hamming codes", "Rateless fountain codes"], "why": "An MDS code has the largest minimum distance possible for its length and dimension, which is why Reed-Solomon codes recover from the most erasures."},
    {"id": "h_burst", "tag": "shard", "src": "wikirs", "q": "For which kind of error pattern is a Reed-Solomon code usually a poor choice compared to a binary code?", "a": ["Random single bit errors", "Long bursts of consecutive errors", "Erasures at known positions", "Errors confined to one symbol"], "why": "Reed-Solomon counts a corrupted symbol as one error no matter how many bits flipped, which suits bursts but wastes power on scattered single bit errors."},
    {"id": "h_advisor", "tag": "hoodi", "src": "wikimedard", "q": "Who supervised Muriel Médard's MIT doctoral dissertation on multiple user time varying wireless channels?", "a": ["Robert G. Gallager", "Claude Shannon", "Nancy Lynch", "Irving S. Reed"], "why": "Médard's 1995 Sc.D. at MIT was supervised by information theory pioneer Robert Gallager."},
    {"id": "h_companies", "tag": "hoodi", "src": "wikimedard", "q": "Muriel Médard is listed as co founder of which three companies?", "a": ["CodeOn, Steinwurf and Chocolate Cloud", "Akamai, Cloudflare and Fastly", "Chainlink, Arbitrum and Optimism", "Qualcomm, Broadcom and Marvell"], "why": "Before Optimum, Médard already brought network coding to industry through CodeOn, Steinwurf and Chocolate Cloud.", "vol": true},
    {"id": "h_kobayashi", "tag": "hoodi", "src": "wikimedard", "q": "In 2022 Muriel Médard won the IEEE Koji Kobayashi Computers and Communications Award for her work on what?", "a": ["A universal decoder", "A quantum repeater", "A new wireless standard", "An optical switch"], "why": "The 2022 Koji Kobayashi award recognized her universal decoder work, alongside her long record in network coding."},
    {"id": "h_blobttl", "tag": "blob", "src": "danksharding", "q": "In Ethereum's danksharding roadmap, how long is blob data kept before it is automatically deleted?", "a": ["About 18 days (4096 epochs)", "Forever, like calldata", "About one hour", "Exactly one epoch"], "why": "Rollups only need the data long enough for provers to check it, so blobs are pruned after 4096 epochs, roughly 18 days, keeping nodes light.", "vol": true},
    {"id": "h_calldata", "tag": "blob", "src": "danksharding", "q": "In Ethereum's danksharding roadmap, where did rollups historically post their transaction data before blobs existed?", "a": ["In CALLDATA on layer 1", "In the beacon state", "In a separate shard chain", "In off chain IPFS storage"], "why": "Calldata is processed by every node and lives on chain forever, which made it expensive; blobs give rollups a cheaper, temporary home for data."},
    {"id": "h_dankname", "tag": "blob", "src": "danksharding", "q": "In Ethereum's danksharding roadmap, where does the name \"Proto Danksharding\" come from?", "a": ["The researchers Protolambda and Dankrad Feist", "A prototype shard chain that was called Dank", "An ancient Greek word for a bundle of data", "The name of the first Proto Danksharding testnet"], "why": "The upgrade is named after the two researchers who proposed it, Protolambda and Dankrad Feist."},
    {"id": "h_blobcount", "tag": "blob", "src": "danksharding", "q": "In Ethereum's danksharding roadmap, how many blobs per block does full Danksharding target, up from six in Proto Danksharding?", "a": ["64", "16", "128", "1024"], "why": "Full Danksharding grows the blob count from 6 to 64, with the remaining work being consensus client changes to handle the larger data.", "vol": true},
    {"id": "h_kzg", "tag": "blob", "src": "danksharding", "q": "In Ethereum's danksharding roadmap, what does KZG stand for?", "a": ["Kate, Zaverucha and Goldberg, its three authors", "Known Zero Guarantee, a property of the proof", "Knowledge Zone Graph, the sampling structure", "Kademlia Zig Zag Gossip, the transport used"], "why": "KZG commitments are named after their three authors and shrink a blob of data into a small cryptographic commitment."},
    {"id": "h_pbswhy", "tag": "blob", "src": "danksharding", "q": "In Ethereum's danksharding roadmap, why does Danksharding require proposer builder separation?", "a": ["So each validator need not compute costly commitments for 32MB of blob data", "So block proposers can censor rollup data they consider unprofitable", "So block builders can skip data availability sampling of blob data", "So home validators can run without a full consensus client"], "why": "Generating KZG commitments for 32MB of blobs is heavy work; builders take it on, and proposers simply pick the most profitable block."},
    {"id": "h_das", "tag": "blob", "src": "danksharding", "q": "In Ethereum's danksharding roadmap, how does data availability sampling let validators verify blobs?", "a": ["Each one randomly samples a few data points rather than the whole blob", "Each one downloads and re executes every blob in full", "One elected validator checks the whole blob for everyone", "Each one trusts the block builder's signature alone"], "why": "Random sampling by many validators gives high confidence the data is available, and any missing data is found quickly so the blob is rejected."},
    {"id": "h_noshard", "tag": "blob", "src": "danksharding", "q": "In Ethereum's danksharding roadmap, what happened to the traditional plan of splitting Ethereum into shard chains?", "a": ["Shard chains were dropped in favor of data sampling across blobs", "Shard chains launch only after full Danksharding is complete", "Shard chains are live today but reserved for rollups", "Shard chains were renamed and became the Hoodi testnet"], "why": "Danksharding does not split the chain. It scales with distributed data sampling across blobs, a model sometimes called data sharding."},
  ];
